async function areCompanyGroupChatsEnabled(companyId: number | null | undefined): Promise<boolean> {
  if (!companyId) return false;
  const setting = await storage.getCompanySetting(companyId, 'inbox_show_group_chats');
  return setting?.value === true;
}

function canAccessGroupConversation(req: any, conversation: any): boolean {
  const user = req.user;
  if (!user || conversation.companyId !== user.companyId) return false;
  if (!conversation.isGroup && !conversation.groupJid) return false;
  if (!['whatsapp', 'whatsapp_unofficial'].includes(conversation.channelType)) return false;
  if (user.isSuperAdmin) return true;
  const permissions = req.userPermissions;
  return permissions?.[PERMISSIONS.VIEW_ALL_CONVERSATIONS] === true ||
    conversation.assignedToUserId === user.id;
}
