const scryptAsync = promisify(scrypt);

function flowRecordToCreatorGraph(flow: { name?: string | null; nodes?: unknown; edges?: unknown; customVariables?: unknown }, overrides?: { nodes?: unknown; edges?: unknown; customVariables?: unknown }): FlowGraphDraft {
  return {
    name: flow.name ?? undefined,
    nodes: (Array.isArray(overrides?.nodes) ? overrides.nodes : Array.isArray(flow.nodes) ? flow.nodes : []) as FlowGraphDraft['nodes'],
    edges: (Array.isArray(overrides?.edges) ? overrides.edges : Array.isArray(flow.edges) ? flow.edges : []) as FlowGraphDraft['edges'],
    customVariables: (Array.isArray(overrides?.customVariables) ? overrides.customVariables : Array.isArray(flow.customVariables) ? flow.customVariables : []) as FlowGraphDraft['customVariables'],
  };
}

async function getCreatorActivationBlockers(flow: { id: number; userId?: number | null; companyId?: number | null; name?: string | null; nodes?: unknown; edges?: unknown; customVariables?: unknown }, overrides?: { nodes?: unknown; edges?: unknown; customVariables?: unknown }) {
  const [creatorBlockers, erpModeBlockers] = await Promise.all([
    aiFlowCreatorPersistenceService.getActivationBlockers(
      flow.id,
      flowRecordToCreatorGraph(flow, overrides),
      { userId: flow.userId, companyId: flow.companyId },
    ),
    getErpModeActivationBlockers(flow, overrides),
  ]);
  return [...creatorBlockers, ...erpModeBlockers];
}

async function getErpModeActivationBlockers(
  flow: { companyId?: number | null; name?: string | null; nodes?: unknown; edges?: unknown; customVariables?: unknown },
  overrides?: { nodes?: unknown; edges?: unknown; customVariables?: unknown },
) {
  if (!flow.companyId) return [];
  const erpBusinessType = await getCompanyErpBusinessType(flow.companyId);
  return validateFlowGraph(flowRecordToCreatorGraph(flow, overrides), {
    mode: 'activation',
    erpBusinessType,
  }).structuralIssues.filter((current) =>
    current.code === 'erp_business_type_mismatch' || current.code === 'invalid_erp_business_type_marker'
  );
}

async function hashPassword(password: string) {
  const salt = randomBytes(16).toString("hex");
  const buf = (await scryptAsync(password, salt, 64)) as Buffer;
  return `${buf.toString("hex")}.${salt}`;
}

async function comparePasswords(supplied: string, stored: string) {
  const [hashed, salt] = stored.split(".");
  const hashedBuf = Buffer.from(hashed, "hex");
  const suppliedBuf = (await scryptAsync(supplied, salt, 64)) as Buffer;
  return timingSafeEqual(hashedBuf, suppliedBuf);
}

function getImageAnalysisErrorStatus(code: ImageAnalysisErrorCode | undefined): number {
  if (code === 'IMAGE_ANALYSIS_DISABLED') return 403;
  if (code === 'IMAGE_ANALYSIS_NOT_FOUND') return 404;
  if (
    code === 'IMAGE_ANALYSIS_INVALID_MESSAGE' ||
    code === 'IMAGE_ANALYSIS_MEDIA_UNAVAILABLE' ||
    code === 'IMAGE_ANALYSIS_MISSING_CREDENTIALS'
  ) return 400;
  if (code === 'IMAGE_ANALYSIS_PROVIDER_FAILED') return 502;
  return 500;
}

const validateBody = (schema: any, body: any) => {
  const result = schema.safeParse(body);
  if (!result.success) {
    throw new Error(`Validation error: ${result.error.message}`);
  }
  return result.data;
};

const LEGACY_FLOW_GRAPH_FIELD_KEYS = ['nodes', 'edges', 'customVariables'] as const;

/** Parses nodes/edges/customVariables when clients send legacy JSON strings; no-op if already objects/arrays. */
function coerceLegacyFlowGraphFields(body: Record<string, unknown>): void {
  for (const key of LEGACY_FLOW_GRAPH_FIELD_KEYS) {
    if (!Object.prototype.hasOwnProperty.call(body, key)) continue;
    const value = body[key];
    if (typeof value === 'string') {
      try {
        body[key] = JSON.parse(value) as unknown;
      } catch {
        throw new Error(`Invalid JSON string for flow field "${key}"`);
      }
    }
  }
}

