  app.use('/api/contacts', whatsappContactSyncRoutes);


  if (!(global as any).flowAssignmentEventEmitter) {
    (global as any).flowAssignmentEventEmitter = new EventEmitter();
  }

  app.get('/public/branding', async (req, res) => {

    try {
      const settings = await storage.getAllAppSettings();


      const brandingSettings = settings.filter(s =>
        s.key === 'branding' ||
        s.key === 'branding_logo' ||
        s.key === 'branding_favicon' ||
        s.key === 'branding_admin_auth_background' ||
        s.key === 'branding_user_auth_background' ||
        s.key === 'auth_background_config'
      );


      res.set('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
      res.set('Pragma', 'no-cache');
      res.set('Expires', '0');
      res.set('Surrogate-Control', 'no-store');
      res.json(brandingSettings);

    } catch (error) {
      res.status(500).json({ error: 'Failed to fetch branding settings' });
    }
  });


  app.get('/public/custom-scripts', async (req, res) => {
    try {
      const customScriptsSetting = await storage.getAppSetting('custom_scripts');

      if (!customScriptsSetting) {
        const defaultConfig = {
          enabled: false,
          scripts: '',
          lastModified: new Date().toISOString()
        };
        res.set('Cache-Control', 'public, max-age=60'); // Cache for 1 minute
        return res.json(defaultConfig);
      }


      const settingValue = customScriptsSetting.value as any;
      const publicConfig = {
        enabled: settingValue?.enabled || false,
        scripts: settingValue?.enabled ? (settingValue?.scripts || '') : '',
        lastModified: settingValue?.lastModified || new Date().toISOString()
      };

      res.set('Cache-Control', 'public, max-age=60'); // Cache for 1 minute
      res.json(publicConfig);
    } catch (error) {
      console.error("Error fetching public custom scripts:", error);
      res.status(500).json({ error: "Failed to fetch custom scripts" });
    }
  });

  app.get('/public/custom-css', async (req, res) => {
    try {
      const customCssSetting = await storage.getAppSetting('custom_css');

      if (!customCssSetting) {
        const defaultConfig = {
          enabled: false,
          css: '',
          lastModified: new Date().toISOString()
        };
        res.set('Cache-Control', 'public, max-age=60'); // Cache for 1 minute
        return res.json(defaultConfig);
      }

      const settingValue = customCssSetting.value as any;
      const publicConfig = {
        enabled: settingValue?.enabled || false,
        css: settingValue?.enabled ? (settingValue?.css || '') : '',
        lastModified: settingValue?.lastModified || new Date().toISOString()
      };

      res.set('Cache-Control', 'public, max-age=60'); // Cache for 1 minute
      res.json(publicConfig);
    } catch (error) {
      console.error("Error fetching public custom CSS:", error);
      res.status(500).json({ error: "Failed to fetch custom CSS" });
    }
  });

  const publicRestaurantQrOrderSchema = z.object({
    guestName: z.string().optional(),
    notes: z.string().optional(),
    idempotencyKey: z.string().trim().min(8).max(128).optional(),
    items: z.array(z.object({
      productId: z.coerce.number().int().positive(),
      quantity: z.coerce.number().positive(),
      description: z.string().optional(),
      sortOrder: z.coerce.number().int().optional(),
    })).min(1),
  });

  async function loadActiveRestaurantQrToken(token: string) {
    const record = await storage.getRestaurantTableQrTokenByValue(token);
    if (!record || !record.isActive) return null;
    if (record.expiresAt && new Date(record.expiresAt).getTime() < Date.now()) return null;
    const table = await storage.getRestaurantTable(record.tableId);
    if (!table || table.companyId !== record.companyId || table.isActive === false) return null;
    return { record, table };
  }

  async function isRestaurantBusinessType(companyId: number): Promise<boolean> {
    const setting = await storage.getCompanySetting(companyId, ERP_BUSINESS_TYPE_SETTING_KEY);
    return normalizeErpBusinessType(setting?.value) === 'restaurant';
  }

  app.get('/api/public/restaurant/qr/:token', async (req: Request, res: Response) => {
    try {
      const tokenState = await loadActiveRestaurantQrToken(req.params.token);
      if (!tokenState) {
        return res.status(404).json({ success: false, error: 'QR token not found or inactive' });
      }
      if (!(await isRestaurantBusinessType(tokenState.record.companyId))) {
        return res.status(403).json({ success: false, error: 'Restaurant QR ordering is unavailable for this company' });
      }
      const [company, categories, productsResult] = await Promise.all([
        storage.getCompany(tokenState.record.companyId),
        storage.getProductCategories(tokenState.record.companyId),
        storage.getProducts(tokenState.record.companyId, { status: 'active', isMenuItem: true, limit: 500 }),
      ]);
      if (!company) {
        return res.status(404).json({ success: false, error: 'Company not found' });
      }
      return res.json({
        success: true,
        data: {
          company: {
            id: company.id,
            name: company.name,
            logo: (company as any).logo ?? (company as any).logoUrl ?? null,
          },
          table: tokenState.table,
          categories,
          products: productsResult.data,
        },
      });
    } catch (error) {
      console.error('Error loading public restaurant QR menu:', error);
      return res.status(500).json({ success: false, error: error instanceof Error ? error.message : String(error) });
    }
  });

  app.post('/api/public/restaurant/qr/:token/order', async (req: Request, res: Response) => {
    try {
      const tokenState = await loadActiveRestaurantQrToken(req.params.token);
      if (!tokenState) {
        return res.status(404).json({ success: false, error: 'QR token not found or inactive' });
      }
      if (!(await isRestaurantBusinessType(tokenState.record.companyId))) {
        return res.status(403).json({ success: false, error: 'Restaurant QR ordering is unavailable for this company' });
      }
      const parsed = publicRestaurantQrOrderSchema.parse(req.body);
      const products = await storage.getProductsByIds(tokenState.record.companyId, parsed.items.map((item) => item.productId));
      const productById = new Map(products.map((product) => [product.id, product]));
      const toLinePayload = (item: (typeof parsed.items)[number], sortOrder: number) => {
        const product = productById.get(item.productId);
        if (
          !product ||
          product.companyId !== tokenState.record.companyId ||
          product.status !== 'active' ||
          product.isMenuItem !== true
        ) {
          throw new Error('Invalid menu item');
        }
        const quantity = Number(item.quantity);
        const unitPrice = Number(product.unitPrice ?? 0);
        const lineTotal = quantity * unitPrice;
        return {
          productId: product.id,
          variantId: null,
          description: item.description ?? product.name,
          quantity: quantity.toFixed(2),
          unitPrice: unitPrice.toFixed(2),
          discountPercent: '0',
          taxRate: '0',
          lineTotal: lineTotal.toFixed(2),
          modifierSelections: [],
          specialInstructions: null,
          sortOrder,
        };
      };
      const subtotal = parsed.items.reduce((sum, item) => {
        const product = productById.get(item.productId);
        if (
          !product ||
          product.companyId !== tokenState.record.companyId ||
          product.status !== 'active' ||
          product.isMenuItem !== true
        ) {
          throw new Error('Invalid menu item');
        }
        return sum + Number(item.quantity) * Number(product.unitPrice ?? 0);
      }, 0);
      const idempotencyKey =
        parsed.idempotencyKey ??
        (typeof req.headers['x-idempotency-key'] === 'string'
          ? req.headers['x-idempotency-key'].trim()
          : undefined);
      const created = await storage.createRestaurantSalesOrderWithContext({
        order: {
          companyId: tokenState.record.companyId,
          orderNumber: '',
          status: 'confirmed',
          source: 'restaurant_qr',
          subtotal: subtotal.toFixed(2),
          taxAmount: '0',
          discountAmount: '0',
          totalAmount: subtotal.toFixed(2),
          currency: 'USD',
          contactId: null,
          dealId: null,
          notes: [parsed.guestName ? `Guest: ${parsed.guestName}` : null, parsed.notes ?? null].filter(Boolean).join(' | ') || null,
          assignedToUserId: null,
          validUntil: null,
          shippingAddress: undefined,
          billingAddress: undefined,
          createdBy: null,
        },
        lineItems: parsed.items.map((item, index) => toLinePayload(item, index)),
        restaurantContext: {
          serviceType: 'dine_in',
          status: 'submitted',
          tableId: tokenState.table.id,
          qrTokenId: tokenState.record.id,
          notes: parsed.notes ?? null,
          createdBy: null,
        },
        qrIdempotencyKey: idempotencyKey,
      });
      return res.json({
        success: true,
        data: {
          orderId: created.order.id,
          orderNumber: created.order.orderNumber,
          message: created.reused
            ? `Order ${created.order.orderNumber} was already submitted for ${tokenState.table.label}.`
            : `Order ${created.order.orderNumber} submitted for ${tokenState.table.label}.`,
        },
      });
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ success: false, error: 'Validation failed', details: error.flatten() });
      }
      console.error('Error creating public restaurant QR order:', error);
      return res.status(500).json({ success: false, error: error instanceof Error ? error.message : String(error) });
    }
  });

  app.get('/api/public/website/:slug', async (req, res) => {
    const { slug } = req.params;

    try {
      if (await rejectLegacyPublicWhenFrontendWebsiteAuthoritative(req, res)) {
        return;
      }

      const website = await storage.getWebsiteBySlug(slug);

      if (!website || website.status !== 'published') {
        return res.status(404).json({ error: 'Website not found' });
      }

      res.json(website);
    } catch (error) {
      console.error('Error fetching website:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  app.get('/api/public/company-page/:prefixedSlug', async (req: Request, res: Response, next: NextFunction) => {
    const { prefixedSlug } = req.params;
    if (!prefixedSlug) return next();
    if (await rejectLegacyPublicWhenFrontendWebsiteAuthoritative(req, res)) {
      return;
    }
    const parts = prefixedSlug.split('-');
    if (parts.length < 2) return next();
    try {
      // Company and page slugs may both contain hyphens; try each possible split
      // (longest company slug first) so e.g. "ns-khan-terms-of-service" → company "ns-khan", page "terms-of-service"
      for (let i = 1; i < parts.length; i++) {
        const companySlug = parts.slice(0, i).join('-');
        const pageSlug = parts.slice(i).join('-');
        const company = await storage.getCompanyBySlug(companySlug);
        if (!company) continue;
        const page = await storage.getCompanyPageBySlug(company.id, pageSlug);
        if (!page || !page.isPublished) continue;
        return res.json({
          id: page.id,
          title: page.title,
          slug: page.slug,
          content: page.content,
          metaTitle: page.metaTitle,
          metaDescription: page.metaDescription,
          metaKeywords: page.metaKeywords,
          customCss: page.customCss,
          customJs: page.customJs,
          status: 'published',
          source: 'company-page'
        });
      }
      return res.status(404).json({ error: 'Page not found' });
    } catch (error) {
      console.error('Error fetching public company page:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  async function getFrontendWebsiteFeatureEnabled(): Promise<boolean> {
    const generalSettings = await storage.getAppSetting('general_settings');
    const settingsValue = generalSettings?.value as { frontendWebsiteEnabled?: boolean } | undefined;
    return settingsValue?.frontendWebsiteEnabled === true;
  }

  function isLegacyPublicCompatRequest(req: Request): boolean {
    const legacy = req.query.legacy;
    return legacy === '1' || legacy === 'true';
  }

  async function rejectLegacyPublicWhenFrontendWebsiteAuthoritative(
    req: Request,
    res: Response
  ): Promise<boolean> {
    if (!(await getFrontendWebsiteFeatureEnabled()) || isLegacyPublicCompatRequest(req)) {
      return false;
    }

    res.set('Cache-Control', 'public, max-age=60');
    res.status(404).json({
      error: 'Legacy public page source is unavailable while the frontend website is enabled. Use /legacy-public/:slug or ?legacy=1 for compatibility.',
    });
    return true;
  }

  async function rejectLegacyPublishedWebsiteWhenFrontendWebsiteAuthoritative(
    req: Request,
    res: Response
  ): Promise<boolean> {
    if (!(await getFrontendWebsiteFeatureEnabled()) || isLegacyPublicCompatRequest(req)) {
      return false;
    }

    res.set('Cache-Control', 'public, max-age=60');
    res.status(404).send(`
      <!DOCTYPE html>
      <html>
        <head>
          <title>Legacy Website Unavailable</title>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
        </head>
        <body>
          <div style="text-align: center; padding: 50px; font-family: Arial, sans-serif;">
            <h1>Legacy Website Unavailable</h1>
            <p>The legacy published website is unavailable while the frontend website is enabled.</p>
            <p>Use <a href="/legacy-website">/legacy-website</a> or append <code>?legacy=1</code> for compatibility access.</p>
          </div>
        </body>
      </html>
    `);
    return true;
  }

  async function serveLegacyPublishedWebsite(res: Response): Promise<void> {
    try {
      const publishedWebsite = await storage.getPublishedWebsite();

      if (!publishedWebsite) {
        res.status(404).send(`
          <!DOCTYPE html>
          <html>
            <head>
              <title>Website Not Found</title>
              <meta charset="utf-8">
              <meta name="viewport" content="width=device-width, initial-scale=1">
            </head>
            <body>
              <div style="text-align: center; padding: 50px; font-family: Arial, sans-serif;">
                <h1>Website Not Found</h1>
                <p>No published website is currently available.</p>
              </div>
            </body>
          </html>
        `);
        return;
      }

      const html = `
        <!DOCTYPE html>
        <html>
          <head>
            <title>${publishedWebsite.metaTitle || publishedWebsite.title}</title>
            <meta charset="utf-8">
            <meta name="viewport" content="width=device-width, initial-scale=1">
            <meta name="description" content="${publishedWebsite.metaDescription || publishedWebsite.description || ''}">
            <meta name="keywords" content="${publishedWebsite.metaKeywords || ''}">
            ${publishedWebsite.favicon ? `<link rel="icon" href="${publishedWebsite.favicon}">` : ''}
            ${publishedWebsite.googleAnalyticsId ? `
              <!-- Google Analytics -->
              <script async src="https://www.googletagmanager.com/gtag/js?id=${publishedWebsite.googleAnalyticsId}"></script>
              <script>
                window.dataLayer = window.dataLayer || [];
                function gtag(){dataLayer.push(arguments);}
                gtag('js', new Date());
                gtag('config', '${publishedWebsite.googleAnalyticsId}');
              </script>
            ` : ''}
            ${publishedWebsite.facebookPixelId ? `
              <!-- Facebook Pixel -->
              <script>
                !function(f,b,e,v,n,t,s)
                {if(f.fbq)return;n=f.fbq=function(){n.callMethod?
                n.callMethod.apply(n,arguments):n.queue.push(arguments)};
                if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version='2.0';
                n.queue=[];t=b.createElement(e);t.async=!0;
                t.src=v;s=b.getElementsByTagName(e)[0];
                s.parentNode.insertBefore(t,s)}(window, document,'script',
                'https://connect.facebook.net/en_US/fbevents.js');
                fbq('init', '${publishedWebsite.facebookPixelId}');
                fbq('track', 'PageView');
              </script>
              <noscript><img height="1" width="1" style="display:none"
                src="https://www.facebook.com/tr?id=${publishedWebsite.facebookPixelId}&ev=PageView&noscript=1"
              /></noscript>
            ` : ''}
            <style>
              ${publishedWebsite.grapesCss || ''}
              ${publishedWebsite.customCss || ''}
            </style>
            ${publishedWebsite.customHead || ''}
          </head>
          <body>
            ${publishedWebsite.grapesHtml || ''}
            <script>
              ${publishedWebsite.grapesJs || ''}
              ${publishedWebsite.customJs || ''}
            </script>
          </body>
        </html>
      `;

      res.set('Cache-Control', 'public, max-age=300');
      res.send(html);
    } catch (error) {
      console.error('Error serving published website:', error);
      res.status(500).send(`
        <!DOCTYPE html>
        <html>
          <head>
            <title>Error</title>
            <meta charset="utf-8">
            <meta name="viewport" content="width=device-width, initial-scale=1">
          </head>
          <body>
            <div style="text-align: center; padding: 50px; font-family: Arial, sans-serif;">
              <h1>Error</h1>
              <p>An error occurred while loading the website.</p>
            </div>
          </body>
        </html>
      `);
    }
  }

  app.get('/website', async (req, res) => {
    if (await rejectLegacyPublishedWebsiteWhenFrontendWebsiteAuthoritative(req, res)) {
      return;
    }
    await serveLegacyPublishedWebsite(res);
  });

  app.get('/legacy-website', async (_req, res) => {
    await serveLegacyPublishedWebsite(res);
  });






