  // IP-based country code for registration (avoids CORS from client)
  app.get('/api/geo/country', async (req: Request, res: Response) => {
    const isPrivateOrLocalIp = (ip: string | undefined): boolean => {
      if (!ip) return true;
      if (ip === '::1' || ip === '127.0.0.1') return true;
      if (ip.startsWith('10.') || ip.startsWith('192.168.')) return true;
      if (ip.startsWith('172.')) {
        const parts = ip.split('.');
        const second = parseInt(parts[1], 10);
        if (second >= 16 && second <= 31) return true;
      }
      return false;
    };
    try {
      const forwarded = req.headers['x-forwarded-for'];
      const clientIp = typeof forwarded === 'string'
        ? forwarded.split(',')[0].trim()
        : (req.ip || (req.socket as any)?.remoteAddress);
      if (!clientIp || isPrivateOrLocalIp(clientIp)) {
        return res.status(200).json({ countryCode: null, geoUnavailable: true });
      }
      const ipinfoToken = process.env.IPINFO_TOKEN || '2f6da3a4e241d0';
      const { data } = await axios.get(`https://ipinfo.io/${clientIp}/json?token=${ipinfoToken}`, { timeout: 2000 });
      const code = data?.country;
      if (typeof code === 'string' && code.length === 2) {
        return res.json({ countryCode: code.toUpperCase() });
      }
      return res.status(200).json({ countryCode: null, geoUnavailable: true });
    } catch {
      return res.status(200).json({ countryCode: null, geoUnavailable: true });
    }
  });

