  app.get('/api/webhooks/messenger', async (req, res) => {
    const mode = req.query['hub.mode'];
    const token = req.query['hub.verify_token'];
    const challenge = req.query['hub.challenge'];



    if (mode !== 'subscribe') {
      return res.status(403).send('Forbidden');
    }

    try {
      const messengerConnections = await storage.getChannelConnectionsByType('messenger');
      const tokenStr = token != null ? String(token) : '';

      let matchingConnection = null;
      for (const connection of messengerConnections) {
        const connectionData = connection.connectionData as any;
        const verifyToken = connectionData?.verifyToken;
        if (verifyToken != null && String(verifyToken) === tokenStr) {
          matchingConnection = connection;
          break;
        }
      }

      const globalToken = process.env.MESSENGER_WEBHOOK_VERIFY_TOKEN;
      const isGlobalMatch = globalToken && token === globalToken;
      const isPartnerConfigMatch = await metaGraphAPI.matchesActiveMetaPartnerWebhookVerifyToken(token);

      if (matchingConnection || isGlobalMatch || isPartnerConfigMatch) {
        res.status(200).send(challenge);
      } else {
        console.warn('[messenger-webhook] Verify token mismatch', {
          endpoint: '/api/webhooks/messenger',
          channel: 'messenger',
          hasMatchingConnection: false,
          hasGlobalMatch: !!isGlobalMatch,
          hasPartnerConfigMatch: !!isPartnerConfigMatch,
        });
        res.status(403).send('Forbidden');
      }
    } catch (error) {
      console.error('Error during Messenger webhook verification:', error);
      res.status(500).send('Internal Server Error');
    }
  });

  app.post('/api/webhooks/messenger',
    express.raw({ type: 'application/json' }),
    async (req, res) => {
    try {
      const signature = req.headers['x-hub-signature-256'] as string;
      const body = req.body;

      if (!Buffer.isBuffer(body)) {
        return res.status(400).send('Invalid request body - expected raw body');
      }

      const rawPayload = body.toString();
      const parsedBody = JSON.parse(rawPayload);

      if (!signature && !isMetaWebhookSignatureBypassAllowed()) {
        console.warn('[messenger-webhook] Rejecting request: missing x-hub-signature-256 header', {
          endpoint: '/api/webhooks/messenger',
          channel: 'messenger',
        });
        return res.status(401).send('Unauthorized');
      }

      let targetConnection = null;
      let pageId: string | null = null;

      if (parsedBody?.entry && Array.isArray(parsedBody.entry) && parsedBody.entry.length > 0) {
        const entry = parsedBody.entry[0];
        if (entry?.messaging && Array.isArray(entry.messaging) && entry.messaging.length > 0) {
          const messaging = entry.messaging[0];
          const recipientId = messaging?.recipient?.id;
          pageId = recipientId != null ? String(recipientId) : (entry?.id != null ? String(entry.id) : null);
        } else if (entry?.id != null) {
          pageId = String(entry.id);
        }

        if (pageId) {
          const messengerConnections = await storage.getChannelConnectionsByType('messenger');

          targetConnection = messengerConnections.find((conn: any) => {
            const connectionData = conn.connectionData as any;
            const connPageId = connectionData?.pageId;
            return connPageId != null && String(connPageId) === pageId;
          });

          if (!targetConnection && messengerConnections.length === 1) {
            targetConnection = messengerConnections[0];
          }

          if (!targetConnection) {
            console.warn('[messenger-webhook] No matching Page connection', {
              entryId: pageId,
              channel: 'messenger',
              companyMatchStatus: 'unmatched',
            });
          }
        }
      }

      if (signature && targetConnection) {
        const connectionData = targetConnection.connectionData as any;
        const appSecret = connectionData?.appSecret;
        const partnerConfig = !appSecret ? await storage.getPartnerConfiguration('meta') : null;
        if (!appSecret && !partnerConfig?.partnerSecret) {
          console.warn('[messenger-webhook] App secret unavailable for signature verification', {
            channel: 'messenger',
            connectionId: targetConnection.id,
            partnerConfigFallbackExists: !!partnerConfig,
          });
        }
      }

      await messengerService.processWebhook(
        parsedBody,
        signature,
        targetConnection?.companyId || undefined,
        targetConnection,
        rawPayload
      );

      res.status(200).send('OK');
    } catch (error) {
      console.error('Error processing Messenger webhook:', error);
      if (
        error instanceof Error &&
        (error.message.includes('x-hub-signature-256') ||
          error.message.includes('webhook signature'))
      ) {
        return res.status(401).send('Unauthorized');
      }
      res.status(500).send('Internal Server Error');
    }
  });

