  app.get('/api/company-settings/auto-add-to-pipeline', ensureAuthenticated, ensureCompanyAdmin, async (req: any, res: Response) => {
    try {
      const companyId = req.user.companyId;
      const setting = await storage.getCompanySetting(companyId, 'autoAddContactToPipeline');
      const value = setting?.value !== undefined ? Boolean(setting.value) : true; // default ON
      const pipelineSetting = await storage.getCompanySetting(companyId, 'autoAddPipelineId');
      const stageSetting = await storage.getCompanySetting(companyId, 'autoAddStageId');
      const parseNumericSetting = (s: Awaited<ReturnType<typeof storage.getCompanySetting>>): number | null => {
        if (!s || s.value === undefined || s.value === null) return null;
        const n = Number(s.value);
        return n && !Number.isNaN(n) ? n : null;
      };
      res.json({
        autoAddContactToPipeline: value,
        autoAddPipelineId: parseNumericSetting(pipelineSetting),
        autoAddStageId: parseNumericSetting(stageSetting),
      });
    } catch (error: any) {
      console.error('Error fetching auto-add to pipeline setting:', error);
      res.status(500).json({ error: error?.message || 'Failed to fetch setting' });
    }
  });

  app.post('/api/company-settings/auto-add-to-pipeline', ensureAuthenticated, ensureCompanyAdmin, async (req: any, res: Response) => {
    try {
      const companyId = req.user.companyId;
      const { autoAddContactToPipeline } = req.body;

      if (autoAddContactToPipeline === undefined) {
        return res.status(400).json({ error: 'autoAddContactToPipeline is required' });
      }

      const { invalidateCompanySettingCache, invalidateCompanySettingNumericCache } = await import('./utils/pipeline-cache');

      const isValidIntSetting = (v: unknown): boolean => {
        if (v === null || v === undefined) return false;
        const n = Number(v);
        return Number.isInteger(n) && Number.isFinite(n);
      };

      const parseNumericSetting = (s: Awaited<ReturnType<typeof storage.getCompanySetting>>): number | null => {
        if (!s || s.value === undefined || s.value === null) return null;
        const n = Number(s.value);
        return n && !Number.isNaN(n) ? n : null;
      };

      const hasPipelineKey = Object.prototype.hasOwnProperty.call(req.body, 'autoAddPipelineId');
      const hasStageKey = Object.prototype.hasOwnProperty.call(req.body, 'autoAddStageId');

      if (hasPipelineKey && req.body.autoAddPipelineId !== null && !isValidIntSetting(req.body.autoAddPipelineId)) {
        return res.status(400).json({ error: 'autoAddPipelineId must be a valid integer or null' });
      }
      if (hasStageKey && req.body.autoAddStageId !== null && !isValidIntSetting(req.body.autoAddStageId)) {
        return res.status(400).json({ error: 'autoAddStageId must be a valid integer or null' });
      }

      if (hasPipelineKey || hasStageKey) {
        let nextPipelineId: number | null;
        if (hasPipelineKey) {
          nextPipelineId = req.body.autoAddPipelineId === null ? null : Number(req.body.autoAddPipelineId);
        } else {
          const s = await storage.getCompanySetting(companyId, 'autoAddPipelineId');
          nextPipelineId = parseNumericSetting(s);
        }

        let nextStageId: number | null;
        if (hasStageKey) {
          nextStageId = req.body.autoAddStageId === null ? null : Number(req.body.autoAddStageId);
        } else {
          const s = await storage.getCompanySetting(companyId, 'autoAddStageId');
          nextStageId = parseNumericSetting(s);
        }

        if (nextStageId !== null && nextPipelineId === null) {
          return res.status(400).json({ error: 'autoAddStageId requires a valid autoAddPipelineId' });
        }

        if (nextPipelineId !== null) {
          const pipelines = await storage.getPipelinesByCompany(companyId);
          if (!pipelines.some((p) => p.id === nextPipelineId)) {
            return res.status(400).json({ error: 'autoAddPipelineId does not exist for this company' });
          }
        }

        if (nextStageId !== null) {
          const stages = await storage.getPipelineStagesByCompany(companyId, nextPipelineId!);
          if (!stages.some((st) => st.id === nextStageId)) {
            return res.status(400).json({ error: 'autoAddStageId does not belong to the selected pipeline' });
          }
        }
      }

      await storage.saveCompanySetting(companyId, 'autoAddContactToPipeline', Boolean(autoAddContactToPipeline));
      invalidateCompanySettingCache(companyId, 'autoAddContactToPipeline');

      if (hasPipelineKey) {
        if (req.body.autoAddPipelineId === null) {
          await storage.saveCompanySetting(companyId, 'autoAddPipelineId', null);
        } else {
          await storage.saveCompanySetting(companyId, 'autoAddPipelineId', Number(req.body.autoAddPipelineId));
        }
        invalidateCompanySettingNumericCache(companyId, 'autoAddPipelineId');
      }

      if (hasStageKey) {
        if (req.body.autoAddStageId === null) {
          await storage.saveCompanySetting(companyId, 'autoAddStageId', null);
        } else {
          await storage.saveCompanySetting(companyId, 'autoAddStageId', Number(req.body.autoAddStageId));
        }
        invalidateCompanySettingNumericCache(companyId, 'autoAddStageId');
      }

      const pipelineSaved = await storage.getCompanySetting(companyId, 'autoAddPipelineId');
      const stageSaved = await storage.getCompanySetting(companyId, 'autoAddStageId');

      res.json({
        message: 'Auto-add to pipeline setting saved successfully',
        autoAddContactToPipeline: Boolean(autoAddContactToPipeline),
        autoAddPipelineId: parseNumericSetting(pipelineSaved),
        autoAddStageId: parseNumericSetting(stageSaved),
      });
    } catch (error: any) {
      console.error('Error saving auto-add to pipeline setting:', error);
      res.status(500).json({ error: error?.message || 'Failed to save setting' });
    }
  });

