  app.post('/api/company-settings/deal-automation-rules', ensureAuthenticated, ensureCompanyAdmin, async (req: any, res: Response) => {
    try {
      const companyId = req.user.companyId;
      const { dealAutomationRulesEnabled, rules } = req.body;

      if (typeof dealAutomationRulesEnabled !== 'boolean') {
        return res.status(400).json({ error: 'dealAutomationRulesEnabled must be a boolean' });
      }

      if (!Array.isArray(rules)) {
        return res.status(400).json({ error: 'rules must be an array' });
      }

      const { invalidateCompanySettingCache } = await import('./utils/pipeline-cache');

      // Load company pipelines and stages for validation
      const companyPipelines = await storage.getPipelinesByCompany(companyId);
      const companyStages: any[] = [];
      for (const p of companyPipelines) {
        const stages = await storage.getPipelineStagesByCompany(companyId, p.id);
        companyStages.push(...stages);
      }

      // Validate and normalize all rules before writing anything
      const normalizedRules = rules.map((rule: any, index: number) => {
        const validated = validateDealAutomationRule(rule, companyPipelines, companyStages);
        return {
          ...validated,
          priority: index
        };
      });

      // Save the toggle
      await storage.saveCompanySetting(companyId, 'dealAutomationRulesEnabled', dealAutomationRulesEnabled);
      invalidateCompanySettingCache(companyId, 'dealAutomationRulesEnabled');

      // Save the rules
      const savedRules = await storage.replaceDealAutomationRules(companyId, normalizedRules);

      // Invalidate the service cache
      dealAutomationService.invalidateDealAutomationRulesCache(companyId);

      res.json({
        message: 'Deal automation rules saved successfully',
        dealAutomationRulesEnabled,
        rules: savedRules
      });
    } catch (error: any) {
      console.error('Error saving deal automation rules:', error);
      res.status(400).json({ error: error?.message || 'Failed to save rules' });
    }
  });

