  app.post('/api/conversations/:id/assign', ensureAuthenticated, requirePermission(PERMISSIONS.ASSIGN_CONVERSATIONS), async (req, res) => {
    try {
      const conversationId = parseInt(req.params.id);
      const { agentId, forceAssign } = req.body;
      const user = req.user as any;

      if (isNaN(conversationId)) {
        return res.status(400).json({ error: 'Invalid conversation ID' });
      }

      const conversation = await storage.getConversation(conversationId);
      if (!conversation) {
        return res.status(404).json({ error: 'Conversation not found' });
      }
      if (conversation.isGroup || conversation.groupJid) {
        return res.status(400).json({ error: 'Assignments are not supported for WhatsApp group conversations' });
      }

      if (conversation.companyId !== null && conversation.companyId !== user.companyId) {
        return res.status(403).json({ error: 'Access denied' });
      }

      if (conversation.companyId === null) {
        await storage.updateConversation(conversationId, {
          companyId: user.companyId
        });
      }

      if (agentId) {
        const agent = await storage.getUser(agentId);
        if (!agent || agent.companyId !== user.companyId) {
          return res.status(400).json({ error: 'Invalid agent or agent not in same company' });
        }

        const availabilityEnabled = await isInboxAvailabilityEnabled(user.companyId);
        if (availabilityEnabled && forceAssign !== true) {
          const availability = await evaluateAgentAvailability(user.companyId, agentId);
          if (!availability.available) {
            return res.status(409).json({
              error: 'Agent is not currently available',
              code: 'AGENT_UNAVAILABLE',
              availabilityReason: availability.reason,
              nextAvailableAt: availability.nextAvailableAt,
            });
          }
        }

      }

      const updatedConversation = await storage.updateConversation(conversationId, {
        assignedToUserId: agentId || null
      });

      if (agentId) {
        conversationMetricsService.recordAssignment(conversationId, agentId, new Date())
          .catch(e => console.error('[metrics] recordAssignment failed:', e));
      }

      broadcastToAll({
        type: 'conversationAssigned',
        data: {
          conversationId,
          agentId: agentId || null,
          assignedBy: user.id,
          conversation: updatedConversation
        }
      }, user.companyId);

      await broadcastConversationUpdate(updatedConversation, 'conversationUpdated');

      res.json(updatedConversation);
    } catch (error) {
      console.error('Error assigning conversation:', error);
      res.status(500).json({ error: 'Failed to assign conversation' });
    }
  });

  app.delete('/api/conversations/:id/assign', ensureAuthenticated, requirePermission(PERMISSIONS.ASSIGN_CONVERSATIONS), async (req, res) => {
    try {
      const conversationId = parseInt(req.params.id);
      const user = req.user as any;

      if (isNaN(conversationId)) {
        return res.status(400).json({ error: 'Invalid conversation ID' });
      }

      const conversation = await storage.getConversation(conversationId);
      if (!conversation) {
        return res.status(404).json({ error: 'Conversation not found' });
      }
      if (conversation.isGroup || conversation.groupJid) {
        return res.status(400).json({ error: 'Assignments are not supported for WhatsApp group conversations' });
      }

      if (conversation.companyId !== null && conversation.companyId !== user.companyId) {
        return res.status(403).json({ error: 'Access denied' });
      }

      if (conversation.companyId === null) {
        await storage.updateConversation(conversationId, {
          companyId: user.companyId
        });
      }

      const updatedConversation = await storage.updateConversation(conversationId, {
        assignedToUserId: null
      });

      broadcastToAll({
        type: 'conversationUnassigned',
        data: {
          conversationId,
          unassignedBy: user.id,
          conversation: updatedConversation
        }
      }, user.companyId);

      await broadcastConversationUpdate(updatedConversation, 'conversationUpdated');

      res.json(updatedConversation);
    } catch (error) {
      console.error('Error unassigning conversation:', error);
      res.status(500).json({ error: 'Failed to unassign conversation' });
    }
  });


  app.post('/api/conversations/:conversationId/initiate-call',
    ensureAuthenticated,
    requirePermission(PERMISSIONS.MANAGE_CALL_LOGS),
    async (req, res) => {
      try {
        // Parse and validate conversationId
        const conversationId = parseInt(req.params.conversationId);
        if (isNaN(conversationId)) {
          return res.status(400).json({ error: 'Invalid conversation ID' });
        }

        // Get conversation
        const conversation = await storage.getConversation(conversationId);
        if (!conversation) {
          return res.status(404).json({ error: 'Conversation not found' });
        }

        // Verify company access
        if (!req.user || conversation.companyId !== req.user.companyId) {
          return res.status(403).json({ error: 'Access denied' });
        }

        // Check if conversation is a group
        if (conversation.isGroup === true) {
          return res.status(400).json({ error: 'Cannot initiate calls to group conversations' });
        }

        // Get contact
        const contact = await storage.getContact(conversation.contactId!);
        if (!contact) {
          return res.status(404).json({ error: 'Contact not found' });
        }

        const permissions = await getUserPermissions(req.user as any);
        if (!(req.user as any).isSuperAdmin && permissions[PERMISSIONS.VIEW_CONTACT_PHONE] !== true) {
          return res.status(403).json({ error: 'You do not have permission to view or use contact phone numbers' });
        }

        // A WhatsApp user may be addressable by BSUID even when Meta withholds their phone number.
        const phoneNumber = contact.phone;

        // Use the company's configured voice channel for calls (conversation may be WhatsApp, etc.)
        const companyId = req.user?.companyId;
        if (!companyId) {
          return res.status(400).json({ error: 'Company ID is required' });
        }
        const parsedCallRequest = initiateCallRequestSchema.safeParse(req.body || {});
        if (!parsedCallRequest.success) {
          return res.status(400).json({ error: 'Invalid call request', details: parsedCallRequest.error.flatten() });
        }
        const callRequest = parsedCallRequest.data;
        const allConnections = await storage.getChannelConnectionsByCompany(companyId);
        const explicitlySelected = callRequest.channelId
          ? allConnections.find((connection) => connection.id === callRequest.channelId && connection.status === 'active')
          : undefined;
        if (callRequest.channelId && !explicitlySelected) {
          return res.status(404).json({ error: 'Calling channel not found' });
        }

        if (explicitlySelected?.channelType === 'whatsapp_official') {
          let targetConversation = await storage.getConversationByContactAndChannel(contact.id, explicitlySelected.id);
          if (!targetConversation) {
            targetConversation = await storage.createConversation({
              contactId: contact.id,
              channelId: explicitlySelected.id,
              companyId,
              channelType: 'whatsapp_official',
              status: 'active',
              lastMessageAt: new Date(),
              isGroup: false,
            });
          }
          try {
            const result = await initiateWhatsAppCall({
              companyId,
              userId: req.user.id,
              channel: explicitlySelected,
              contact,
              conversation: targetConversation,
              request: callRequest,
            });
            return res.json({
              success: true,
              callId: result.call.id,
              callSid: result.metaCallId,
              status: result.call.status,
              channelId: explicitlySelected.id,
              callType: result.callType,
              provider: 'whatsapp',
              supportsBrowserDirect: result.callType === 'direct',
              contactName: contact.name,
              contactPhone: contact.phone,
              contactAvatar: contact.avatarUrl,
            });
          } catch (error) {
            if (error instanceof WhatsAppCallingError) {
              return res.status(error.status).json({ error: error.message, code: error.code, errorCode: error.code, details: error.details });
            }
            throw error;
          }
        }

        if (explicitlySelected && explicitlySelected.channelType !== 'twilio_voice') {
          return res.status(400).json({ error: 'Selected channel does not support calls' });
        }
        if (!phoneNumber || phoneNumber.trim() === '') {
          return res.status(400).json({ error: 'Contact does not have a phone number' });
        }
        const voiceConnections = getActiveVoiceConnections(allConnections as any);

        if (voiceConnections.length === 0) {
          return res.status(400).json({
            error: 'No active voice channel found. Please configure Voice Calls in Settings.'
          });
        }

        const channelConnection = explicitlySelected || voiceConnections[0];

        // Extract callType from request body
        const { callType } = callRequest;

        const connectionData = normalizeVoiceChannelConnectionData(channelConnection.connectionData as any);
        const credentialError = getVoiceConnectionCredentialError(connectionData);
        if (credentialError) {
          return res.status(400).json({
            error: credentialError
          });
        }

        const actualCallType = resolveEffectiveVoiceCallType(connectionData, callType);
        const aiConfigError = actualCallType === 'ai-powered'
          ? getAiVoiceConfigurationError(connectionData)
          : null;
        if (aiConfigError) {
          return res.status(400).json({ error: aiConfigError });
        }

        const { callLogsService } = await import('./services/call-logs-service');
        const { CallLogsEventEmitter } = await import('./utils/websocket');
        const webhookBaseUrl = process.env.WEBHOOK_BASE_URL ||
          process.env.PUBLIC_URL?.replace(/^https?:\/\//, '') ||
          'localhost:3000';
        const result = await dispatchVoiceCall({
          connection: channelConnection as any,
          to: phoneNumber!,
          from: connectionData.fromNumber || '',
          requestedCallType: callType,
          webhookBaseUrl,
          recordCall: callRequest.recording !== false,
          twilioConfigFactory: () => ({
            twilioAccountSid: connectionData.accountSid || '',
            twilioAuthToken: connectionData.authToken || '',
            twilioFromNumber: connectionData.fromNumber || '',
            toNumber: phoneNumber!,
            elevenLabsApiKey: actualCallType === 'ai-powered' ? (connectionData.elevenLabsApiKey || '') : '',
            elevenLabsAgentId: actualCallType === 'ai-powered' ? connectionData.elevenLabsAgentId : undefined,
            elevenLabsPrompt: actualCallType === 'ai-powered' ? connectionData.elevenLabsPrompt : undefined,
            elevenLabsVoiceId: actualCallType === 'ai-powered' ? connectionData.voiceId : undefined,
            timeout: 30,
            maxDuration: 300,
            recordCall: callRequest.recording !== false,
            executionMode: 'async'
          })
        });
        const { callSid, from, to, startTime, metadata } = result;
        const metadataRecord = (metadata || {}) as Record<string, any>;
        const recordingNorm = buildCallRecordingFields({
          recordCall: callRequest.recording !== false,
          telephonyProvider: result.telephonyProvider,
          callType: result.callType,
          elevenLabsNativeOutbound: !!metadataRecord.elevenLabsNativeOutbound
        });

        // Create call log entry
        const { call: savedCall } = await callLogsService.upsertCallLog({
          companyId: req.user?.companyId || 0,
          channelId: channelConnection.id,
          contactId: contact.id,
          conversationId: conversationId,
          flowId: null,
          nodeId: null,
          direction: 'outbound',
          status: 'initiated',
          from: from,
          to: to,
          twilioCallSid: callSid,
          provider: result.telephonyProvider,
          providerCallId: callSid,
          callType: result.callType,
          transcriptionRequested: false,
          startedAt: startTime,
          recordingRequested: recordingNorm.recordingRequested,
          recordingAudioProvider: recordingNorm.recordingAudioProvider,
          recordingExpectedFrom: recordingNorm.recordingExpectedFrom,
          agentConfig: actualCallType === 'ai-powered' ? {
            elevenLabsAgentId: connectionData.elevenLabsAgentId,
            elevenLabsPrompt: connectionData.elevenLabsPrompt,
            voiceId: connectionData.voiceId,
            vapiAssistantId: connectionData.vapiAssistantId
          } : undefined,
          metadata: {
            ...metadataRecord,
            hasElevenLabs: connectionData.providerStack === 'twilio-elevenlabs',
            providerStack: connectionData.providerStack,
            providerStackLabel: getVoiceProviderStackLabel(connectionData.providerStack),
            callType: result.callType,
            userSelectedCallType: !!callType,
            elevenLabsConversationId: metadataRecord.elevenLabsConversationId ?? metadataRecord.conversation_id,
            conferenceName: metadataRecord.conferenceName,
            supportsBrowserDirect: result.supportsBrowserDirect
          }
        });

        // Broadcast WebSocket event
        CallLogsEventEmitter.emitCallStatusUpdate(
          savedCall.id,
          req.user?.companyId || 0,
          'initiated',
          { callSid, from, to }
        );

        const canViewPhone = (req.user as any).isSuperAdmin || permissions[PERMISSIONS.VIEW_CONTACT_PHONE] === true;
        // Return success response with conference name for direct calls
        res.json({
          success: true,
          callSid: callSid,
          callId: savedCall.id,
          status: 'initiated',
          from: from,
          to: to,
          message: 'Call initiated successfully',
          conferenceName: metadataRecord.conferenceName,
          channelId: channelConnection.id,
          callType: result.callType,
          providerStack: result.providerStack,
          supportsBrowserDirect: result.supportsBrowserDirect,
          contactName: contact.name,
          contactPhone: canViewPhone ? contact.phone : null,
          contactAvatar: contact.avatarUrl
        });

      } catch (error) {
        console.error('[Initiate Call]', error);

        // Handle specific error types
        const errorMessage = error instanceof Error ? error.message : 'Unknown error';

        if (errorMessage?.includes('Invalid credentials') ||
          errorMessage?.includes('authentication')) {
          return res.status(400).json({ error: 'Invalid voice provider credentials' });
        }

        if (errorMessage?.includes('Twilio API')) {
          return res.status(500).json({ error: 'Twilio API error: ' + errorMessage });
        }

        if (errorMessage?.includes('Telnyx') || errorMessage?.includes('Vapi')) {
          return res.status(500).json({ error: 'Voice provider API error: ' + errorMessage });
        }

        // Generic error
        res.status(500).json({ error: 'Failed to initiate call: ' + errorMessage });
      }
    }
  );

  /**
   * Generate Twilio Voice SDK Access Token
   * Used by the frontend to connect to Twilio Voice via WebRTC
   */
  app.get('/api/twilio/voice-token',
    ensureAuthenticated,
    requirePermission(PERMISSIONS.MANAGE_CALL_LOGS),
    async (req, res) => {
      try {
        const user = req.user;
        if (!user) {
          return res.status(401).json({ error: 'Unauthorized' });
        }

        // Get channelId from query params - required for multi-tenant isolation
        const channelId = req.query.channelId ? parseInt(req.query.channelId as string) : null;
        
        if (!channelId) {
          return res.status(400).json({ 
            error: 'Channel ID is required for voice token generation',
            setup: {
              step1: 'Create API Key in Twilio Console > Account > API Keys',
              step2: 'Create TwiML App in Twilio Console > Voice > TwiML Apps',
              step3: 'Set Voice Request URL to: https://your-domain.com/api/twilio/voice-app-twiml',
              step4: 'Add API Key, API Secret, and TwiML App SID to channel connection settings'
            },
            documentation: 'https://www.twilio.com/docs/voice/sdks/javascript/get-started'
          });
        }

        // Fetch credentials from channel connection - no fallback to .env
        const channelConnection = await storage.getChannelConnection(channelId);
        if (!channelConnection) {
          return res.status(404).json({ error: 'Channel connection not found' });
        }
        if (channelConnection.companyId !== user.companyId) {
          return res.status(403).json({ error: 'Access denied' });
        }
        if (channelConnection.channelType !== 'twilio_voice') {
          return res.status(400).json({ error: 'Not a voice channel' });
        }

        const connectionData = normalizeVoiceChannelConnectionData(channelConnection.connectionData as any);
        if (!supportsBrowserVoiceConnection(connectionData)) {
          return res.status(400).json({
            error: 'Browser-based direct calling is only available for the Twilio + ElevenLabs stack.',
            providerStack: connectionData.providerStack
          });
        }

        const accountSid = connectionData?.accountSid;
        const apiKey = connectionData?.apiKey;
        const apiSecret = connectionData?.apiSecret;
        const twimlAppSid = connectionData?.twimlAppSid;

        // Validate required credentials - return clear error if missing
        if (!accountSid || !apiKey || !apiSecret) {
          return res.status(400).json({ 
            error: 'Twilio Voice SDK credentials not configured in channel connection',
            setup: {
              step1: 'Create API Key in Twilio Console > Account > API Keys',
              step2: 'Create TwiML App in Twilio Console > Voice > TwiML Apps',
              step3: 'Set Voice Request URL to: https://your-domain.com/api/twilio/voice-app-twiml',
              step4: 'Add API Key, API Secret, and TwiML App SID to channel connection settings'
            },
            documentation: 'https://www.twilio.com/docs/voice/sdks/javascript/get-started'
          });
        }

        // Validate TwiML App SID is present
        if (!twimlAppSid) {
          return res.status(400).json({ 
            error: 'TwiML Application SID not configured in channel connection',
            setup: {
              step1: 'Create TwiML App in Twilio Console > Voice > TwiML Apps',
              step2: 'Set Voice Request URL to: https://your-domain.com/api/twilio/voice-app-twiml',
              step3: 'Add TwiML App SID to channel connection settings'
            },
            documentation: 'https://www.twilio.com/docs/voice/sdks/javascript/get-started'
          });
        }

        // Import Twilio JWT library - load default export for ESM compatibility
        const twilioModule = await import('twilio');
        const twilio = twilioModule.default || twilioModule;
        const AccessToken = twilio.jwt?.AccessToken;
        
        // Defensive check: ensure AccessToken is available
        if (!AccessToken) {
          return res.status(500).json({ 
            error: 'Failed to load Twilio AccessToken - Twilio module structure is invalid',
            details: 'The Twilio JWT AccessToken class could not be found. This may indicate a module compatibility issue.'
          });
        }
        
        const VoiceGrant = AccessToken.VoiceGrant;

        // Create identity for the agent
        const identity = `agent-${user.id}-${user.companyId}`;

        // Create Voice Grant
        const voiceGrant = new VoiceGrant({
          outgoingApplicationSid: twimlAppSid,
          incomingAllow: true
        });

        // Create Access Token
        const token = new AccessToken(
          accountSid,
          apiKey,
          apiSecret,
          { identity, ttl: 3600 } // 1 hour TTL
        );
        token.addGrant(voiceGrant);

        console.log(`[Twilio Voice Token] Generated token for agent: ${identity}`);

        res.json({
          token: token.toJwt(),
          identity
        });

      } catch (error) {
        console.error('[Twilio Voice Token] Error:', error);
        res.status(500).json({ 
          error: 'Failed to generate voice token',
          details: error instanceof Error ? error.message : 'Unknown error'
        });
      }
    }
  );

  /**
   * Voice SDK Setup Validation Endpoint
   * Validates Twilio Voice SDK configuration for a channel connection
   */
  app.post('/api/twilio/voice-setup/validate',
    ensureAuthenticated,
    requirePermission(PERMISSIONS.MANAGE_CALL_LOGS),
    async (req, res) => {
      try {
        const user = req.user;
        if (!user) {
          return res.status(401).json({ error: 'Unauthorized' });
        }

        const { channelId } = req.body;
        if (!channelId) {
          return res.status(400).json({ error: 'Channel ID is required' });
        }

        // Fetch channel connection with error handling
        let channelConnection;
        try {
          channelConnection = await storage.getChannelConnection(channelId);
        } catch (error) {
          console.error('[Voice SDK Setup Validation] Database error:', error);
          return res.status(500).json({ 
            error: 'Failed to fetch channel connection',
            details: error instanceof Error ? error.message : 'Database error',
            validationResults: {
              overallStatus: 'error',
              message: 'Could not access channel connection data'
            }
          });
        }

        if (!channelConnection) {
          return res.status(404).json({ error: 'Channel connection not found' });
        }
        if (channelConnection.companyId !== user.companyId) {
          return res.status(403).json({ error: 'Access denied' });
        }
        if (channelConnection.channelType !== 'twilio_voice') {
          return res.status(400).json({ error: 'Not a Twilio Voice channel' });
        }

        const connectionData = channelConnection.connectionData as any;
        const accountSid = connectionData?.accountSid;
        const authToken = connectionData?.authToken;
        const apiKey = connectionData?.apiKey;
        const apiSecret = connectionData?.apiSecret;
        const twimlAppSid = connectionData?.twimlAppSid;
        const fromNumber = connectionData?.fromNumber;

        const validationResults: any = {
          channelId,
          timestamp: new Date().toISOString(),
          checks: {}
        };

        // Check 1: REST API credentials
        validationResults.checks.restApiCredentials = {
          status: 'unknown',
          message: ''
        };
        if (accountSid && authToken) {
          try {
            const response = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${accountSid}.json`, {
              headers: {
                'Authorization': `Basic ${Buffer.from(`${accountSid}:${authToken}`).toString('base64')}`
              },
              signal: AbortSignal.timeout(5000)
            });
            validationResults.checks.restApiCredentials.status = response.ok ? 'valid' : 'invalid';
            validationResults.checks.restApiCredentials.message = response.ok 
              ? 'REST API credentials are valid'
              : 'REST API credentials are invalid';
          } catch (error) {
            validationResults.checks.restApiCredentials.status = 'error';
            validationResults.checks.restApiCredentials.message = 'Failed to validate REST API credentials';
          }
        } else {
          validationResults.checks.restApiCredentials.status = 'missing';
          validationResults.checks.restApiCredentials.message = 'REST API credentials not configured';
        }

        // Check 2: Voice SDK credentials (API Key and Secret)
        validationResults.checks.voiceSDKCredentials = {
          status: 'unknown',
          message: ''
        };
        if (apiKey && apiSecret && accountSid) {
          try {
            // Import Twilio JWT library - load default export for ESM compatibility
            const twilioModule = await import('twilio');
            const twilio = twilioModule.default || twilioModule;
            const AccessToken = twilio.jwt?.AccessToken;
            
            // Defensive check: ensure AccessToken is available
            if (!AccessToken) {
              validationResults.checks.voiceSDKCredentials.status = 'error';
              validationResults.checks.voiceSDKCredentials.message = 'Failed to load Twilio AccessToken - Twilio module structure is invalid';
            } else {
              const VoiceGrant = AccessToken.VoiceGrant;
              
              const voiceGrant = new VoiceGrant({
                outgoingApplicationSid: twimlAppSid || 'test',
                incomingAllow: true
              });
              
              const token = new AccessToken(
                accountSid,
                apiKey,
                apiSecret,
                { identity: 'validation-test', ttl: 60 }
              );
              token.addGrant(voiceGrant);
              
              const jwt = token.toJwt();
              validationResults.checks.voiceSDKCredentials.status = jwt && jwt.length > 0 ? 'valid' : 'invalid';
              validationResults.checks.voiceSDKCredentials.message = jwt && jwt.length > 0
                ? 'Voice SDK credentials can generate valid tokens'
                : 'Failed to generate Voice SDK token';
            }
          } catch (error) {
            validationResults.checks.voiceSDKCredentials.status = 'error';
            validationResults.checks.voiceSDKCredentials.message = error instanceof Error ? error.message : 'Voice SDK credential validation failed';
          }
        } else {
          validationResults.checks.voiceSDKCredentials.status = 'missing';
          validationResults.checks.voiceSDKCredentials.message = 'Voice SDK credentials (API Key, API Secret) not configured';
        }

        // Check 3: TwiML App SID exists and is accessible
        validationResults.checks.twimlApp = {
          status: 'unknown',
          message: ''
        };
        if (twimlAppSid && accountSid && authToken) {
          try {
            const response = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Applications/${twimlAppSid}.json`, {
              headers: {
                'Authorization': `Basic ${Buffer.from(`${accountSid}:${authToken}`).toString('base64')}`
              },
              signal: AbortSignal.timeout(3000)
            });
            if (response.ok) {
              const appData = await response.json();
              validationResults.checks.twimlApp.voiceUrl = appData.voice_url;

              const actualServerUrl = getPublicBaseUrlFromRequest(req);
              const expectedVoiceUrl = getExpectedTwimlAppVoiceUrl(actualServerUrl);

              const configuredUrl = appData.voice_url || '';
              const normalizedConfigured = configuredUrl.replace(/\/$/, '');
              const normalizedExpected = expectedVoiceUrl.replace(/\/$/, '');
              const urlsMatch = normalizedConfigured === normalizedExpected;

              validationResults.checks.twimlApp.voiceUrlConfigured = urlsMatch;
              validationResults.checks.twimlApp.configuredVoiceUrl = configuredUrl;
              validationResults.checks.twimlApp.expectedVoiceUrl = expectedVoiceUrl;

              if (!urlsMatch) {
                validationResults.checks.twimlApp.status = 'invalid';
                validationResults.checks.twimlApp.message = `TwiML App Voice URL mismatch. Expected: ${expectedVoiceUrl}, Got: ${configuredUrl}`;
                if (configuredUrl.startsWith('http://')) {
                  validationResults.checks.twimlApp.httpSchemeWarning =
                    'The configured Voice URL uses HTTP instead of HTTPS. Use HTTPS for production webhooks.';
                  validationResults.checks.twimlApp.message += ` ${validationResults.checks.twimlApp.httpSchemeWarning}`;
                }
              } else if (configuredUrl && !configuredUrl.startsWith('https://')) {
                validationResults.checks.twimlApp.status = 'warning';
                validationResults.checks.twimlApp.warning = 'Voice URL should use HTTPS in production';
                validationResults.checks.twimlApp.message =
                  'Voice URL uses HTTP instead of HTTPS. Twilio requires HTTPS for production webhooks.';
              } else {
                validationResults.checks.twimlApp.status = 'valid';
                validationResults.checks.twimlApp.message = 'TwiML App Voice URL is correctly configured';
              }

              if (configuredUrl) {
                const reach = await validateWebhookReachability(configuredUrl);
                validationResults.checks.twimlApp.voiceUrlReachable = reach.reachable;
                if (!reach.reachable && reach.error) {
                  validationResults.checks.twimlApp.voiceUrlReachabilityError = reach.error;
                }
                if (!reach.reachable && validationResults.checks.twimlApp.status === 'valid') {
                  validationResults.checks.twimlApp.status = 'warning';
                  validationResults.checks.twimlApp.message = `${validationResults.checks.twimlApp.message} Voice URL is not reachable from the internet.`;
                }
              }
            } else {
              validationResults.checks.twimlApp.status = 'invalid';
              validationResults.checks.twimlApp.message = 'TwiML App SID not found or not accessible';
            }
          } catch (error) {
            validationResults.checks.twimlApp.status = 'error';
            validationResults.checks.twimlApp.message = 'Failed to validate TwiML App';
          }
        } else {
          validationResults.checks.twimlApp.status = 'missing';
          validationResults.checks.twimlApp.message = 'TwiML App SID not configured';
        }

        // Check 4: Account balance (if accessible)
        validationResults.checks.accountBalance = {
          status: 'unknown',
          message: ''
        };
        if (accountSid && authToken) {
          try {
            const response = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${accountSid}.json`, {
              headers: {
                'Authorization': `Basic ${Buffer.from(`${accountSid}:${authToken}`).toString('base64')}`
              },
              signal: AbortSignal.timeout(3000)
            });
            if (response.ok) {
              const accountData = await response.json();
              validationResults.checks.accountBalance.status = 'checked';
              validationResults.checks.accountBalance.balance = accountData.balance;
              validationResults.checks.accountBalance.currency = accountData.currency;
              validationResults.checks.accountBalance.message = accountData.balance && parseFloat(accountData.balance) > 0
                ? 'Account has sufficient balance'
                : 'Account balance is low or zero';
            }
          } catch (error) {
            validationResults.checks.accountBalance.status = 'error';
            validationResults.checks.accountBalance.message = 'Could not check account balance';
          }
        }

        // Check 5: Phone number configuration
        validationResults.checks.phoneNumber = {
          status: fromNumber ? 'configured' : 'missing',
          message: fromNumber ? 'Phone number is configured' : 'Phone number not configured',
          fromNumber: fromNumber || null
        };

        // Calculate overall status
        const allChecks = Object.values(validationResults.checks);
        const criticalChecks = ['restApiCredentials', 'voiceSDKCredentials', 'twimlApp'];
        const criticalStatuses = criticalChecks.map(key => validationResults.checks[key]?.status);
        
        if (criticalStatuses.every(s => s === 'valid')) {
          validationResults.overallStatus = 'valid';
          validationResults.message = 'All critical checks passed';
        } else if (criticalStatuses.some(s => s === 'error' || s === 'invalid')) {
          validationResults.overallStatus = 'invalid';
          validationResults.message = 'Some critical checks failed';
        } else {
          validationResults.overallStatus = 'incomplete';
          validationResults.message = 'Configuration is incomplete';
        }

        // Add setup instructions
        validationResults.setup = {
          step1: 'Create API Key in Twilio Console > Account > API Keys',
          step2: 'Create TwiML App in Twilio Console > Voice > TwiML Apps',
          step3: `Set Voice Request URL to: ${process.env.PUBLIC_URL || process.env.WEBHOOK_BASE_URL || 'https://your-domain.com'}/api/twilio/voice-app-twiml`,
          step4: 'Add API Key, API Secret, and TwiML App SID to channel connection settings',
          documentation: 'https://www.twilio.com/docs/voice/sdks/javascript/get-started'
        };

        res.json(validationResults);

      } catch (error) {
        console.error('[Voice SDK Setup Validation] Error:', error);
        res.status(500).json({ 
          error: 'Failed to validate Voice SDK setup',
          details: error instanceof Error ? error.message : 'Unknown error'
        });
      }
    }
  );

  function voiceAppTwimlErrorTwiml(message: string): string {
    return `<?xml version="1.0" encoding="UTF-8"?><Response><Say>${message}</Say><Hangup/></Response>`;
  }

  /** Whether the request's effective host is loopback (local proxy / dev on localhost). */
  function isVoiceAppTwimlLoopbackHost(hostHeader: string | undefined): boolean {
    if (!hostHeader) return false;
    const first = firstForwardedHeaderValue(hostHeader) ?? hostHeader.trim();
    let hostname = first;
    if (hostname.startsWith('[')) {
      const end = hostname.indexOf(']');
      if (end > 1) hostname = hostname.slice(1, end);
    } else {
      const lastColon = hostname.lastIndexOf(':');
      if (lastColon > 0) {
        const after = hostname.slice(lastColon + 1);
        if (/^\d+$/.test(after)) hostname = hostname.slice(0, lastColon);
      }
    }
    const h = hostname.toLowerCase();
    return h === 'localhost' || h === '127.0.0.1' || h === '::1';
  }

  /**
   * TwiML Application endpoint for Twilio Voice SDK
   * Returns TwiML to connect the agent to a conference
   * Validates requests using Twilio signature verification (no session auth required)
   */
  app.post('/api/twilio/voice-app-twiml',
    express.urlencoded({ extended: false }),
    async (req, res) => {
      try {
        const { conferenceName } = req.body;
        const channelIdParsed = parseInt(req.body.channelId, 10);
        const signature = req.headers['x-twilio-signature'] as string | undefined;

        if (!conferenceName) {
          console.error('[Voice App TwiML] Missing conferenceName parameter');
          return res.type('text/xml').send(
            voiceAppTwimlErrorTwiml('Error: Missing conference name parameter.')
          );
        }

        if (Number.isNaN(channelIdParsed)) {
          console.error('[Voice App TwiML] Missing or invalid channelId parameter');
          return res.type('text/xml').send(
            voiceAppTwimlErrorTwiml('Error: Missing or invalid channel identifier.')
          );
        }

        const connection = await storage.getChannelConnection(channelIdParsed);
        let authToken: string | undefined;
        if (connection?.connectionData) {
          const connectionData = connection.connectionData as any;
          authToken = connectionData.authToken;
        }

        if (!connection) {
          console.warn(`[Voice App TwiML] No channel connection for channelId: ${channelIdParsed}`);
          return res.type('text/xml').send(
            voiceAppTwimlErrorTwiml('Error: Voice channel connection not found.')
          );
        }

        if (!authToken) {
          console.error(`[Voice App TwiML] No auth token for channel connection: ${channelIdParsed}`);
          return res.type('text/xml').send(
            voiceAppTwimlErrorTwiml('Error: Voice channel credentials not configured.')
          );
        }

        if (process.env.NODE_ENV !== 'production') {
          console.warn('[Voice App TwiML] Skipping signature validation (non-production environment)');
        } else {
          const fullUrl = `${getPublicBaseUrlFromRequest(req)}${req.originalUrl}`;
          const forwardedHost = firstForwardedHeaderValue(req.get('x-forwarded-host'));
          const hostHeader = firstForwardedHeaderValue(req.get('host'));
          const effectiveExternalHost = forwardedHost ?? hostHeader;

          if (signature) {
            const signatureValid = verifyTwilioCallSignature(
              fullUrl,
              req.body as Record<string, string>,
              signature,
              authToken
            );
            if (!signatureValid) {
              console.error('[Voice App TwiML] Invalid Twilio signature');
              return res.type('text/xml').send(
                voiceAppTwimlErrorTwiml('Error: Request signature validation failed.')
              );
            }
          } else if (isVoiceAppTwimlLoopbackHost(effectiveExternalHost)) {
            console.warn(
              '[Voice App TwiML] Missing X-Twilio-Signature on loopback host; bypassing validation (production)'
            );
          } else {
            console.warn('[Voice App TwiML] Missing X-Twilio-Signature header (production)');
            return res.type('text/xml').send(
              voiceAppTwimlErrorTwiml('Error: Request signature validation failed.')
            );
          }
        }

        console.log(`[Voice App TwiML] Agent joining conference: ${conferenceName}`);

        // Generate TwiML for agent to join the conference.
        // Mixed conference recording is started on the customer PSTN leg (outbound TwiML in call-agent-service);
        // this leg stays record="do-not-record" so Twilio does not create a second conference recording.
        const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Dial>
    <Conference 
      startConferenceOnEnter="false" 
      endConferenceOnExit="true"
      beep="false"
      muted="false"
      waitUrl=""
      waitMethod="GET"
      record="do-not-record"
      statusCallbackEvent="start end join leave">
      ${conferenceName}
    </Conference>
  </Dial>
</Response>`;

        res.type('text/xml');
        res.send(twiml);

      } catch (error) {
        console.error('[Voice App TwiML] Error:', error);
        res.type('text/xml').send(
          voiceAppTwimlErrorTwiml('Error: An unexpected error occurred processing your call.')
        );
      }
    }
  );

  /**
   * GET version of TwiML Application endpoint (for Twilio webhook verification)
   */
  app.get('/api/twilio/voice-app-twiml', (req, res) => {
    res.type('text/xml');
    res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>This endpoint is for Twilio Voice SDK connections.</Say>
</Response>`);
  });


