  app.post('/api/tiktok/oauth/prepare', ensureAuthenticated, async (req: Request, res: Response) => {
    try {
      const { state, accountName, parentOrigin } = req.body;

      if (!state || !accountName) {
        return res.status(400).json({ error: 'State and account name are required' });
      }

      const partner = await storage.getPartnerConfiguration('tiktok');
      if (!partner || !partner.isActive) {
        return res.status(400).json({ error: 'TikTok platform configuration not found or inactive' });
      }

      if (!req.session) {
        req.session = {} as any;
      }
      (req.session as any).tiktokOAuthState = state;
      (req.session as any).tiktokAccountName = accountName;
      if (typeof parentOrigin === 'string' && parentOrigin.startsWith('http')) {
        (req.session as any).tiktokOAuthParentOrigin = parentOrigin;
      }

      const pp = partner.publicProfile as Record<string, unknown> | undefined;
      const allowedScopes = resolveTikTokPartnerOAuthScopes(pp);
      const accountHolderAuthorizationUrl =
        typeof pp?.accountHolderAuthorizationUrl === 'string' ? pp.accountHolderAuthorizationUrl.trim() : '';

      res.json({
        success: true,
        allowedScopes: [...allowedScopes],
        ...(accountHolderAuthorizationUrl ? { accountHolderAuthorizationUrl } : {}),
      });
    } catch (error) {
      console.error('Error preparing TikTok OAuth:', error);
      res.status(500).json({ error: 'Failed to prepare OAuth' });
    }
  });


  /**
   * TikTok account holder OAuth redirect (`www.tiktok.com/v2/auth/authorize`): success may return `code` and/or `auth_code` (prefer `code`, fall back to `auth_code` for compatibility), plus `state`; denial returns `error` / `error_description`.
   * Token exchange posts to `open.tiktokapis.com/v2/oauth/token/` (form body: `client_key`, `client_secret`, `code`, `grant_type`, `redirect_uri`) per TikTok v2 authorize flow.
   */
  app.get(
    ['/api/tiktok/oauth/callback', '/api/tiktok/oauth/callback/'],
    ensureAuthenticated,
    ensureActiveSubscription,
    async (req: Request, res: Response) => {
    try {
      const { auth_code, code, state, error, error_description } = req.query;
      const user = req.user as any;
      const postMessageTarget = JSON.stringify((req.session as any)?.tiktokOAuthParentOrigin || '');

      if (!user?.id || !user?.companyId) {
        return res.status(401).send(`
          <html>
            <body>
              <h1>Authentication Error</h1>
              <p>User not authenticated. Please log in and try again.</p>
              <script>window.close();</script>
            </body>
          </html>
        `);
      }


      if (error) {
        console.error('TikTok OAuth error:', error, error_description);
        return res.status(400).send(`
          <html>
            <body>
              <h1>TikTok Authorization Failed</h1>
              <p>${error_description || error}</p>
              <script>
                setTimeout(() => {
                  var t = ${postMessageTarget};
                  window.opener?.postMessage({ type: 'tiktok_oauth_error', error: ${JSON.stringify(String(error))} }, t || '*');
                  window.close();
                }, 2000);
              </script>
            </body>
          </html>
        `);
      }


      const savedState = (req.session as any)?.tiktokOAuthState;
      if (!state || state !== savedState) {
        console.error('TikTok OAuth state mismatch');
        return res.status(400).send(`
          <html>
            <body>
              <h1>Security Error</h1>
              <p>Invalid state parameter. Please try again.</p>
              <script>window.close();</script>
            </body>
          </html>
        `);
      }

      const authCodeRaw =
        typeof code === 'string' && code.length > 0
          ? code
          : typeof auth_code === 'string' && auth_code.length > 0
            ? auth_code
            : undefined;
      if (!authCodeRaw) {
        return res.status(400).send(`
          <html>
            <body>
              <h1>Authorization Error</h1>
              <p>No authorization code received from TikTok.</p>
              <script>window.close();</script>
            </body>
          </html>
        `);
      }


      await TikTokService.getPlatformConfig();

      const tokenResponse = await TikTokService.exchangeCodeForToken(authCodeRaw);
      const grantedScopes = parseTikTokScopeList(tokenResponse.scope);

      const userInfo = await TikTokService.getUserInfo(tokenResponse.access_token, grantedScopes);

      // Verify Business Account / Business Messaging eligibility (not Login Kit profile alone)
      const businessAccountVerification = await TikTokService.verifyBusinessAccount(
        tokenResponse.access_token,
        grantedScopes
      );

      if (businessAccountVerification.outcome === 'retryable') {
        const retryMsg = businessAccountVerification.message || 'Temporary error verifying TikTok Business Messaging. Please try again.';
        return res.status(503).send(`
          <html>
            <body>
              <h1>Please try again</h1>
              <p>${retryMsg.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</p>
              <p>If this keeps happening, wait a few minutes and reconnect.</p>
              <script>
                setTimeout(() => {
                  var t = ${postMessageTarget};
                  window.opener?.postMessage({ type: 'tiktok_oauth_error', error: 'TikTok verification temporarily unavailable' }, t || '*');
                  window.close();
                }, 4000);
              </script>
            </body>
          </html>
        `);
      }

      if (businessAccountVerification.outcome === 'not_business') {
        return res.status(400).send(`
          <html>
            <body>
              <h1>TikTok Business Account Required</h1>
              <p>TikTok Business Account required. Personal and Creator accounts are not supported for messaging. Please convert your account to a Business Account in TikTok settings.</p>
              <p><a href="https://www.tiktok.com/business/en-US" target="_blank">Learn how to convert to a Business Account →</a></p>
              <script>
                setTimeout(() => {
                  var t = ${postMessageTarget};
                  window.opener?.postMessage({ type: 'tiktok_oauth_error', error: 'TikTok Business Account Required' }, t || '*');
                  window.close();
                }, 3000);
              </script>
            </body>
          </html>
        `);
      }

      const partnerCfg = await storage.getPartnerConfiguration('tiktok');
      const portalExpectedScopes = [...resolveTikTokPartnerOAuthScopes(partnerCfg?.publicProfile)];
      const enforcedMissing = (TIKTOK_OAUTH_ENFORCED_SCOPES as readonly string[]).filter(
        (s) => !grantedScopes.includes(s)
      );
      if (enforcedMissing.length > 0) {
        const scopeHint =
          enforcedMissing.join(', ') === 'user.info.basic'
            ? 'The basic profile scope (user.info.basic) is required. Please try connecting again and allow basic profile access.'
            : `These permissions are required: ${enforcedMissing.join(', ')}. Please try connecting again and approve the requested access.`;
        return res.status(400).send(`
          <html>
            <body>
              <h1>Required Permissions Not Granted</h1>
              <p>${scopeHint}</p>
              <script>
                setTimeout(() => {
                  var t = ${postMessageTarget};
                  window.opener?.postMessage({ type: 'tiktok_oauth_error', error: 'Required Permissions Not Granted' }, t || '*');
                  window.close();
                }, 3000);
              </script>
            </body>
          </html>
        `);
      }
      const enforcedSet = new Set(TIKTOK_OAUTH_ENFORCED_SCOPES as readonly string[]);
      const optionalMissing = portalExpectedScopes.filter(
        (scope) => !grantedScopes.includes(scope) && !enforcedSet.has(scope)
      );
      if (optionalMissing.length > 0) {
        logger.warn('tiktok', 'OAuth callback: user granted a subset of portal-requested scopes (continuing)', {
          optionalMissing,
          grantedScopes,
          portalExpectedScopes,
          userId: user.id,
          companyId: user.companyId,
        });
      }

      const accountName = (req.session as any)?.tiktokAccountName || `TikTok - ${userInfo.display_name}`;
      const tokenOpenId =
        typeof tokenResponse.open_id === 'string' ? tokenResponse.open_id.trim() : '';
      const userOpenId = typeof userInfo.open_id === 'string' ? userInfo.open_id.trim() : '';
      const accountOpenId = tokenOpenId || userOpenId || '';
      if (!accountOpenId) {
        return res.status(400).send(`
          <html>
            <body>
              <h1>Account identification failed</h1>
              <p>TikTok did not return a user identifier. Please try connecting again or contact support.</p>
              <script>
                var t = ${postMessageTarget};
                window.opener?.postMessage({ type: 'tiktok_oauth_error', error: 'Account identification failed' }, t || '*');
                setTimeout(function () { window.close(); }, 2000);
              </script>
            </body>
          </html>
        `);
      }

      // Log granted scopes for debugging and audit purposes
      logger.info('tiktok', 'OAuth scopes granted:', { grantedScopes, userId: user.id, companyId: user.companyId });

      const messagingBusinessId =
        businessAccountVerification.outcome === 'verified'
          ? String(businessAccountVerification.businessAccountId).trim() || accountOpenId
          : accountOpenId;
      const regionInfo = await TikTokService.detectRegionRestrictions(
        tokenResponse.access_token,
        messagingBusinessId
      );

      const connectionData = {
        oauthTokenMintFlow: TIKTOK_OAUTH_TOKEN_MINT_FLOW_BUSINESS_API_V13,
        accessToken: tokenResponse.access_token,
        refreshToken: tokenResponse.refresh_token,
        tokenExpiresAt: Date.now() + (tokenResponse.expires_in * 1000),
        accountId: accountOpenId,
        accountName: userInfo.display_name,
        accountHandle: userInfo.username,
        avatarUrl: userInfo.avatar_url,
        grantedScopes: grantedScopes,
        isBusinessAccount: businessAccountVerification.outcome === 'verified',
        businessAccountId:
          businessAccountVerification.outcome === 'verified'
            ? String(businessAccountVerification.businessAccountId).trim() || undefined
            : undefined,
        regionRestricted: regionInfo.regionRestricted,
        restrictedFeatures: regionInfo.restrictedFeatures,
        regionCode: regionInfo.regionCode,
        connectedAt: Date.now(),
        lastSyncAt: Date.now(),
        status: 'active' as const,
        lastError: regionInfo.regionRestricted 
          ? 'Messaging features unavailable in your region (EEA/UK/CH). Analytics and profile features remain available.'
          : undefined
      };

      const connection = await storage.createChannelConnection({
        companyId: user.companyId,
        userId: user.id,
        channelType: 'tiktok',
        accountId: accountOpenId,
        accountName: accountName,
        accessToken: tokenResponse.access_token,
        status: 'active',
        connectionData: connectionData
      });


      await TikTokService.initializeConnection(connection.id);


      if (req.session) {
        delete (req.session as any).tiktokOAuthState;
        delete (req.session as any).tiktokAccountName;
        delete (req.session as any).tiktokOAuthParentOrigin;
      }


      res.send(`
        <html>
          <head>
            <style>
              body {
                font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
                display: flex;
                align-items: center;
                justify-content: center;
                height: 100vh;
                margin: 0;
                background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
              }
              .container {
                background: white;
                padding: 2rem;
                border-radius: 1rem;
                box-shadow: 0 10px 40px rgba(0,0,0,0.2);
                text-align: center;
                max-width: 400px;
              }
              .success-icon {
                font-size: 4rem;
                margin-bottom: 1rem;
              }
              h1 {
                color: #333;
                margin-bottom: 0.5rem;
              }
              p {
                color: #666;
                margin-bottom: 1.5rem;
              }
              .account-info {
                background: #f7fafc;
                padding: 1rem;
                border-radius: 0.5rem;
                margin-bottom: 1rem;
              }
            </style>
          </head>
          <body>
            <div class="container">
              <div class="success-icon">✅</div>
              <h1>TikTok Connected!</h1>
              <p>Your TikTok account has been successfully connected.</p>
              <div class="account-info">
                <strong>${userInfo.display_name}</strong>
                ${userInfo.username ? `<br/>@${userInfo.username}` : ''}
              </div>
              <p style="font-size: 0.875rem; color: #999;">You can close this window.</p>
            </div>
            <script>
              (function () {
                var t = ${postMessageTarget};
                try {
                  window.opener?.postMessage({ type: 'tiktok_oauth_success' }, t || '*');
                } finally {
                  setTimeout(function () { window.close(); }, 400);
                }
              })();
            </script>
          </body>
        </html>
      `);
    } catch (error: any) {
      console.error('Error processing TikTok OAuth callback:', error);
      
      // Determine error type and provide specific messaging
      let errorTitle = 'Connection Error';
      let errorMessage =
        error instanceof TikTokOAuthRequestError
          ? error.tiktokErrorDescription || error.message
          : error.message || 'Failed to connect TikTok account';
      let actionableGuidance = '';

      if (error instanceof TikTokOAuthRequestError) {
        errorTitle = 'TikTok authorization failed';
      } else if (error.message?.includes('Business Account') || error.response?.data?.error?.code === 'BUSINESS_ACCOUNT_REQUIRED') {
        errorTitle = 'TikTok Business Account Required';
        errorMessage = 'TikTok Business Account required. Personal and Creator accounts are not supported for messaging.';
        actionableGuidance = '<p><a href="https://www.tiktok.com/business/en-US" target="_blank">Learn how to convert to a Business Account →</a></p>';
      } else if (error.message?.includes('Required Permissions') || error.message?.includes('scope')) {
        errorTitle = 'Required Permissions Not Granted';
        errorMessage = 'Required permissions not granted. Please authorize all requested permissions to enable messaging features.';
        actionableGuidance = '<p>Please try connecting again and ensure you grant all requested permissions.</p>';
      } else if (error.message?.includes('region') || error.response?.data?.error?.code === 'REGION_NOT_SUPPORTED') {
        errorTitle = 'Messaging Unavailable in Your Region';
        errorMessage = 'Messaging features are not available in your region (EEA/UK/CH). Analytics and profile features remain available.';
        actionableGuidance = '<p>Your connection will be created with limited functionality.</p>';
      }
      
      logger.error('tiktok', 'OAuth callback error:', {
        error: error instanceof TikTokOAuthRequestError ? error.tiktokErrorDescription : error.message,
        tiktokCode: error instanceof TikTokOAuthRequestError ? error.tiktokErrorCode : undefined,
        logId: error instanceof TikTokOAuthRequestError ? error.logId : undefined,
        httpStatus: error instanceof TikTokOAuthRequestError ? error.httpStatus : error.response?.status,
        stack: error.stack,
        userId: (req.user as any)?.id,
        companyId: (req.user as any)?.companyId
      });
      
      res.status(500).send(`
        <html>
          <body>
            <h1>${errorTitle}</h1>
            <p>${errorMessage}</p>
            ${actionableGuidance}
            <script>
              setTimeout(() => {
                var t = ${JSON.stringify(String((req.session as any)?.tiktokOAuthParentOrigin || ''))};
                window.opener?.postMessage({ type: 'tiktok_oauth_error', error: ${JSON.stringify(errorMessage)} }, t || '*');
                window.close();
              }, 3000);
            </script>
          </body>
        </html>
      `);
    }
  });

