  app.post('/api/channel-connections/meta-channels-embedded-signup', ensureAuthenticated, ensureActiveSubscription, async (req: Request, res: Response) => {
    try {
      const { accessToken, authorizationCode, code, action } = req.body;
      const normalizedAuthorizationCode =
        (typeof code === 'string' && code.trim()) ||
        (typeof authorizationCode === 'string' && authorizationCode.trim()) ||
        undefined;
      const user = req.user as any;

      if (!user?.companyId) {
      return res.status(401).json({ message: 'User not authenticated or missing company', code: 'session_expired' });
      }

      const config = await storage.getPartnerConfiguration('meta');
      if (!config || !config.isActive) {
        return res.status(500).json({
          message: 'Meta partner configuration missing or inactive',
          error: 'Contact your administrator to configure Meta partner credentials in the admin panel',
          code: 'configuration_missing',
        });
      }

      if (!config.partnerApiKey || !config.partnerSecret) {
        return res.status(400).json({
          message: 'Meta partner configuration incomplete',
          error: 'App ID and App Secret are required',
          code: 'configuration_missing',
        });
      }

      if (action === 'fetch_assets') {
        try {
          const userToken = await metaGraphAPI.resolveUserAccessToken(
            accessToken,
            normalizedAuthorizationCode,
            config.partnerApiKey,
            config.partnerSecret
          );

          let pages: Awaited<ReturnType<typeof metaGraphAPI.getMessengerPages>>['pages'] = [];
          let accounts: Awaited<ReturnType<typeof metaGraphAPI.getInstagramAccounts>>['accounts'] = [];
          let messengerDiagnostics: Awaited<ReturnType<typeof metaGraphAPI.getMessengerPages>>['diagnostics'] = {
            grantedScopes: [],
            missingScopes: [],
            restrictedScopes: [],
            message: 'Messenger discovery was not attempted.',
          };
          let instagramDiagnostics: Awaited<ReturnType<typeof metaGraphAPI.getInstagramAccounts>>['diagnostics'] = {
            grantedScopes: [],
            missingScopes: [],
            restrictedScopes: [],
            message: 'Instagram discovery was not attempted.',
          };

          try {
            const messengerResult = await metaGraphAPI.getMessengerPages(
              userToken,
              config.partnerApiKey,
              config.partnerSecret
            );
            pages = messengerResult.pages;
            messengerDiagnostics = messengerResult.diagnostics;
          } catch (error: any) {
            console.error('Error discovering Messenger Pages:', error);
            messengerDiagnostics = {
              grantedScopes: [],
              missingScopes: [],
              restrictedScopes: [],
              code: 'no_eligible_assets',
              message: error.message || 'Failed to discover Messenger Pages',
            };
          }

          try {
            const instagramResult = await metaGraphAPI.getInstagramAccounts(
              userToken,
              config.partnerApiKey,
              config.partnerSecret
            );
            accounts = instagramResult.accounts;
            instagramDiagnostics = instagramResult.diagnostics;
          } catch (error: any) {
            console.error('Error discovering Instagram accounts:', error);
            instagramDiagnostics = {
              grantedScopes: [],
              missingScopes: [],
              restrictedScopes: [],
              code: 'no_eligible_assets',
              message: error.message || 'Failed to discover Instagram accounts',
            };
          }

          const sanitizedPages = pages.map(metaGraphAPI.sanitizePageForClient);
          const sanitizedInstagramAccounts = accounts.map(metaGraphAPI.sanitizeInstagramAccountForClient);

          if (pages.length === 0 && accounts.length === 0) {
            const primaryCode = messengerDiagnostics.code || instagramDiagnostics.code || 'no_eligible_assets';
            const primaryMessage =
              messengerDiagnostics.message ||
              instagramDiagnostics.message ||
              'No eligible Facebook Pages or Instagram accounts were found';

            return res.status(400).json({
              message: primaryMessage,
              code: primaryCode,
              pages: sanitizedPages,
              instagramAccounts: sanitizedInstagramAccounts,
              diagnostics: {
                messenger: messengerDiagnostics,
                instagram: instagramDiagnostics,
              },
            });
          }

          let messengerOnboardingSessionId: string | undefined;
          let instagramOnboardingSessionId: string | undefined;

          if (pages.length > 0) {
            messengerOnboardingSessionId = await metaGraphAPI.createOnboardingSession(
              userToken,
              user.id,
              user.companyId,
              'messenger',
              pages.map((page) => page.id)
            );
          }

          if (accounts.length > 0) {
            instagramOnboardingSessionId = await metaGraphAPI.createOnboardingSession(
              userToken,
              user.id,
              user.companyId,
              'instagram',
              accounts.map((account) => account.id)
            );
          }

          return res.json({
            pages: sanitizedPages,
            instagramAccounts: sanitizedInstagramAccounts,
            diagnostics: {
              messenger: messengerDiagnostics,
              instagram: instagramDiagnostics,
            },
            messengerOnboardingSessionId,
            instagramOnboardingSessionId,
          });
        } catch (error: any) {
          console.error('Error fetching Meta Channels assets:', error);
          return res.status(400).json({
            message: error.message || 'Failed to discover Meta Channels assets',
            code: 'no_eligible_assets',
            pages: [],
            instagramAccounts: [],
          });
        }
      }

      return res.status(400).json({ message: 'Invalid action' });
    } catch (error: any) {
      console.error('Error in Meta Channels embedded signup:', error);
      return res.status(500).json({
        message: 'Failed to process Meta Channels embedded signup',
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  });

