  app.post('/api/channel-connections/meta-messenger-embedded-signup', ensureAuthenticated, ensureActiveSubscription, async (req: Request, res: Response) => {
    try {
      const { accessToken, authorizationCode, code, action, connectionName, pageId, pageName } = req.body;
      const normalizedAuthorizationCode =
        (typeof code === 'string' && code.trim()) ||
        (typeof authorizationCode === 'string' && authorizationCode.trim()) ||
        undefined;
      const user = req.user as any;

      if (!user?.companyId) {
        return res.status(401).json({ message: 'User not authenticated or missing company' });
      }

      const config = await storage.getPartnerConfiguration('meta');
      if (!config || !config.isActive) {
        return res.status(500).json({
          message: 'Meta partner configuration missing or inactive',
          error: 'Contact your administrator to configure Meta partner credentials in the admin panel',
          code: 'configuration_missing',
        });
      }

      if (!config.partnerApiKey || !config.partnerSecret) {
        return res.status(400).json({
          message: 'Meta partner configuration incomplete',
          error: 'App ID and App Secret are required',
          code: 'configuration_missing',
        });
      }

      const origin = `${req.protocol}://${req.get('host')}`;
      const messengerWebhookUrl = resolveChannelWebhookUrl(config, 'messenger', origin);

      if (action === 'fetch_pages') {
        try {
          const userToken = await metaGraphAPI.resolveUserAccessToken(
            accessToken,
            normalizedAuthorizationCode,
            config.partnerApiKey,
            config.partnerSecret
          );

          const { pages, diagnostics } = await metaGraphAPI.getMessengerPages(
            userToken,
            config.partnerApiKey,
            config.partnerSecret
          );

          if (diagnostics.code && pages.length === 0) {
            return res.status(400).json({
              message: diagnostics.message,
              code: diagnostics.code,
              diagnostics,
              pages: [],
            });
          }

          if (pages.length === 0) {
            return res.status(400).json({
              message: diagnostics.message || 'No eligible Facebook Pages were found',
              code: diagnostics.code || 'no_eligible_assets',
              diagnostics,
              pages: [],
            });
          }

          const onboardingSessionId = await metaGraphAPI.createOnboardingSession(
            userToken,
            user.id,
            user.companyId,
            'messenger',
            pages.map((page) => page.id)
          );

          return res.json({
            pages: pages.map(metaGraphAPI.sanitizePageForClient),
            diagnostics,
            onboardingSessionId,
          });
        } catch (error: any) {
          console.error('Error fetching Pages:', error);
          return res.status(400).json({
            message: error.message || 'Failed to fetch Facebook Pages',
            code: 'no_eligible_assets',
            pages: [],
          });
        }
      } else if (action === 'create_connection') {
        if (!pageId || !connectionName) {
        return res.status(400).json({ message: 'Page ID and connection name are required', code: 'validation_error' });
        }

        const { onboardingSessionId, pageAccessToken } = req.body;
        let longLivedToken: string;

        if (onboardingSessionId) {
          const userToken = await metaGraphAPI.consumeOnboardingSession(
            onboardingSessionId,
            user.id,
            user.companyId,
            'messenger',
            pageId
          );
          if (!userToken) {
          return res.status(400).json({
            message: 'Onboarding session expired or invalid. Log in again and retry.',
            code: 'session_expired',
            });
          }

          longLivedToken = await metaGraphAPI.getPageAccessToken(
            pageId,
            userToken,
            config.partnerApiKey,
            config.partnerSecret
          );
        } else if (
          isMetaLegacyTokenOnboardingAllowed() &&
          typeof pageAccessToken === 'string' &&
          pageAccessToken.trim()
        ) {
          longLivedToken = pageAccessToken.trim();

          const scopeDiagnostics = await metaGraphAPI.inspectTokenScopes(
            longLivedToken,
            config.partnerApiKey,
            config.partnerSecret,
            MESSENGER_LOGIN_SCOPES
          );
          if (
            scopeDiagnostics.missingScopes.length > 0 ||
            scopeDiagnostics.restrictedScopes.length > 0
          ) {
            return res.status(400).json({
              message: scopeDiagnostics.message || 'Page token is missing required Messenger permissions',
              code: scopeDiagnostics.code || 'missing_permissions',
              diagnostics: scopeDiagnostics,
            });
          }

          const validatedPage = await metaGraphAPI.getPageInfo(pageId, longLivedToken);
          if (String(validatedPage?.id) !== String(pageId)) {
            return res.status(400).json({
              message: 'Selected Page could not be validated with the provided token',
              code: 'no_eligible_assets',
            });
          }
        } else {
        return res.status(400).json({
          message: 'Onboarding session ID is required',
          code: 'session_expired',
          });
        }

        try {

          const rawPageInfo = await metaGraphAPI.getPageInfo(pageId, longLivedToken);
          const { access_token: _pageToken, ...pageInfo } = rawPageInfo;
          const verifyToken = config.webhookVerifyToken?.trim() || '';

          const connection = await storage.createChannelConnection({
            userId: user.id,
            companyId: user.companyId,
            channelType: 'messenger',
            accountId: pageId,
            accountName: connectionName,
            accessToken: longLivedToken,
            connectionData: {
              pageId: pageId,
              appId: config.partnerApiKey,
              webhookUrl: messengerWebhookUrl,
              verifyToken,
              pageInfo: pageInfo,
            },
            status: 'active',
          });

          await messengerService.connect(connection.id, user.id, user.companyId);

          const webhookSubscriptionStatus = await messengerService.setupWebhook(
            connection.id,
            messengerWebhookUrl,
            verifyToken,
            { appSecret: config.partnerSecret }
          );

          const updatedConnection =
            (await storage.getChannelConnection(connection.id)) || connection;

          broadcastToCompany({
            type: 'channelConnectionCreated',
            data: metaGraphAPI.sanitizeMetaConnectionForClient(updatedConnection),
          }, user.companyId);

          const responseBody: Record<string, unknown> = {
            connection: metaGraphAPI.sanitizeMetaConnectionForClient(updatedConnection),
            message: webhookSubscriptionStatus.success
              ? 'Messenger connection created successfully'
              : 'Messenger connection created but webhook subscription failed',
            webhookSubscriptionStatus,
          };

          if (!webhookSubscriptionStatus.success) {
            responseBody.warning =
              webhookSubscriptionStatus.error ||
              'Webhook subscription failed — messages may not be delivered until subscription is fixed';
          }

          return res.status(201).json(responseBody);
        } catch (error: any) {
          console.error('Error creating Messenger connection:', error);
          return res.status(400).json({
            message: error.message || 'Failed to create Messenger connection',
            code: 'no_eligible_assets',
          });
        }
      } else {
      return res.status(400).json({ message: 'Invalid action', code: 'invalid_action' });
      }
    } catch (error: any) {
      console.error('Error in Messenger embedded signup:', error);
      return res.status(500).json({
        message: 'Failed to process Messenger embedded signup',
        error: error instanceof Error ? error.message : 'Unknown error',
        code: 'connection_failed',
      });
    }
  });

