  const validateInstagramConnectionHasResolvableSecret = async (
    channelType: string | undefined,
    connectionData: Record<string, any> | null | undefined
  ): Promise<string | null> => {
    if (channelType !== 'instagram') return null;
    if (connectionData?.appSecret && String(connectionData.appSecret).trim()) return null;
    if (await hasActiveMetaPartnerSecret()) return null;
    return instagramAppSecretRequiredMessage;
  };

  const instagramAppSecretMismatchMessage =
    'Meta could not validate the Instagram access token with this App Secret. Verify you used the correct app secret for the app that issued the token (Instagram app secret for Instagram-Login apps, not a Facebook app secret).';

  const instagramAccessTokenExpiredMessage =
    'Instagram access token is expired or revoked. Generate a new long-lived token and save the connection again.';

  const validateInstagramTokenSecretPair = async (
    channelType: string | undefined,
    connectionData: Record<string, any> | null | undefined,
    accessToken: string | null | undefined
  ): Promise<string | null> => {
    if (channelType !== 'instagram') return null;

    const appId = connectionData?.appId ? String(connectionData.appId).trim() : '';
    const appSecret = connectionData?.appSecret ? String(connectionData.appSecret).trim() : '';
    const token = accessToken ? String(accessToken).trim() : '';
    if (!appId || !appSecret || !token) return null;

    try {
      const diagnostics = await metaGraphAPI.debugToken(token, appId, appSecret, INSTAGRAM_LOGIN_SCOPES);
      if (diagnostics.code === 'token_invalid_or_expired') {
        return instagramAccessTokenExpiredMessage;
      }
    } catch (error) {
      console.warn('Unable to validate Instagram token/app secret pair with Meta; saving connection anyway:', error);
    }

    return null;
  };

