  app.get('/api/whatsapp/qr/:connectionId', ensureAuthenticated, async (req: any, res) => {
    try {
      const connectionId = parseInt(req.params.connectionId);
      const connection = await storage.getChannelConnection(connectionId);
      if (!connection) {
        return res.status(404).json({ message: 'Connection not found' });
      }
      const owned = await isConnectionOwnedByCompany(connectionId, req.user?.companyId);
      if (!owned) {
        return res.status(403).json({ message: 'Forbidden' });
      }
      const qrCode = whatsAppService.getLastQrCode(connectionId);
      const { lastQrAt } = whatsAppService.getConnectionStateStatus(connectionId);
      const QR_MAX_AGE_MS = 60000;
      const now = Date.now();
      const isFresh = qrCode && lastQrAt && (now - lastQrAt.getTime()) < QR_MAX_AGE_MS;
      if (isFresh && lastQrAt) {
        const expiresIn = Math.max(0, Math.floor((QR_MAX_AGE_MS - (now - lastQrAt.getTime())) / 1000));
        return res.status(200).json({ qrCode, expiresIn });
      }
      return res.status(200).json({ qrCode: null, status: connection.status });
    } catch (err: any) {
      res.status(400).json({ message: err.message });
    }
  });

