  app.get('/api/contacts/pins', ensureAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const permissions = await getUserPermissions(user);
      const contactScope = resolveContactViewScope(permissions, user.isSuperAdmin);
      if (!contactScope || (!user.isSuperAdmin && !user.companyId)) {
        return res.status(403).json({ message: 'You do not have permission to view contacts' });
      }
      const savedPins = await storage.getPinnedContactIds(user.id);
      const allowedPins = new Set(await storage.getAccessibleContactIds(savedPins, {
        companyId: user.isSuperAdmin ? undefined : user.companyId, userId: user.id, contactScope,
      }));
      const pinnedIds = savedPins.filter(id => allowedPins.has(id));

      let pinnedContacts: Contact[] = [];
      if (pinnedIds.length > 0) {
        if (user.isSuperAdmin) {
          pinnedContacts = await storage.getContactsByIds(pinnedIds);
        } else if (user.companyId) {
          pinnedContacts = await storage.getContactsByIdsForCompany(user.companyId, pinnedIds);
        }

        const contactsById = new Map(pinnedContacts.map((contact) => [contact.id, contact]));
        pinnedContacts = pinnedIds
          .map((id) => contactsById.get(id))
          .filter((contact): contact is Contact => !!contact);

        const permissions = await getUserPermissions(user);
        if (!user.isSuperAdmin && permissions[PERMISSIONS.VIEW_CONTACT_PHONE] !== true) {
          pinnedContacts = pinnedContacts.map((contact) => ({ ...contact, phone: null, identifier: null }));
        }
      }

      res.json({ pinnedIds, contacts: pinnedContacts });
    } catch (error) {
      console.error('[Contacts API] Error fetching pinned contacts:', error);
      res.status(500).json({ message: 'Failed to fetch pinned contacts' });
    }
  });

