  app.patch('/api/contacts/:id', ensureAuthenticated, async (req, res) => {
    try {
      const id = parseInt(req.params.id);

      if (!Number.isInteger(id) || id <= 0) {
        return res.status(400).json({ message: 'Invalid contact ID' });
      }

      const contact = await storage.getContact(id);
      const user = req.user as any;
      if (!contact || !user?.companyId || contact.companyId !== user.companyId) {
        return res.status(404).json({ message: 'Contact not found' });
      }

      const permissions = user.isSuperAdmin ? {} : await getUserPermissions(user);
      if (!user.isSuperAdmin && permissions[PERMISSIONS.MANAGE_CONTACTS] !== true) {
        return res.status(403).json({ message: 'Manage contacts permission is required' });
      }

      const updateData = validateBody(editableContactSchema.partial(), req.body);
      if (updateData.colombiaFiscalProfile !== undefined && updateData.colombiaFiscalProfile !== null) {
        const parsedFiscalProfile = colombiaCustomerFiscalProfileSchema.safeParse(updateData.colombiaFiscalProfile);
        if (!parsedFiscalProfile.success) {
          return res.status(400).json({
            message: await serverI18n.t('erp.electronicInvoicing.errors.invalidFiscalProfile', user.languagePreference ?? 'en', 'Invalid Colombia fiscal profile'),
            errors: parsedFiscalProfile.error.flatten(),
          });
        }
        updateData.colombiaFiscalProfile = parsedFiscalProfile.data;
      }
      if (updateData.customFields !== undefined) {
        updateData.customFields = await validateEntityCustomFields({
          companyId: user.companyId,
          ownerType: 'contact',
          ownerId: id,
          input: updateData.customFields,
          enforceRequired: true,
          existingValues: contact.customFields as Record<string, unknown> | null,
          allowClinicalContactDocuments: user.isSuperAdmin || permissions[PERMISSIONS.VIEW_DENTAL_IMAGING] === true,
        });
      }

      if (updateData.whatsappUsername !== undefined) {
        const rawUsername = String(updateData.whatsappUsername || '').trim();
        if (!rawUsername) {
          updateData.whatsappUsername = null;
          updateData.whatsappUsernameUpdatedAt = new Date();
        } else if (!validateUsername(rawUsername)) {
          return res.status(400).json({
            code: 'WHATSAPP_USERNAME_INVALID',
            message: 'WhatsApp username must be 3-35 characters using letters, numbers, periods or underscores'
          });
        } else {
          updateData.whatsappUsername = normalizeUsername(rawUsername);
          updateData.whatsappUsernameUpdatedAt = new Date();
        }
      }


      if (updateData.identifierType && !updateData.source) {
        if (updateData.identifierType === 'whatsapp_official') {
          updateData.source = 'whatsapp_official';
        } else if (updateData.identifierType === 'whatsapp_unofficial' || updateData.identifierType === 'whatsapp') {
          updateData.source = 'whatsapp';
        } else if (updateData.identifierType === 'messenger') {
          updateData.source = 'messenger';
        } else if (updateData.identifierType === 'instagram') {
          updateData.source = 'instagram';
        }
      }

      const updatedContact = await storage.updateContact(id, updateData);

      if (updateData.customFields !== undefined) {
        await removeUnreferencedCustomFieldAttachments({
          companyId: contact.companyId!,
          ownerType: 'contact',
          ownerId: id,
          customFields: updatedContact.customFields as Record<string, unknown> | null,
        });
      }


      const changedFields = Object.keys(updateData).filter(key =>
        contact[key as keyof typeof contact] !== updateData[key]
      );

      if (changedFields.length > 0) {
        const oldValues: any = {};
        const newValues: any = {};

        changedFields.forEach(field => {
          oldValues[field] = contact[field as keyof typeof contact];
          newValues[field] = updateData[field];
        });

        await logContactAudit({
          companyId: contact.companyId!,
          contactId: contact.id,
          userId: (req.user as any)?.id,
          actionType: 'updated',
          actionCategory: 'contact',
          description: `Contact updated: ${changedFields.join(', ')} changed`,
          oldValues,
          newValues,
          ipAddress: req.ip,
          userAgent: req.get('User-Agent')
        });
      }

      const canViewPhone = user.isSuperAdmin || permissions[PERMISSIONS.VIEW_CONTACT_PHONE] === true;
      const contactForBroadcast = canViewPhone ? updatedContact : { ...updatedContact, phone: null, identifier: null };
      if ((global as any).broadcastToAllClients) {
        (global as any).broadcastToAllClients({
          type: 'contactUpdated',
          data: contactForBroadcast
        });
      }

      if (!user.isSuperAdmin && !canViewPhone) {
        return res.json({ ...updatedContact, phone: null, identifier: null });
      }
      res.json(updatedContact);
    } catch (error) {
      console.error('Error updating contact:', error);
      if (error instanceof ContactCustomFieldValidationError) {
        return res.status(400).json({ message: error.message, fieldName: error.fieldName });
      }
      res.status(500).json({ message: 'Failed to update contact' });
    }
  });


