  app.post('/api/contacts/:contactId/appointments', ensureAuthenticated, async (req: any, res) => {
    try {
      const contactId = parseInt(req.params.contactId);
      const companyId = req.user?.companyId;
      const { title, description, location, scheduledAt, durationMinutes, type, status } = req.body;

      if (!companyId) {
        return res.status(400).json({ error: 'Company ID required' });
      }

      if (!title || !scheduledAt) {
        return res.status(400).json({ error: 'Title and scheduled time are required' });
      }


      const contact = await storage.getContact(contactId);
      if (!contact || contact.companyId !== companyId) {
        return res.status(404).json({ error: 'Contact not found' });
      }

      if (!(await ensureDentalScheduleContactAccess(req, res, 'manage'))) return;

      const businessTypeSetting = await storage.getCompanySetting(companyId, ERP_BUSINESS_TYPE_SETTING_KEY);
      const isDental = normalizeErpBusinessType(businessTypeSetting?.value) === 'dental';
      if (isDental && ('durationMinutes' in req.body || 'type' in req.body)) {
        return res.status(422).json({
          error: 'Dental appointment duration and type are derived from catalogItemId',
          code: 'service_fields_are_authoritative',
        });
      }
      const dentalFields = isDental
        ? {
            providerUserId: req.body.providerUserId ?? null,
            chairId: req.body.chairId ?? null,
            isRecall: Boolean(req.body.isRecall),
            recallDueAt: req.body.recallDueAt ? new Date(req.body.recallDueAt) : null,
            status: status || 'scheduled',
          }
        : {};
      if (!isDental && (req.body.providerUserId != null || req.body.chairId != null || req.body.isRecall || req.body.recallDueAt || status === 'no_show')) {
        return res.status(400).json({ error: 'Dental appointment fields are only allowed when Dental ERP mode is enabled' });
      }
      // Hold/request states belong to the dental booking lifecycle, not generic CRUD.
      if (status != null && !(CONTACT_APPOINTMENT_BASE_STATUSES as readonly string[]).includes(status)) {
        return res.status(400).json({ error: 'Invalid appointment status' });
      }

      const appointmentData = {
        contactId,
        companyId,
        title,
        description: description || '',
        location: location || '',
        scheduledAt: new Date(scheduledAt),
        durationMinutes: durationMinutes || 60,
        type: type || 'meeting',
        createdBy: req.user.id,
        ...dentalFields,
      };

      const appointment = isDental
        ? await createManualDentalAppointment(companyId, {
            contactId,
            catalogItemId: String(req.body.catalogItemId ?? ''),
            title,
            description: description || null,
            location: location || null,
            scheduledAt,
            status: status || 'scheduled',
            providerUserId: req.body.providerUserId ?? null,
            chairId: req.body.chairId ?? null,
            isRecall: Boolean(req.body.isRecall),
            recallDueAt: req.body.recallDueAt ? new Date(req.body.recallDueAt) : null,
            overrideReason: req.body.overrideReason ?? null,
          }, {
            userId: req.user.id,
            ipAddress: req.ip,
            userAgent: req.get('User-Agent'),
          })
        : await storage.createContactAppointment(appointmentData);


      await logContactAudit({
        companyId,
        contactId,
        userId: req.user.id,
        actionType: 'appointment_created',
        actionCategory: 'appointment',
        description: `Appointment created: ${appointment.title}`,
        newValues: {
          title: appointment.title,
          description: appointment.description,
          location: appointment.location,
          scheduledAt: appointment.scheduledAt,
          durationMinutes: appointment.durationMinutes,
          type: appointment.type
        },
        metadata: {
          appointmentId: appointment.id
        },
        ipAddress: req.ip,
        userAgent: req.get('User-Agent')
      });

      res.status(201).json(appointment);
    } catch (error) {
      const mapped = getErpErrorResponse(error);
      if (mapped) return res.status(mapped.status).json({
        error: mapped.message,
        ...(mapped.code ? { code: mapped.code } : {}),
        ...(mapped.details !== undefined ? { details: mapped.details } : {}),
      });
      console.error('Error creating contact appointment:', error);
      res.status(500).json({ error: 'Failed to create appointment' });
    }
  });


  app.patch('/api/contacts/:contactId/appointments/:appointmentId', ensureAuthenticated, async (req: any, res) => {
    try {
      const contactId = parseInt(req.params.contactId);
      const appointmentId = parseInt(req.params.appointmentId);
      const companyId = req.user?.companyId;

      if (!companyId) {
        return res.status(400).json({ error: 'Company ID required' });
      }


      const contact = await storage.getContact(contactId);
      if (!contact || contact.companyId !== companyId) {
        return res.status(404).json({ error: 'Contact not found' });
      }

      if (!(await ensureDentalScheduleContactAccess(req, res, 'manage'))) return;

      const appointment = await storage.getContactAppointment(appointmentId);
      if (!appointment || appointment.contactId !== contactId) {
        return res.status(404).json({ error: 'Appointment not found' });
      }

      const businessTypeSetting = await storage.getCompanySetting(companyId, ERP_BUSINESS_TYPE_SETTING_KEY);
      const isDental = normalizeErpBusinessType(businessTypeSetting?.value) === 'dental';
      if (isDental && ('durationMinutes' in req.body || 'type' in req.body)) {
        return res.status(422).json({
          error: 'Dental appointment duration and type are derived from catalogItemId',
          code: 'service_fields_are_authoritative',
        });
      }
      const dentalKeys = ['providerUserId', 'chairId', 'isRecall', 'recallDueAt'];
      const hasDentalPayload = dentalKeys.some((key) => key in req.body) || req.body.status === 'no_show';
      if (!isDental && hasDentalPayload) {
        return res.status(400).json({ error: 'Dental appointment fields are only allowed when Dental ERP mode is enabled' });
      }
      // Hold/request states belong to the dental booking lifecycle, not generic CRUD.
      if ('status' in req.body && !(CONTACT_APPOINTMENT_BASE_STATUSES as readonly string[]).includes(req.body.status)) {
        return res.status(400).json({ error: 'Invalid appointment status' });
      }

      const allowed = [
        'title', 'description', 'location', 'scheduledAt', 'durationMinutes', 'type', 'status',
        ...(isDental ? dentalKeys : []),
      ];
      const updateData: Record<string, unknown> = {};
      for (const key of allowed) {
        if (key in req.body) updateData[key] = req.body[key];
      }
      if (updateData.scheduledAt) {
        updateData.scheduledAt = new Date(updateData.scheduledAt as string);
      }
      if (isDental && 'recallDueAt' in updateData) {
        updateData.recallDueAt = updateData.recallDueAt ? new Date(updateData.recallDueAt as string) : null;
      }
      if (!isDental && appointment.companyId == null) {
        updateData.companyId = companyId;
      }

      const updatedAppointment = isDental
        ? await updateManualDentalAppointment(companyId, appointmentId, {
            ...(updateData as any),
            catalogItemId: req.body.catalogItemId,
            overrideReason: req.body.overrideReason,
          }, {
            userId: req.user.id,
            ipAddress: req.ip,
            userAgent: req.get('User-Agent'),
          })
        : await storage.updateContactAppointment(appointmentId, updateData);
      res.json(updatedAppointment);
    } catch (error) {
      const mapped = getErpErrorResponse(error);
      if (mapped) return res.status(mapped.status).json({
        error: mapped.message,
        ...(mapped.code ? { code: mapped.code } : {}),
        ...(mapped.details !== undefined ? { details: mapped.details } : {}),
      });
      console.error('Error updating contact appointment:', error);
      res.status(500).json({ error: 'Failed to update appointment' });
    }
  });


