  app.post('/api/contacts/:id/update-profile-picture', ensureAuthenticated, ensureActiveSubscription, requirePermission(PERMISSIONS.MANAGE_CONTACTS), async (req: any, res) => {
    try {
      const contactId = parseInt(req.params.id);
      const connectionId = Number(req.body?.connectionId);
      const forceRefresh = req.body?.forceRefresh !== false;
      const companyId = req.user?.companyId;

      if (!companyId || !Number.isInteger(contactId) || contactId <= 0) {
        return res.status(400).json({ code: 'INVALID_CONTACT' });
      }
      if (!Number.isInteger(connectionId) || connectionId <= 0) {
        return res.status(400).json({ message: 'Connection ID is required' });
      }

      const contact = await storage.getContact(contactId);
      if (!contact || contact.companyId !== companyId) {
        return res.status(404).json({ message: 'Contact not found' });
      }

      const contactIdentifier = contact.identifier || contact.phone || null;
      const isWhatsApp = contact.identifierType === 'whatsapp' || contact.identifierType === 'whatsapp_unofficial';
      const isTelegram = contact.identifierType === 'telegram';
      const isInstagram = contact.identifierType === 'instagram';
      if ((!isWhatsApp && !isTelegram && !isInstagram) || !contactIdentifier) {
        return res.status(400).json({ message: 'Contact does not have a supported channel identifier' });
      }

      const connection = await storage.getChannelConnection(connectionId);
      if (!connection || connection.companyId !== companyId) {
        return res.status(404).json({ message: 'Connection not found' });
      }

      const permissions = await getUserPermissions(req.user);
      const canViewPhone = (req.user as any).isSuperAdmin || permissions[PERMISSIONS.VIEW_CONTACT_PHONE] === true;

      if (!forceRefresh && contact.avatarUrl) {
        const avatarAge = Date.now() - new Date(contact.updatedAt || contact.createdAt || Date.now()).getTime();
        const maxAge = 24 * 60 * 60 * 1000;

        if (avatarAge < maxAge) {
          const contactToReturn = canViewPhone ? contact : { ...contact, phone: null, identifier: null };
          return res.json({
            success: true,
            contact: contactToReturn,
            profilePictureUrl: contact.avatarUrl,
            cached: true
          });
        }
      }

      let profilePictureUrl: string | null = null;
      let updatedContact = contact;

      if (isWhatsApp) {
        const isActive = whatsAppService.isConnectionActive(connectionId);
        if (!isActive) {
          return res.status(400).json({ message: 'WhatsApp connection is not active' });
        }

        profilePictureUrl = await whatsAppService.fetchProfilePicture(
          connectionId,
          contactIdentifier,
          true,
          forceRefresh,
          `${connectionId}-${contact.id}`,
        );
        updatedContact = await storage.updateContact(contactId, {
          avatarUrl: profilePictureUrl || null
        });
      } else if (isTelegram) {
        if (connection.channelType !== 'telegram') {
          return res.status(400).json({ message: 'Selected connection is not a Telegram connection' });
        }
        if (!connection.companyId) {
          return res.status(400).json({ message: 'Telegram connection is missing company context' });
        }

        profilePictureUrl = await fetchTelegramUserProfilePhoto(
          connection as any,
          contactIdentifier,
          connection.companyId
        );
        updatedContact = await storage.updateContact(contactId, {
          avatarUrl: profilePictureUrl || null
        });
      } else if (isInstagram) {
        if (connection.channelType !== 'instagram') {
          return res.status(400).json({ message: 'Selected connection is not an Instagram connection' });
        }
        const refreshResult = await instagramService.refreshContactInstagramProfile(contactId, connectionId);
        if (!refreshResult.success) {
          return res.status(400).json({ message: refreshResult.error || 'Failed to refresh Instagram profile' });
        }
        updatedContact = refreshResult.contact!;
        profilePictureUrl = refreshResult.profilePictureUrl || null;
      }

      const contactForBroadcast = canViewPhone ? updatedContact : { ...updatedContact, phone: null, identifier: null };
      if ((global as any).broadcastToAllClients) {
        (global as any).broadcastToAllClients({
          type: 'contactUpdated',
          data: contactForBroadcast
        });
      }

      const contactToReturn = canViewPhone ? updatedContact : { ...updatedContact, phone: null, identifier: null };
      res.json({
        success: true,
        contact: contactToReturn,
        profilePictureUrl: profilePictureUrl || null,
        noPicture: !profilePictureUrl,
        cached: false
      });
    } catch (err: any) {
      console.error('Error updating contact profile picture:', err);
      res.status(500).json({ message: err.message || 'Failed to update contact profile picture' });
    }
  });

  app.post('/api/conversations/:id/update-group-picture', ensureAuthenticated, ensureActiveSubscription, requireAnyPermission([PERMISSIONS.VIEW_ALL_CONVERSATIONS, PERMISSIONS.VIEW_ASSIGNED_CONVERSATIONS]), async (req: any, res) => {
    try {
      const conversationId = parseInt(req.params.id);
      const { connectionId } = req.body;

      if (!connectionId) {
        return res.status(400).json({ message: 'WhatsApp connection ID is required' });
      }

      const conversation = await storage.getConversation(conversationId);
      if (!conversation) {
        return res.status(404).json({ message: 'Conversation not found' });
      }

      if (!conversation.isGroup || !conversation.groupJid) {
        return res.status(400).json({
          message: 'This conversation is not a group chat'
        });
      }
      if (!canAccessGroupConversation(req, conversation) || !await areCompanyGroupChatsEnabled(req.user.companyId)) {
        return res.status(403).json({ message: 'Access denied' });
      }
      if (connectionId !== conversation.channelId) {
        return res.status(400).json({ message: 'Group conversations cannot switch WhatsApp connections' });
      }

      const connection = await storage.getChannelConnection(connectionId);
      if (!connection) {
        return res.status(404).json({ message: 'Connection not found' });
      }



      const isActive = whatsAppService.isConnectionActive(connectionId);
      if (!isActive) {
        return res.status(400).json({ message: 'WhatsApp connection is not active' });
      }



      const groupPictureUrl = await whatsAppService.fetchGroupProfilePicture(
        connectionId,
        conversation.groupJid
      );



      if (!groupPictureUrl) {
        return res.status(404).json({ message: 'No group profile picture found' });
      }

      const updatedGroupMetadata = {
        ...(conversation.groupMetadata || {}),
        profilePictureUrl: groupPictureUrl
      };

      const updatedConversation = await storage.updateConversation(conversationId, {
        groupMetadata: updatedGroupMetadata
      });

      broadcastToAll({
        type: 'conversationUpdated',
        data: updatedConversation,
      }, conversation.companyId ?? undefined);

      res.json({
        success: true,
        conversation: updatedConversation,
        groupPictureUrl
      });
    } catch (err: any) {
      console.error('Error updating group profile picture:', err);
      res.status(500).json({ message: err.message || 'Failed to update group profile picture' });
    }
  });



  app.get('/api/conversations', ensureAuthenticated, ensureActiveSubscription, requireAnyPermission([PERMISSIONS.VIEW_ALL_CONVERSATIONS, PERMISSIONS.VIEW_ASSIGNED_CONVERSATIONS]), async (req, res) => {
    try {
      const user = req.user as any;
      const userPermissions = (req as any).userPermissions;

      const page = parseInt(req.query.page as string) || 1;
      const limit = parseInt(req.query.limit as string) || 50;
      const search = req.query.search as string;

      const companyId = user.isSuperAdmin ? undefined : user.companyId;

      const assignedToUserId = (userPermissions && !userPermissions[PERMISSIONS.VIEW_ALL_CONVERSATIONS]) ? user.id : undefined;

      const { conversations, total } = await storage.getConversations({
        companyId,
        page,
        limit,
        search,
        assignedToUserId
      });

      const conversationsWithContacts = await Promise.all(
        conversations.map(async (conversation) => {
          const contact = conversation.contactId ? await storage.getContact(conversation.contactId) : null;
          const channelConnection = conversation.channelId ? await storage.getChannelConnection(conversation.channelId) : null;
          return {
            ...conversation,
            contact,
            channelConnection
          };
        })
      );

      const telegramIdsNeedingPreview = conversationsWithContacts
        .filter((c: any) => c.channelType === 'telegram' && !(c as any).lastMessage)
        .map((c: any) => c.id);
      const telegramLatest =
        telegramIdsNeedingPreview.length > 0
          ? await storage.getLatestMessageForConversations(telegramIdsNeedingPreview)
          : {};
      const conversationsWithLastMessage = conversationsWithContacts.map((c: any) => {
        if (c.channelType !== 'telegram' || c.lastMessage) {
          return c;
        }
        const lm = telegramLatest[c.id];
        return lm ? { ...c, lastMessage: lm } : c;
      });

      res.json({
        conversations: conversationsWithLastMessage,
        total: total,
        page,
        limit,
        totalPages: Math.ceil(total / limit)
      });
    } catch (error) {
      console.error('Error fetching conversations:', error);
      res.status(500).json({ error: 'Failed to fetch conversations' });
    }
  });

