  app.post('/api/conversations/whatsapp/initiate', ensureAuthenticated, ensureActiveSubscription,
    requireAnyPermission([PERMISSIONS.VIEW_ALL_CONVERSATIONS, PERMISSIONS.VIEW_ASSIGNED_CONVERSATIONS]), async (req: any, res) => {
    try {
      const { name, phoneNumber, recipient, usernameKey, channelConnectionId, initialMessage, contactId } = req.body;

      const recipientInput = String(recipient ?? phoneNumber ?? '').trim();
      if (!name || !recipientInput || !channelConnectionId) {
        return res.status(400).json({
          message: 'Name, phone number or @username, and channel connection ID are required'
        });
      }

      const parsedRecipient = parseWhatsAppRecipientInput(recipientInput);
      if (!parsedRecipient) {
        return res.status(400).json({
          message: 'Please enter a valid phone number or @username'
        });
      }

      const isUsernameRecipient = parsedRecipient.type === 'username';
      const cleanPhoneNumber = parsedRecipient.type === 'phone' ? parsedRecipient.value : '';

      if (parsedRecipient.type === 'phone' && cleanPhoneNumber.length < 10) {
        return res.status(400).json({
          message: 'Please enter a valid phone number with at least 10 digits'
        });
      }


      if (cleanPhoneNumber && isWhatsAppGroupChatId(cleanPhoneNumber)) {
        return res.status(400).json({
          message: 'Cannot initiate conversations with WhatsApp group chat IDs'
        });
      }

      const channelConnection = await storage.getChannelConnection(channelConnectionId);
      if (!channelConnection) {
        return res.status(404).json({ message: 'Channel connection not found' });
      }


      if (!req.user || !req.user.companyId) {
        return res.status(400).json({ message: 'Company ID is required for multi-tenant security' });
      }


      if (channelConnection.companyId !== req.user.companyId) {
        return res.status(403).json({ message: 'Access denied: Connection does not belong to your company' });
      }


      const supportedChannelTypes = ['whatsapp_unofficial', 'whatsapp', 'whatsapp_official'];
      if (!supportedChannelTypes.includes(channelConnection.channelType)) {
        return res.status(400).json({
          message: `Unsupported channel type: ${channelConnection.channelType}`
        });
      }

      if (isBaileysChannel(channelConnection.channelType) && !isChannelAvailable(channelConnection)) {
        return res.status(400).json({
          message: 'WhatsApp connection is not active. Please reconnect in Settings.'
        });
      }

      let identifierType = 'whatsapp';
      switch (channelConnection.channelType) {
        case 'whatsapp_official':
          identifierType = 'whatsapp_official';
          break;
        case 'whatsapp_unofficial':
        case 'whatsapp':
          identifierType = 'whatsapp_unofficial';
          break;
        default:
          identifierType = channelConnection.channelType;
      }

      let contact = null;
      let resolvedUsernameLid: string | null = null;

      if (contactId) {
        contact = await storage.getContact(Number(contactId));
        if (!contact || contact.companyId !== req.user.companyId) return res.status(403).json({ message: 'Access denied' });
        const expected = parseWhatsAppRecipientInput(contact.phone || contact.identifier || '');
        if (!expected || expected.type !== parsedRecipient.type || expected.value !== parsedRecipient.value) {
          return res.status(400).json({ message: 'Recipient does not match the selected contact' });
        }
      } else if (isUsernameRecipient) {
        const username = parsedRecipient.value;
        contact = (await storage.getContactByWhatsAppUsername(username, req.user.companyId)) ?? null;

        if (!contact) {
          if (channelConnection.channelType === 'whatsapp_official') {
            return res.status(404).json({
              message: `No contact found with username @${username}. WhatsApp Business API cannot look up usernames - the user must message you first.`
            });
          }

          const sock = getWhatsAppConnection(channelConnectionId);
          if (!sock) {
            return res.status(400).json({
              message: 'WhatsApp connection is not active. Please reconnect in Settings.'
            });
          }

          let resolution;
          try {
            resolution = await resolveUsernameViaUSync(sock, username, usernameKey ? String(usernameKey) : undefined);
          } catch (resolveError: any) {
            return res.status(400).json({
              message: resolveError?.message || `Could not look up @${username} on WhatsApp`
            });
          }

          if (!resolution.exists) {
            if (resolution.keyRequired) {
              return res.status(400).json({
                message: `@${username} requires a username key (PIN). Enter the key this user shared with you and try again.`
              });
            }
            if (resolution.usernameTaken === true) {
              return res.status(404).json({
                message: `@${username} exists on WhatsApp, but this linked connection could not open a chat with it. Try their phone number, or message them first from the WhatsApp app on the linked phone.`
              });
            }
            if (resolution.usernameTaken === false) {
              return res.status(404).json({
                message: `@${username} is not registered as a WhatsApp username.`
              });
            }
            return res.status(404).json({
              message: `@${username} was not found on WhatsApp. Check the username (and the username key, if they have one set).`
            });
          }
          resolvedUsernameLid = resolution.lid;

          const contactData: InsertContact = {
            companyId: req.user.companyId,
            name,
            phone: null,
            identifier: username,
            identifierType: identifierType,
            source: 'manual',
            email: null,
            avatarUrl: null,
            company: null,
            tags: null,
            isActive: true,
            notes: null,
            createdBy: req.user.id,
            whatsappUsername: username,
            whatsappUsernameUpdatedAt: new Date(),
            ...(resolvedUsernameLid ? { whatsappLid: resolvedUsernameLid } : {})
          };

          contact = await storage.getOrCreateContact(contactData);
        }
      } else if (parsedRecipient.type === 'lid') {
        contact = (await storage.getContactByWhatsAppLid(parsedRecipient.value, req.user.companyId)) ?? null;
        if (!contact) {
          const contactData: InsertContact = {
            companyId: req.user.companyId,
            name,
            phone: null,
            identifier: parsedRecipient.value,
            identifierType: identifierType,
            source: 'manual',
            email: null,
            avatarUrl: null,
            company: null,
            tags: null,
            isActive: true,
            notes: null,
            createdBy: req.user.id,
            whatsappLid: parsedRecipient.value
          };
          contact = await storage.getOrCreateContact(contactData);
        }
      } else if (parsedRecipient.type === 'bsuid') {
        contact = (await storage.getContactByWhatsAppBsuid(parsedRecipient.value, req.user.companyId)) ?? null;
        if (!contact) {
          if (channelConnection.channelType !== 'whatsapp_official') {
            return res.status(400).json({
              message: 'BSUID recipients are only supported on WhatsApp Business API connections'
            });
          }
          const contactData: InsertContact = {
            companyId: req.user.companyId,
            name,
            phone: null,
            identifier: parsedRecipient.value,
            identifierType: identifierType,
            source: 'manual',
            email: null,
            avatarUrl: null,
            company: null,
            tags: null,
            isActive: true,
            notes: null,
            createdBy: req.user.id,
            whatsappBsuid: parsedRecipient.value
          };
          contact = await storage.getOrCreateContact(contactData);
        }
      } else {
        contact = await storage.getContactByIdentifier(cleanPhoneNumber, 'whatsapp');

        if (!contact) {
          const contactData: InsertContact = {
            companyId: req.user.companyId,
            name,
            phone: cleanPhoneNumber,
            identifier: cleanPhoneNumber,
            identifierType: identifierType,
            source: 'manual',
            email: null,
            avatarUrl: null,
            company: null,
            tags: null,
            isActive: true,
            notes: null,
            createdBy: req.user.id
          };

          contact = await storage.getOrCreateContact(contactData);
        }
      }

      let conversation = await storage.getConversationByContactAndChannel(
        contact.id,
        channelConnectionId
      );

      if (conversation) {
        const permissions = await getUserPermissions(req.user);
        if (conversation.companyId !== req.user.companyId || (!req.user.isSuperAdmin && req.user.role !== 'admin' &&
            !permissions[PERMISSIONS.VIEW_ALL_CONVERSATIONS] && conversation.assignedToUserId !== req.user.id)) {
          return res.status(403).json({ message: 'Access denied' });
        }
      }

      if (!conversation) {
        const conversationData: InsertConversation = {
          companyId: req.user.companyId,
          contactId: contact.id,
          channelId: channelConnectionId,
          channelType: channelConnection.channelType,
          status: 'open',
          assignedToUserId: req.user.id,
          lastMessageAt: new Date(),
          originalContactMethod: isUsernameRecipient ? 'username' : 'phone'
        };

        conversation = await storage.createConversation(conversationData);

        conversationMetricsService.initMetric(
          conversation.id,
          req.user.companyId,
          conversation.channelType,
          conversation.createdAt ?? new Date()
        ).catch(e => console.error('[metrics] initMetric failed:', e));
      }

      if (initialMessage && initialMessage.trim()) {
        try {
          let sentMessage = null;

          let sendTarget: string;
          if (channelConnection.channelType === 'whatsapp_official') {
            sendTarget = contact.phone || contact.whatsappBsuid || cleanPhoneNumber;
          } else if (isUsernameRecipient) {
            sendTarget = contact.whatsappLid ? `${contact.whatsappLid}@lid` : `@${parsedRecipient.value}`;
          } else if (parsedRecipient.type === 'lid') {
            sendTarget = `${parsedRecipient.value}@lid`;
          } else {
            sendTarget = cleanPhoneNumber;
          }

          if (channelConnection.channelType === 'whatsapp_official') {
            if (!sendTarget) {
              console.warn('Skipping initial message: contact has no phone or BSUID to send to');
            } else {
              const whatsAppOfficialService = await import('./services/channels/whatsapp-official');
              cancelOfficialDebouncedBatchByConversationId(conversation.id);
              sentMessage = await whatsAppOfficialService.sendMessage(
                channelConnectionId,
                req.user.id,
                req.user.companyId,
                sendTarget,
                initialMessage.trim(),
                false
              );
            }
          } else {
            if (channelConnection.channelType === 'whatsapp_unofficial' || channelConnection.channelType === 'whatsapp') {
              cancelDebouncedBatchByConversationId(conversation.id);
            }
            const { sendWhatsAppMessage } = await import('./services/channels/whatsapp');
            sentMessage = await sendWhatsAppMessage(
              channelConnectionId,
              req.user.id,
              sendTarget,
              initialMessage.trim()
            );
          }

          if (!sentMessage && sendTarget) {
            console.warn('Initial message was not sent successfully');
          }
          if (sentMessage) await recordPipelineContact(conversation.id, req.user.id, sentMessage);
        } catch (messageError) {
          console.error('Error sending initial message:', messageError);
        }
      }

      broadcastToAll({
        type: 'newConversation',
        data: {
          ...conversation,
          contact
        }
      });

      res.status(201).json({
        conversation,
        contact,
        success: true,
        message: 'Conversation initiated successfully'
      });

    } catch (err: any) {
      console.error('Error initiating WhatsApp conversation:', err);
      res.status(500).json({ message: err.message || 'Failed to initiate conversation' });
    }
  });

