  app.get('/api/group-conversations', ensureAuthenticated, ensureActiveSubscription, requireAnyPermission([PERMISSIONS.VIEW_ALL_CONVERSATIONS, PERMISSIONS.VIEW_ASSIGNED_CONVERSATIONS]), async (req, res) => {
    try {
      const user = req.user as any;
      const userPermissions = (req as any).userPermissions;
      if (!await areCompanyGroupChatsEnabled(user.companyId)) {
        return res.status(403).json({ error: 'WhatsApp group chats are disabled', code: 'GROUP_CHATS_DISABLED' });
      }

      const page = parseInt(req.query.page as string) || 1;
      const limit = parseInt(req.query.limit as string) || 50;
      const search = req.query.search as string;

      const companyId = user.companyId;
      const assignedToUserId = userPermissions && !userPermissions[PERMISSIONS.VIEW_ALL_CONVERSATIONS]
        ? user.id
        : undefined;
      const { conversations, total } = await storage.getGroupConversations({
        companyId,
        page,
        limit,
        search,
        assignedToUserId,
      });

      const filteredConversations = conversations;

      const groupIdsNeedingPreview = filteredConversations
        .filter((c: any) => !(c as any).lastMessage)
        .map((c: any) => c.id);
      const groupLatest =
        groupIdsNeedingPreview.length > 0
          ? await storage.getLatestMessageForConversations(groupIdsNeedingPreview)
          : {};
      const groupConversationsWithLastMessage = filteredConversations.map((c: any) => {
        if (c.lastMessage) return c;
        const lm = groupLatest[c.id];
        return lm ? { ...c, lastMessage: lm } : c;
      });

      res.json({
        conversations: groupConversationsWithLastMessage,
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit)
      });
    } catch (error) {
      console.error('Error fetching group conversations:', error);
      res.status(500).json({ error: 'Failed to fetch group conversations' });
    }
  });

