  function isFlowAssignmentConflictMessage(message: string): boolean {
    return (
      message.includes('already handles this pipeline stage') ||
      message.includes('catch-all flow is already active') ||
      message.includes('scoped stage bots are active') ||
      message.includes('Message Trigger stage scope is incomplete or invalid') ||
      message.includes('Meta ad routing key') ||
      message.includes('Message Trigger channel type does not match the selected channel')
    );
  }

