  app.post('/api/flows', ensureAuthenticated, ensureCompanyUser, requirePermission(PERMISSIONS.MANAGE_FLOWS), async (req: any, res) => {
    try {
      const user = req.user;
      if (!user.companyId) {
        return res.status(403).json({ message: 'User is not associated with a company' });
      }

      const company = await storage.getCompany(user.companyId);
      if (!company) {
        return res.status(403).json({ message: 'Company not found' });
      }

      let companyPlan;

      if (company.planId) {
        companyPlan = await storage.getPlan(company.planId);
      }

      if (!companyPlan && company.plan) {
        const allPlans = await storage.getAllPlans();
        companyPlan = allPlans.find(p => p.name.toLowerCase() === company.plan!.toLowerCase());
      }

      if (!companyPlan) {
        return res.status(403).json({ message: 'Company plan not found' });
      }

      const companyFlows = await storage.getFlowsByCompany(company.id);

      if (companyFlows.length >= companyPlan.maxFlows) {
        return res.status(403).json({
          message: `You've reached your plan's flow limit. The ${companyPlan.name} plan allows ${companyPlan.maxFlows} flow${companyPlan.maxFlows === 1 ? '' : 's'}.`,
          planLimit: companyPlan.maxFlows,
          currentCount: companyFlows.length,
          planName: companyPlan.name,
          upgradeRequired: true
        });
      }

      const rawFlowBody = { ...req.body };
      const creatorCommit = rawFlowBody.aiCreatorCommit
        ? aiCreatorCommitSchema.parse(rawFlowBody.aiCreatorCommit) as AiCreatorCommitMetadata
        : null;
      delete rawFlowBody.aiCreatorCommit;
      if (creatorCommit && !verifyAiFlowGenerationProof({
        generationId: creatorCommit.generationId,
        userId: req.user.id,
        companyId: company.id,
        beforeGraphHash: creatorCommit.beforeGraphHash,
        generatedGraphHash: creatorCommit.generatedGraphHash,
      }, creatorCommit.generationProof)) {
        return res.status(400).json({ message: 'Creator generation metadata could not be verified' });
      }
      coerceLegacyFlowGraphFields(rawFlowBody);

      const flowData = validateBody(insertFlowSchema, {
        ...rawFlowBody,
        userId: typeof req.user?.id === 'number' ? req.user.id : (() => { res.status(400).json({ message: 'User ID is required' }); throw new Error('User ID is required'); })(),
        companyId: company.id,
        status: rawFlowBody.status || 'draft'
      });

      if (flowData.status === 'active') {
        const erpModeBlockers = await getErpModeActivationBlockers(flowData);
        if (erpModeBlockers.length) {
          return res.status(400).json({
            message: 'ERP nodes are incompatible with the active company ERP mode',
            erpModeBlockers,
          });
        }
      }

      if (Array.isArray(flowData.nodes)) {
        const stageScopeError = await validateMessageTriggerStageScopeOnFlowNodes(flowData.nodes, {
          getPipeline: (id) => storage.getPipeline(id),
          getPipelineStage: (id) => storage.getPipelineStage(id),
          companyId: company.id,
        });
        if (stageScopeError) {
          return res.status(400).json({ message: stageScopeError });
        }
        flowData.nodes = normalizeFlowNodesAgentControl(flowData.nodes) as typeof flowData.nodes;
      }

      if (creatorCommit) {
        const creatorValidation = await aiFlowCreatorPersistenceService.validateForCommit(
          flowRecordToCreatorGraph(flowData),
          { userId: req.user.id, companyId: company.id },
        );
        if (!creatorValidation.valid) {
          return res.status(400).json({
            message: 'Creator workflow is structurally invalid',
            creatorStructuralIssues: creatorValidation.structuralIssues,
          });
        }
        if (creatorValidation.setupIssues.length && flowData.status === 'active') {
          flowData.status = 'draft';
        }
      }

      const flow = await storage.createFlow(flowData);
      if (flow.companyId != null) {
        let syncResult;
        try {
          syncResult = await syncWebhookTriggersForFlow(flow.id, Array.isArray(flow.nodes) ? flow.nodes : [], flow.companyId);
          if (syncResult.created > 0 || syncResult.updated > 0 || syncResult.deleted > 0) {
            logger.info('Flows', 'Webhook trigger sync after flow create', { flowId: flow.id, ...syncResult });
          }
        } catch (syncErr: any) {
          logger.error('Flows', 'Webhook trigger sync failed after flow create', { flowId: flow.id, error: syncErr?.message });
          await storage.deleteFlow(flow.id);
          return res.status(400).json({ message: 'Webhook trigger sync failed', error: syncErr?.message });
        }
        if (syncResult!.errors.length > 0) {
          await storage.deleteFlow(flow.id);
          return res.status(400).json({ message: 'Webhook trigger sync failed', errors: syncResult!.errors });
        }
        try {
          await knowledgeBaseService.syncKnowledgeBaseConfigsFromFlow(
            flow.companyId,
            flow.id,
            flow.nodes
          );
        } catch (kbSyncErr: any) {
          logger.error('Flows', 'Knowledge base config sync failed after flow create', {
            flowId: flow.id,
            error: kbSyncErr?.message,
          });
        }
      }
      if (creatorCommit && flow.companyId != null) {
        await aiFlowCreatorPersistenceService.recordAppliedRevision({
          flowId: flow.id,
          companyId: flow.companyId,
          userId: req.user.id,
          graph: flowRecordToCreatorGraph(flow),
          metadata: creatorCommit,
          provider: creatorCommit.provider,
          model: creatorCommit.model,
          credentialSource: creatorCommit.credentialSource,
        });
      }
      res.status(201).json(flow);

      broadcastToAll({
        type: 'flowCreated',
        data: flow
      });
    } catch (err: any) {
      res.status(400).json({ message: err.message });
    }
  });

  app.patch('/api/flows/:id', ensureAuthenticated, requirePermission(PERMISSIONS.MANAGE_FLOWS), async (req: any, res) => {
    try {
      const id = parseInt(req.params.id);
      const flow = await storage.getFlow(id);

      if (!flow) {
        return res.status(404).json({ message: 'Flow not found' });
      }

      if (!userCanAccessFlow(flow, req.user as User)) {
        return res.status(403).json({ message: 'You do not have permission to update this flow' });
      }

      const rawPatchBody = { ...req.body };
      let creatorDowngradedToDraft = false;
      let creatorCommit = rawPatchBody.aiCreatorCommit
        ? aiCreatorCommitSchema.parse(rawPatchBody.aiCreatorCommit) as AiCreatorCommitMetadata
        : null;
      delete rawPatchBody.aiCreatorCommit;
      if (creatorCommit) {
        const verified = await aiFlowCreatorPersistenceService.resolveVerifiedSavedGeneration(id, flow.companyId ?? req.user.companyId, req.user.id, creatorCommit);
        if (!verified) {
          return res.status(400).json({ message: 'Creator generation metadata could not be verified for this flow' });
        }
        creatorCommit = verified;
      }
      coerceLegacyFlowGraphFields(rawPatchBody);

      const validatedPatch = validateBody(patchFlowSchema, rawPatchBody);

      const flowMediaAssets = await storage.getFlowMediaAssets(id);
      if (flowMediaAssets.length > 0) {
        const mediaVariableNames = new Set(flowMediaAssets.map((asset) => asset.variableName));
        const candidateNodes = validatedPatch.nodes ?? flow.nodes;
        const sanitizedNodes = removeStaleInferredAiMediaVariables(candidateNodes, mediaVariableNames);
        if (sanitizedNodes !== candidateNodes) {
          (validatedPatch as any).nodes = sanitizedNodes;
        }
        const declaredNames = collectDeclaredFlowVariableNames(
          sanitizedNodes,
          validatedPatch.customVariables ?? flow.customVariables,
        );
        const conflict = flowMediaAssets.find((asset) => declaredNames.has(asset.variableName));
        if (conflict) {
          return res.status(400).json({
            message: `Media variable “${conflict.variableName}” conflicts with another flow variable. Rename one of them before saving.`,
          });
        }
      }

      const updatePayload: Partial<InsertFlow> = { ...validatedPatch };

      if (validatedPatch.status === 'active') {
        const blockers = await getCreatorActivationBlockers(flow, {
          nodes: validatedPatch.nodes,
          edges: validatedPatch.edges,
          customVariables: validatedPatch.customVariables,
        });
        if (blockers.length) {
          return res.status(400).json({
            message: 'Resolve the flow setup or ERP mode requirements before activating this flow',
            creatorSetupBlockers: blockers,
            activationBlockers: blockers,
          });
        }
      }

      const targetFlowStatus = validatedPatch.status ?? flow.status;
      if (targetFlowStatus === 'active' && validatedPatch.status !== 'active') {
        const erpModeBlockers = await getErpModeActivationBlockers(flow, {
          nodes: validatedPatch.nodes,
          edges: validatedPatch.edges,
          customVariables: validatedPatch.customVariables,
        });
        if (erpModeBlockers.length) {
          return res.status(400).json({
            message: 'ERP nodes are incompatible with the active company ERP mode',
            erpModeBlockers,
          });
        }
      }

      if (validatedPatch.nodes != null && Array.isArray(validatedPatch.nodes)) {
        const stageScopeError = await validateMessageTriggerStageScopeOnFlowNodes(validatedPatch.nodes, {
          getPipeline: (pipelineId) => storage.getPipeline(pipelineId),
          getPipelineStage: (stageId) => storage.getPipelineStage(stageId),
          companyId: flow.companyId,
        });
        if (stageScopeError) {
          return res.status(400).json({ message: stageScopeError });
        }

        const assignmentConflict = await validateActiveFlowNodesAgainstChannelAssignments(id, validatedPatch.nodes, {
          getFlowAssignments: (channelId, flowId) => storage.getFlowAssignments(channelId, flowId),
          getFlow: (flowId) => storage.getFlow(flowId),
        });
        if (assignmentConflict) {
          return res.status(400).json({ message: assignmentConflict });
        }

        const metaAdRoutingConflict = await validateActiveFlowNodesAgainstMetaAdRoutingAssignments(
          id,
          validatedPatch.nodes,
          activeFlowMetaAdRoutingValidationDeps
        );
        if (metaAdRoutingConflict) {
          return res.status(400).json({ message: metaAdRoutingConflict });
        }

        updatePayload.nodes = normalizeFlowNodesAgentControl(validatedPatch.nodes) as InsertFlow['nodes'];
      }

      if (creatorCommit) {
        const creatorGraph = flowRecordToCreatorGraph(flow, {
          nodes: updatePayload.nodes,
          edges: updatePayload.edges,
          customVariables: updatePayload.customVariables,
        });
        const creatorValidation = await aiFlowCreatorPersistenceService.validateForCommit(
          creatorGraph,
          { userId: flow.userId, companyId: flow.companyId },
        );
        if (!creatorValidation.valid) {
          return res.status(400).json({
            message: 'Creator workflow is structurally invalid',
            creatorStructuralIssues: creatorValidation.structuralIssues,
          });
        }
        const effectiveStatus = updatePayload.status ?? flow.status;
        if (creatorValidation.setupIssues.length && effectiveStatus === 'active') {
          updatePayload.status = 'draft';
          creatorDowngradedToDraft = true;
        }
      }

      const updatedFlow = await storage.updateFlow(id, updatePayload);
      if (updatedFlow.companyId != null) {
        let syncResult;
        try {
          syncResult = await syncWebhookTriggersForFlow(updatedFlow.id, Array.isArray(updatedFlow.nodes) ? updatedFlow.nodes : [], updatedFlow.companyId);
          if (syncResult.created > 0 || syncResult.updated > 0 || syncResult.deleted > 0) {
            logger.info('Flows', 'Webhook trigger sync after flow update', { flowId: updatedFlow.id, ...syncResult });
          }
        } catch (syncErr: any) {
          logger.error('Flows', 'Webhook trigger sync failed after flow update', { flowId: updatedFlow.id, error: syncErr?.message });
          return res.status(400).json({ message: 'Webhook trigger sync failed', error: syncErr?.message });
        }
        if (syncResult!.errors.length > 0) {
          return res.status(400).json({ message: 'Webhook trigger sync failed', errors: syncResult!.errors });
        }
        try {
          await knowledgeBaseService.syncKnowledgeBaseConfigsFromFlow(
            updatedFlow.companyId,
            updatedFlow.id,
            updatedFlow.nodes
          );
        } catch (kbSyncErr: any) {
          logger.error('Flows', 'Knowledge base config sync failed after flow update', {
            flowId: updatedFlow.id,
            error: kbSyncErr?.message,
          });
        }
      }
      if (creatorCommit && updatedFlow.companyId != null) {
        await aiFlowCreatorPersistenceService.recordAppliedRevision({
          flowId: updatedFlow.id,
          companyId: updatedFlow.companyId,
          userId: req.user.id,
          graph: flowRecordToCreatorGraph(updatedFlow),
          metadata: creatorCommit,
          provider: creatorCommit.provider,
          model: creatorCommit.model,
          credentialSource: creatorCommit.credentialSource,
        });
      }
      if (creatorDowngradedToDraft) {
        const assignments = await storage.getFlowAssignments(undefined, updatedFlow.id);
        for (const assignment of assignments.filter((current) => current.isActive)) {
          await storage.updateFlowAssignmentStatus(assignment.id, false);
          broadcastToAll({ type: 'flowAssignmentUpdated', data: { ...assignment, isActive: false } });
        }
      }
      res.json(updatedFlow);

      broadcastToAll({
        type: 'flowUpdated',
        data: updatedFlow
      });
    } catch (err: any) {
      res.status(400).json({ message: err.message });
    }
  });

