  app.post('/api/flows/:id/duplicate', ensureAuthenticated, requirePermission(PERMISSIONS.MANAGE_FLOWS), async (req: any, res) => {
    try {
      const id = parseInt(req.params.id);
      const originalFlow = await storage.getFlow(id);

      if (!originalFlow) {
        return res.status(404).json({ message: 'Flow not found' });
      }

      if (!userCanAccessFlow(originalFlow, req.user as User)) {
        return res.status(403).json({ message: 'You do not have permission to duplicate this flow' });
      }

      const user = req.user;
      if (!user.companyId) {
        return res.status(403).json({ message: 'User is not associated with a company' });
      }

      const company = await storage.getCompany(user.companyId);
      if (!company) {
        return res.status(403).json({ message: 'Company not found' });
      }

      let companyPlan;

      if (company.planId) {
        companyPlan = await storage.getPlan(company.planId);
      }

      if (!companyPlan && company.plan) {
        const allPlans = await storage.getAllPlans();
        companyPlan = allPlans.find(p => p.name.toLowerCase() === company.plan!.toLowerCase());
      }

      if (!companyPlan) {
        return res.status(403).json({ message: 'Company plan not found' });
      }

      const companyFlows = await storage.getFlowsByCompany(company.id);

      if (companyFlows.length >= companyPlan.maxFlows) {
        return res.status(403).json({
          message: `You've reached your plan's flow limit. The ${companyPlan.name} plan allows ${companyPlan.maxFlows} flow${companyPlan.maxFlows === 1 ? '' : 's'}.`,
          planLimit: companyPlan.maxFlows,
          currentCount: companyFlows.length,
          planName: companyPlan.name,
          upgradeRequired: true
        });
      }

      const nodes = Array.isArray(originalFlow.nodes) ? [...originalFlow.nodes] : [];
      for (const node of nodes) {
        if (
          (node?.type === 'webhookTrigger' || node?.type === 'mastershopWebhookTrigger') &&
          node.data &&
          typeof node.data === 'object'
        ) {
          (node as any).data = {
            ...(node.data as object),
            webhookToken: generateWebhookVerifyToken(48),
            useCustomPath: false,
            customPath: null
          };
        }
      }

      const stageScopeError = await validateMessageTriggerStageScopeOnFlowNodes(nodes, {
        getPipeline: (pipelineId) => storage.getPipeline(pipelineId),
        getPipelineStage: (stageId) => storage.getPipelineStage(stageId),
        companyId: originalFlow.companyId,
      });
      if (stageScopeError) {
        return res.status(400).json({ message: stageScopeError });
      }

      const normalizedNodes = normalizeFlowNodesAgentControl(nodes);

      const duplicateFlowData = validateBody(insertFlowSchema, {
        userId: req.user.id,
        companyId: originalFlow.companyId,
        name: `${originalFlow.name} (Copy)`,
        description: originalFlow.description,
        status: 'draft',
        nodes: normalizedNodes,
        edges: originalFlow.edges,
        customVariables: Array.isArray(originalFlow.customVariables)
          ? originalFlow.customVariables
          : [],
        version: 1
      });

      const duplicatedFlow = await storage.createFlow(duplicateFlowData);
      const originalMediaAssets = await storage.getFlowMediaAssets(originalFlow.id);
      const copiedMediaPaths: string[] = [];
      try {
        for (const asset of originalMediaAssets) {
          const extension = path.extname(asset.originalName).toLowerCase();
          const copiedFilename = `${Date.now()}-${crypto.randomBytes(16).toString('hex')}${extension}`;
          const copiedPath = path.join(FLOW_MEDIA_DIR, copiedFilename);
          await fsExtra.copy(path.join(FLOW_MEDIA_DIR, path.basename(asset.fileUrl)), copiedPath);
          copiedMediaPaths.push(copiedPath);
          const copiedUrl = `/media/flow-media/${copiedFilename}`;
          await storage.createFlowMediaAsset({
            flowId: duplicatedFlow.id,
            companyId: duplicatedFlow.companyId!,
            variableName: asset.variableName,
            originalName: asset.originalName,
            fileUrl: copiedUrl,
            mimeType: asset.mimeType,
            mediaKind: asset.mediaKind,
            fileSize: asset.fileSize,
            uploadedBy: req.user.id,
          });
          await recordMediaFileOwnership({
            companyId: duplicatedFlow.companyId!,
            publicUrl: copiedUrl,
            bucket: 'uploads/flow-media',
            fileSize: asset.fileSize,
          });
          void dataUsageTracker.trackFileUpload(duplicatedFlow.companyId!, asset.fileSize);
        }
      } catch (mediaCopyError) {
        logger.error('Flows', 'Media gallery copy failed during flow duplication', { flowId: duplicatedFlow.id, error: mediaCopyError });
        const copiedAssets = await storage.getFlowMediaAssets(duplicatedFlow.id);
        await storage.deleteFlow(duplicatedFlow.id);
        await cleanupFlowMediaFiles(copiedAssets, copiedMediaPaths);
        return res.status(500).json({ message: 'Failed to copy the flow media gallery' });
      }
      if (duplicatedFlow.companyId != null) {
        let syncResult;
        try {
          syncResult = await syncWebhookTriggersForFlow(duplicatedFlow.id, Array.isArray(duplicatedFlow.nodes) ? duplicatedFlow.nodes : [], duplicatedFlow.companyId);
          if (syncResult.created > 0 || syncResult.updated > 0 || syncResult.deleted > 0) {
            logger.info('Flows', 'Webhook trigger sync after flow duplicate', { flowId: duplicatedFlow.id, ...syncResult });
          }
        } catch (syncErr: any) {
          logger.error('Flows', 'Webhook trigger sync failed after flow duplicate', { flowId: duplicatedFlow.id, error: syncErr?.message });
          const copiedAssets = await storage.getFlowMediaAssets(duplicatedFlow.id);
          await storage.deleteFlow(duplicatedFlow.id);
          await cleanupFlowMediaFiles(copiedAssets, copiedMediaPaths);
          return res.status(400).json({ message: 'Webhook trigger sync failed', error: syncErr?.message });
        }
        if (syncResult!.errors.length > 0) {
          const copiedAssets = await storage.getFlowMediaAssets(duplicatedFlow.id);
          await storage.deleteFlow(duplicatedFlow.id);
          await cleanupFlowMediaFiles(copiedAssets, copiedMediaPaths);
          return res.status(400).json({ message: 'Webhook trigger sync failed', errors: syncResult!.errors });
        }
        try {
          await knowledgeBaseService.syncKnowledgeBaseConfigsFromFlow(
            duplicatedFlow.companyId,
            duplicatedFlow.id,
            duplicatedFlow.nodes
          );
        } catch (kbSyncErr: any) {
          logger.error('Flows', 'Knowledge base config sync failed after flow duplicate', {
            flowId: duplicatedFlow.id,
            error: kbSyncErr?.message,
          });
        }
      }
      res.status(201).json(duplicatedFlow);

      broadcastToAll({
        type: 'flowCreated',
        data: duplicatedFlow
      });
    } catch (err: any) {
      res.status(400).json({ message: err.message });
    }
  });


  app.get('/api/flows/:id/variables', ensureAuthenticated, requirePermission(PERMISSIONS.VIEW_FLOWS), async (req: any, res) => {
    try {
      const flowId = parseInt(req.params.id);
      const userId = req.user?.id;

      if (!flowId || isNaN(flowId)) {
        return res.status(400).json({
          success: false,
          error: 'Invalid flow ID'
        });
      }

      const flow = await storage.getFlow(flowId);
      if (!flow) {
        return res.status(404).json({
          success: false,
          error: 'Flow not found'
        });
      }

      if (!userCanAccessFlow(flow, req.user as User)) {
        return res.status(403).json({
          success: false,
          error: 'Access denied'
        });
      }

      const nodes = flow.nodes as any[] || [];
      const dataCaptureNodes = nodes.filter(node =>
        node.type === 'data_capture' &&
        node.data?.captureRules?.length > 0
      );

      const codeExecutionNodes = nodes.filter(node =>
        node.type === 'code_execution' &&
        node.data?.code
      );

      const databaseQueryNodes = nodes.filter(node =>
        node.type === 'database_query' || node.type === 'databaseQueryNode'
      );

      const capturedVariables: Array<{
        variableKey: string;
        label: string;
        description: string;
        variableType: string;
        nodeId: string;
        nodeName: string;
        required: boolean;
      }> = [];

      dataCaptureNodes.forEach(node => {
        const captureRules = node.data.captureRules || [];
        const nodeName = node.data.label || `Data Capture ${node.id}`;

        captureRules.forEach((rule: any) => {
          if (rule.variableName) {
            capturedVariables.push({
              variableKey: rule.variableName,
              label: rule.variableName.replace(/_/g, ' ').replace(/\b\w/g, (l: string) => l.toUpperCase()),
              description: rule.description || `Captured from ${nodeName}`,
              variableType: rule.dataType || 'string',
              nodeId: node.id,
              nodeName,
              required: rule.required || false
            });
          }
        });
      });

      codeExecutionNodes.forEach(node => {
        const nodeName = node.data.label || `Code Execution ${node.id}`;

        capturedVariables.push({
          variableKey: 'code_execution_output',
          label: 'Code Execution Output',
          description: `Output variables from ${nodeName}`,
          variableType: 'object',
          nodeId: node.id,
          nodeName,
          required: false
        });
        extractCodeExecutionVariableNames(node.data.code).forEach((variableName) => {
          capturedVariables.push({
            variableKey: variableName,
            label: variableName.replace(/[_.-]+/g, ' ').replace(/\b\w/g, (letter: string) => letter.toUpperCase()),
            description: `Created by ${nodeName}`,
            variableType: 'runtime',
            nodeId: node.id,
            nodeName,
            required: false
          });
          capturedVariables.push({
            variableKey: `code_execution_output.${variableName}`,
            label: `Code Output · ${variableName}`,
            description: `Nested output from ${nodeName}`,
            variableType: 'runtime',
            nodeId: node.id,
            nodeName,
            required: false
          });
        });
      });

      databaseQueryNodes.forEach(node => {
        const nodeName = node.data?.label || `Database ${node.id}`;

        capturedVariables.push({
          variableKey: 'database_query_output',
          label: 'Database Query Output',
          description: `Query result envelope from ${nodeName} (rows, rowCount, fields, etc.)`,
          variableType: 'object',
          nodeId: node.id,
          nodeName,
          required: false
        });
      });

      const uniqueVariables = capturedVariables.reduce((acc, variable) => {
        const existing = acc.find(v => v.variableKey === variable.variableKey);
        if (!existing) {
          acc.push(variable);
        }
        return acc;
      }, [] as typeof capturedVariables);

      const mediaAssets = await storage.getFlowMediaAssets(flowId);
      for (const asset of mediaAssets) {
        if (uniqueVariables.some((variable) => variable.variableKey === asset.variableName)) continue;
        uniqueVariables.push({
          variableKey: asset.variableName,
          label: asset.variableName.replace(/_+/g, ' ').replace(/\b\w/g, (letter: string) => letter.toUpperCase()),
          description: `Flow media: ${asset.originalName}`,
          variableType: 'media',
          nodeId: '',
          nodeName: 'Media Gallery',
          required: false,
        });
      }

      const rawCustomVars = (flow as any).customVariables ?? [];
      const customVariables = rawCustomVars.map((v: any) => ({
        variableKey: v.name,
        label: v.label,
        description: v.description ?? '',
        variableType: v.dataType,
        nodeId: null,
        nodeName: null
      }));

      let runtimeVariables: typeof uniqueVariables = [];
      try {
        const ctxSnap = await storage.getLatestFlowExecutionContextData(flowId);
        if (ctxSnap) {
          const keys = collectContextVariableKeysForPicker(ctxSnap, 200);
          const taken = new Set(uniqueVariables.map((v) => v.variableKey));
          for (const key of keys) {
            if (taken.has(key)) continue;
            taken.add(key);
            runtimeVariables.push({
              variableKey: key,
              label: key,
              description: 'Seen in a recent flow execution',
              variableType: 'runtime',
              nodeId: '',
              nodeName: 'Recent run',
              required: false
            });
          }
        }
      } catch (runtimeErr) {
        logger.warn('FlowVariables', 'Could not load runtime variable sample', runtimeErr);
      }

      logger.info('FlowVariables', `Retrieved ${uniqueVariables.length} captured variables for flow ${flowId}`, {
        flowId,
        userId,
        variableCount: uniqueVariables.length,
        dataCaptureNodeCount: dataCaptureNodes.length,
        codeExecutionNodeCount: codeExecutionNodes.length,
        databaseQueryNodeCount: databaseQueryNodes.length
      });

      res.json({
        success: true,
        variables: uniqueVariables,
        runtimeVariables,
        customVariables,
        meta: {
          flowId,
          flowName: flow.name,
          dataCaptureNodeCount: dataCaptureNodes.length,
          codeExecutionNodeCount: codeExecutionNodes.length,
          databaseQueryNodeCount: databaseQueryNodes.length,
          totalVariableCount: uniqueVariables.length,
          runtimeVariableCount: runtimeVariables.length,
          customVariableCount: customVariables.length
        }
      });

    } catch (error) {
      logger.error('FlowVariables', 'Error getting flow variables', error);
      res.status(500).json({
        success: false,
        error: 'Internal server error'
      });
    }
  });


