  app.get('/api/sessions/:sessionId/variables', ensureAuthenticated, requirePermission(PERMISSIONS.VIEW_FLOWS), async (req: any, res) => {
    try {
      const sessionId = req.params.sessionId;
      const scope = req.query.scope as string;
      const limit = parseInt(req.query.limit as string) || 50;
      const offset = parseInt(req.query.offset as string) || 0;

      if (!sessionId) {
        return res.status(400).json({
          success: false,
          error: 'Session ID is required'
        });
      }

      const flowSession = await storage.getFlowSession(sessionId);
      if (!flowSession) {
        return res.status(404).json({
          success: false,
          error: 'Session not found'
        });
      }

      const sessionFlow = await storage.getFlow((flowSession as { flowId: number }).flowId);
      if (!sessionFlow || !userCanAccessFlow(sessionFlow, req.user as User)) {
        return res.status(403).json({
          success: false,
          error: 'Access denied'
        });
      }

      if (limit < 1 || limit > 100) {
        return res.status(400).json({
          success: false,
          error: 'Limit must be between 1 and 100'
        });
      }

      if (offset < 0) {
        return res.status(400).json({
          success: false,
          error: 'Offset must be non-negative'
        });
      }

      const validScopes = ['global', 'flow', 'node', 'user', 'session'] as const;
      const validatedScope = scope && validScopes.includes(scope as any) ? scope as typeof validScopes[number] : 'session';

      const { variables, totalCount } = await storage.getFlowVariablesPaginated(sessionId, {
        scope: validatedScope,
        limit,
        offset
      });

      logger.info('FlowVariables', `Retrieved ${variables.length} variable values for session ${sessionId} (${offset}-${offset + variables.length} of ${totalCount})`, {
        sessionId,
        scope,
        limit,
        offset,
        variableCount: variables.length,
        totalCount
      });

      res.json({
        success: true,
        variables: variables.reduce((acc, variable) => {
          acc[variable.variableKey] = variable.variableValue;
          return acc;
        }, {} as Record<string, any>),
        details: variables,
        meta: {
          sessionId,
          scope: validatedScope,
          count: variables.length,
          totalCount,
          limit,
          offset,
          hasMore: offset + variables.length < totalCount
        }
      });

    } catch (error) {
      logger.error('FlowVariables', 'Error getting session variables', error);
      res.status(500).json({
        success: false,
        error: 'Internal server error'
      });
    }
  });


