  app.get('/api/flow-assignments', ensureAuthenticated, requirePermission(PERMISSIONS.VIEW_FLOWS), async (req: any, res) => {
    try {
      const { channelId, flowId } = req.query;
      const hasChannelParam = channelId !== undefined && String(channelId).length > 0;
      const hasFlowParam = flowId !== undefined && String(flowId).length > 0;

      let channelIdNum: number | undefined;
      let flowIdNum: number | undefined;

      if (hasChannelParam) {
        channelIdNum = parseInt(String(channelId), 10);
        if (Number.isNaN(channelIdNum)) {
          return res.status(400).json({ message: 'Invalid channelId' });
        }
      }
      if (hasFlowParam) {
        flowIdNum = parseInt(String(flowId), 10);
        if (Number.isNaN(flowIdNum)) {
          return res.status(400).json({ message: 'Invalid flowId' });
        }
      }

      if (channelIdNum === undefined && flowIdNum === undefined) {
        return res.status(400).json({ message: 'Specify channelId and/or flowId to list flow assignments' });
      }

      if (flowIdNum != null) {
        const flow = await storage.getFlow(flowIdNum);
        if (!flow || !userCanAccessFlow(flow, req.user as User)) {
          return res.status(403).json({ message: 'You do not have permission to view assignments for this flow' });
        }
      }

      if (channelIdNum != null) {
        const channelConnection = await storage.getChannelConnection(channelIdNum);
        if (!channelConnection) {
          return res.status(404).json({ message: 'Channel connection not found' });
        }
        const isOwner = channelConnection.userId === req.user.id;
        const isSameCompany =
          channelConnection.companyId != null && channelConnection.companyId === req.user.companyId;
        if (!isOwner && !isSameCompany) {
          return res.status(403).json({ message: 'You do not have permission to view assignments for this channel' });
        }
      }

      const assignments = await storage.getFlowAssignments(channelIdNum, flowIdNum);
      const user = req.user as User;
      const uniqueFlowIds = [...new Set(assignments.map((a) => a.flowId))];
      const flowAccessById = new Map<number, boolean>();
      await Promise.all(
        uniqueFlowIds.map(async (fid) => {
          const flow = await storage.getFlow(fid);
          flowAccessById.set(fid, !!flow && userCanAccessFlow(flow, user));
        })
      );
      const filteredAssignments = assignments.filter((a) => flowAccessById.get(a.flowId));
      const flowNodesById = new Map<number, unknown>();
      await Promise.all(
        uniqueFlowIds.map(async (fid) => {
          const flow = await storage.getFlow(fid);
          if (flow) {
            flowNodesById.set(fid, flow.nodes);
          }
        })
      );
      const enrichedAssignments = filteredAssignments.map((assignment) => {
        const nodes = flowNodesById.get(assignment.flowId);
        const parsedNodes = Array.isArray(nodes)
          ? nodes
          : typeof nodes === 'string'
            ? (() => {
                try {
                  return JSON.parse(nodes);
                } catch {
                  return [];
                }
              })()
            : [];
        const triggerStageScope = deriveFlowTriggerStageScopeFromNodes(parsedNodes);
        return {
          ...assignment,
          triggerStageScope: triggerStageScope.kind === 'stage-scoped'
            ? { pipelineId: triggerStageScope.pipelineId, stageId: triggerStageScope.stageId }
            : null,
        };
      });
      res.json(enrichedAssignments);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post('/api/flow-assignments', ensureAuthenticated, requirePermission(PERMISSIONS.MANAGE_FLOWS), async (req: any, res) => {
    try {
      const assignmentData = validateBody(insertFlowAssignmentSchema, {
        ...req.body,
        isActive: req.body.isActive || false
      });

      const flow = await storage.getFlow(assignmentData.flowId);
      if (!flow || !userCanAccessFlow(flow, req.user as User)) {
        return res.status(403).json({ message: 'You do not have permission to assign this flow' });
      }
      if (assignmentData.isActive) {
        const creatorBlockers = await getCreatorActivationBlockers(flow);
        if (creatorBlockers.length) {
          return res.status(400).json({
            message: 'Resolve the flow setup or ERP mode requirements before activating this assignment',
            creatorSetupBlockers: creatorBlockers,
            activationBlockers: creatorBlockers,
          });
        }
      }

      const channelConnection = await storage.getChannelConnection(assignmentData.channelId);
      if (!channelConnection) {
        return res.status(404).json({ message: 'Channel connection not found' });
      }

      const isOwner = channelConnection.userId === req.user.id;
      const isSameCompany = channelConnection.companyId != null && channelConnection.companyId === req.user.companyId;
      if (!isOwner && !isSameCompany) {
        return res.status(403).json({ message: 'You do not have permission to assign flows to this channel' });
      }

      const assignment = await storage.createFlowAssignment(assignmentData);
      res.status(201).json(assignment);

      broadcastToAll({
        type: 'flowAssignmentCreated',
        data: assignment
      });
    } catch (err: any) {
      console.error('❌ Error creating flow assignment:', err);


      let errorMessage = err.message;
      if (err.message.includes('already assigned to')) {
        errorMessage = `Cannot assign flow: ${err.message}`;
      } else if (isFlowAssignmentConflictMessage(err.message)) {
        errorMessage = err.message;
      }

      res.status(400).json({ message: errorMessage });
    }
  });

  app.patch('/api/flow-assignments/:id/status', ensureAuthenticated, requirePermission(PERMISSIONS.MANAGE_FLOWS), async (req: any, res) => {
    try {
      const id = parseInt(req.params.id);
      const { isActive } = req.body;

      if (isActive === undefined) {
        return res.status(400).json({ message: 'isActive field is required' });
      }

      const assignment = await storage.getFlowAssignment(id);
      if (!assignment) {
        return res.status(404).json({ message: 'Flow assignment not found' });
      }

      const assignedFlow = await storage.getFlow(assignment.flowId);
      if (!assignedFlow || !userCanAccessFlow(assignedFlow, req.user as User)) {
        return res.status(403).json({ message: 'You do not have permission to update this assignment' });
      }
      if (isActive === true) {
        const creatorBlockers = await getCreatorActivationBlockers(assignedFlow);
        if (creatorBlockers.length) {
          return res.status(400).json({
            message: 'Resolve the flow setup or ERP mode requirements before activating this assignment',
            creatorSetupBlockers: creatorBlockers,
            activationBlockers: creatorBlockers,
          });
        }
      }

      const channelConnection = await storage.getChannelConnection(assignment.channelId);
      if (!channelConnection) {
        return res.status(403).json({ message: 'You do not have permission to update this assignment' });
      }
      const isOwner = channelConnection.userId === req.user.id;
      const isSameCompany = channelConnection.companyId != null && channelConnection.companyId === req.user.companyId;
      if (!isOwner && !isSameCompany) {
        return res.status(403).json({ message: 'You do not have permission to update this assignment' });
      }



      const updatedAssignment = await storage.updateFlowAssignmentStatus(id, isActive);



      res.json(updatedAssignment);


      broadcastToAll({
        type: 'flowAssignmentUpdated',
        data: updatedAssignment
      });


      broadcastToAll({
        type: 'flowAssignmentStatusChanged',
        data: {
          assignmentId: id,
          flowId: updatedAssignment.flowId,
          channelId: updatedAssignment.channelId,
          isActive: updatedAssignment.isActive,
          timestamp: new Date().toISOString()
        }
      });


      if ((global as any).flowAssignmentEventEmitter) {
        (global as any).flowAssignmentEventEmitter.emit('flowAssignmentStatusChanged', {
          assignmentId: id,
          flowId: updatedAssignment.flowId,
          channelId: updatedAssignment.channelId,
          isActive: updatedAssignment.isActive,
          timestamp: new Date().toISOString()
        });
      }

    } catch (err: any) {
      console.error('❌ Error updating flow assignment status:', err);


      let errorMessage = err.message;
      if (err.message.includes('already active on')) {
        errorMessage = `Cannot activate: ${err.message}`;
      } else if (err.message.includes('already assigned to')) {
        errorMessage = `Cannot assign: ${err.message}`;
      } else if (isFlowAssignmentConflictMessage(err.message)) {
        errorMessage = err.message;
      }

      res.status(400).json({ message: errorMessage });
    }
  });

