  app.get('/api/google/calendar/calendars', ensureAuthenticated, async (req: any, res) => {
    try {
      const assignmentStrategy = req.query.assignmentStrategy as string | undefined;
      const targetAgentUserId = req.query.targetAgentUserId
        ? parseInt(req.query.targetAgentUserId as string, 10)
        : null;
      let targetUserId = req.user.id;

      if (assignmentStrategy === 'agent_pick' && targetAgentUserId != null) {
        const permissions = await getUserPermissions(req.user);
        const hasTeamCalendarAccess = req.user.isSuperAdmin ||
          req.user.role === 'admin' ||
          permissions[PERMISSIONS.VIEW_TEAM] === true ||
          permissions[PERMISSIONS.MANAGE_TEAM] === true;
        if (!hasTeamCalendarAccess) {
          return res.status(403).json({ success: false, calendars: [], error: 'Forbidden' });
        }

        const companyId = req.user.companyId;
        if (!companyId) {
          return res.status(400).json({ success: false, calendars: [], error: 'Company ID is required' });
        }

        const teamCalendarMembers = await storage.getTeamMembersWithCalendarConnected(companyId);
        const hasAccessToAgent = teamCalendarMembers.some((agent: any) => agent.userId === targetAgentUserId);
        if (!hasAccessToAgent) {
          return res.status(403).json({ success: false, calendars: [], error: 'Forbidden' });
        }

        targetUserId = targetAgentUserId;
      }

      const result = await googleCalendarService.listUserCalendars(targetUserId, req.user.companyId);
      return res.json(result);
    } catch (error: any) {
      console.error('Error listing Google Calendars:', error);
      const message = error?.message || '';
      if (message.includes('token') || message.includes('not_connected') || message.includes('Calendar client not available')) {
        return res.json({ success: false, calendars: [], error: 'not_connected' });
      }
      return res.status(500).json({ success: false, calendars: [], error: 'Error listing Google Calendars' });
    }
  });

