  app.get('/api/team/members', ensureAuthenticated, ensureCompanyContext, async (req: any, res) => {
    try {
      const user = req.user;
      const scope = await resolveTeamMembersListScope(user);

      if (!scope) {
        return res.status(403).json({ message: 'Forbidden: Insufficient permissions' });
      }

      let teamMembers;
      if (scope === 'company-all') {
        teamMembers = await storage.getTeamMembersByCompany(user.companyId);
      } else {
        teamMembers = await storage.getActiveTeamMembersByCompany(user.companyId);
      }

      const customRoles = await storage.getCompanyCustomRoles(user.companyId);
      const customRoleNameById = new Map(customRoles.map((role) => [role.id, role.name]));

      const safeTeamMembers = teamMembers.map(member => {
        const { password, ...safeUser } = member;
        return {
          ...safeUser,
          customRoleName: member.customRoleId
            ? (customRoleNameById.get(member.customRoleId) ?? null)
            : null,
        };
      });

      res.json(safeTeamMembers);
    } catch (error) {
      console.error('Error getting team members:', error);
      res.status(500).json({ message: 'Failed to retrieve team members' });
    }
  });

  app.post('/api/team/members', ensureAuthenticated, ensureAdmin, ensureCompanyContext, async (req: any, res) => {
    try {
      const teamMemberSchema = z.object({
        fullName: z.string().min(1, 'Full name is required'),
        username: z.string().min(3, 'Username must be at least 3 characters'),
        email: z.string().email('Valid email is required'),
        password: z.string().min(6, 'Password must be at least 6 characters'),
        role: z.string().refine(role => role === 'admin' || role === 'agent', {
          message: "Role must be either 'admin' or 'agent'"
        }),
        customRoleId: z.number().int().positive().nullable().optional(),
        whatsappNumber: z.string().transform((value) => value.trim()).refine(
          (value) => value.length > 0,
          { message: 'WhatsApp number is required' }
        )
      }).merge(teamMemberPermissionFieldsSchema);

      const validationResult = teamMemberSchema.safeParse(req.body);
      if (!validationResult.success) {
        return res.status(400).json({
          message: 'Invalid team member data',
          errors: validationResult.error.errors
        });
      }

      const { fullName, username, email, password, whatsappNumber } = validationResult.data;
      let role = validationResult.data.role as 'admin' | 'agent';
      let customRoleId: number | null = validationResult.data.customRoleId ?? null;

      if (customRoleId != null && role === 'admin') {
        return res.status(400).json({
          message: 'Custom roles cannot be combined with the Administrator role',
        });
      }

      if (customRoleId != null) {
        const customRole = await storage.getCompanyCustomRole(customRoleId, req.user.companyId!);
        if (!customRole) {
          return res.status(400).json({ message: 'Custom role not found' });
        }
        role = 'agent';
      } else {
        customRoleId = null;
      }

      const existingUser = await storage.getUserByUsernameCaseInsensitive(username);
      if (existingUser) {
        return res.status(400).json({ message: 'A user with this username already exists' });
      }

      const existingEmailUser = await storage.getUserByEmail(email);
      if (existingEmailUser) {
        return res.status(400).json({ message: 'A user with this email already exists' });
      }

      const hashedPassword = await hashPassword(password);

      const permissionUpdates = buildTeamMemberPermissionUpdates(validationResult.data);
      const normalizedCustomPermissions = normalizeAdminCustomPermissionsSnapshot(
        role,
        permissionUpdates.customPermissions
      );

      const newUser = await storage.createUser({
        username,
        email,
        fullName,
        password: hashedPassword,
        role,
        customRoleId,
        companyId: req.user.companyId!,
        whatsappNumber,
        permissionMode: permissionUpdates.permissionMode ?? USER_PERMISSION_MODES.INHERIT,
        permissions: permissionUpdates.permissions ?? {},
        customPermissions: normalizedCustomPermissions ?? {},
      });

      const { password: _, ...safeUser } = newUser;

      res.status(201).json(safeUser);
    } catch (error) {
      console.error('Error creating team member:', error);
      res.status(500).json({ message: 'Failed to create team member' });
    }
  });

  app.patch('/api/team/members/:id', ensureAuthenticated, ensureAdmin, ensureCompanyContext, async (req: any, res) => {
    try {
      const memberId = parseInt(req.params.id);
      const updateSchema = z.object({
        fullName: z.string().min(1, 'Full name is required').optional(),
        email: z.string().email('Valid email is required').optional(),
        password: z.string().min(6, 'Password must be at least 6 characters').optional(),
        role: z.string().refine(role => role === 'admin' || role === 'agent', {
          message: "Role must be either 'admin' or 'agent'"
        }).optional(),
        customRoleId: z.number().int().positive().nullable().optional(),
        whatsappNumber: z
          .string()
          .transform((value) => value.trim())
          .refine((value) => value.length > 0, { message: 'WhatsApp number is required' })
          .optional()
      }).merge(teamMemberPermissionFieldsSchema);

      const validationResult = updateSchema.safeParse(req.body);
      if (!validationResult.success) {
        return res.status(400).json({
          message: 'Invalid update data',
          errors: validationResult.error.errors
        });
      }

      const updateData = validationResult.data;

      if (isSelfAuthMutationAttempt(req.user.id, memberId, req.body)) {
        return res.status(400).json({ message: 'You cannot change your own role or permissions' });
      }

      const existingMember = await storage.getUser(memberId);
      if (!existingMember) {
        return res.status(404).json({ message: 'Team member not found' });
      }

      if (!req.user.isSuperAdmin && existingMember.companyId !== req.user.companyId) {
        return res.status(403).json({ message: 'Access denied' });
      }

      let nextRole = (updateData.role ?? existingMember.role) as 'admin' | 'agent' | 'super_admin';
      let nextCustomRoleId =
        updateData.customRoleId !== undefined
          ? updateData.customRoleId
          : (existingMember.customRoleId ?? null);

      if (updateData.role !== undefined || updateData.customRoleId !== undefined) {
        if (updateData.customRoleId != null) {
          if (updateData.role === 'admin') {
            return res.status(400).json({
              message: 'Custom roles cannot be combined with the Administrator role',
            });
          }
          const customRole = await storage.getCompanyCustomRole(
            updateData.customRoleId,
            existingMember.companyId ?? req.user.companyId!
          );
          if (!customRole) {
            return res.status(400).json({ message: 'Custom role not found' });
          }
          nextRole = 'agent';
          nextCustomRoleId = updateData.customRoleId;
        } else if (updateData.customRoleId === null || updateData.role !== undefined) {
          // Built-in role assignment clears custom role
          nextCustomRoleId = null;
          if (updateData.role) {
            nextRole = updateData.role as 'admin' | 'agent';
          }
        }
      }

      if (
        nextRole !== 'admin' &&
        existingMember.companyId != null &&
        wouldRemoveLastCompanyAdmin(
          await storage.getUsersByCompany(existingMember.companyId),
          memberId,
          nextRole
        )
      ) {
        return res.status(400).json({ message: 'Cannot remove the last company administrator' });
      }

      const userUpdateData: any = {
        fullName: updateData.fullName,
        email: updateData.email,
        whatsappNumber: updateData.whatsappNumber,
        ...buildTeamMemberPermissionUpdates(updateData),
      };

      if (updateData.role !== undefined || updateData.customRoleId !== undefined) {
        userUpdateData.role = nextRole;
        userUpdateData.customRoleId = nextCustomRoleId;
      }

      if (userUpdateData.customPermissions !== undefined) {
        userUpdateData.customPermissions = normalizeAdminCustomPermissionsSnapshot(
          nextRole === 'admin' ? 'admin' : 'agent',
          userUpdateData.customPermissions
        );
      }

      if (updateData.password) {
        userUpdateData.password = await hashPassword(updateData.password);
      }

      const updatedUser = await storage.updateUser(memberId, userUpdateData);

      const { password: _, ...safeUser } = updatedUser;

      res.json(safeUser);
    } catch (error) {
      console.error('Error updating team member:', error);
      res.status(500).json({ message: 'Failed to update team member' });
    }
  });

  app.delete('/api/team/members/:id', ensureAuthenticated, ensureAdmin, ensureCompanyContext, async (req: any, res) => {
    try {
      const memberId = parseInt(req.params.id);
      const user = req.user;

      if (isNaN(memberId)) {
        return res.status(400).json({ message: 'Invalid member ID' });
      }

      const existingMember = await storage.getUser(memberId);
      if (!existingMember) {
        return res.status(404).json({ message: 'Team member not found' });
      }

      if (existingMember.id === user.id) {
        return res.status(400).json({ message: 'You cannot delete your own account' });
      }

      if (!user.isSuperAdmin && existingMember.companyId !== user.companyId) {
        return res.status(403).json({ message: 'Access denied. You can only remove members from your own company.' });
      }

      if (
        existingMember.companyId != null &&
        wouldRemoveLastCompanyAdmin(
          await storage.getUsersByCompany(existingMember.companyId),
          memberId
        )
      ) {
        return res.status(400).json({ message: 'Cannot remove the last company administrator' });
      }

      const success = await storage.deleteUser(memberId);

      if (!success) {
        return res.status(500).json({ message: 'Failed to remove team member' });
      }

      res.json({ message: 'Team member removed successfully' });
    } catch (error) {
      console.error('Error deleting team member:', error);
      res.status(500).json({ message: 'Failed to remove team member' });
    }
  });

