  app.post('/api/v1/email/send', ensureAuthenticated, ensureActiveSubscription, requireAnyPermission([PERMISSIONS.MANAGE_CHANNELS, PERMISSIONS.MANAGE_CONVERSATIONS]), conversationUpload({ directory: UPLOAD_DIR, multiple: true }), async (req, res) => {
    try {
      const user = req.user;
      if (!user) {
        return res.status(401).json({ success: false, message: 'Unauthorized' });
      }

      const {
        channelId,
        to,
        subject,
        content,
        isHtml,
        cc,
        bcc,
        inReplyTo,
        references
      } = req.body;

      if (!channelId || !to || !content) {
        return res.status(400).json({
          success: false,
          message: 'Channel ID, recipient, and content are required'
        });
      }

      let ccArray = [];
      let bccArray = [];

      if (cc) {
        ccArray = typeof cc === 'string' ? JSON.parse(cc) : cc;
      }

      if (bcc) {
        bccArray = typeof bcc === 'string' ? JSON.parse(bcc) : bcc;
      }

      if (Number(channelId) !== (req as any).mediaConversation.channelId) return res.status(403).json({ message: 'Channel does not match conversation' });
      const attachments = [];
      for (const file of (req.files as Express.Multer.File[] || [])) {
        attachments.push({ filename: file.originalname, content: await fsExtra.readFile(file.path), contentType: file.mimetype });
      }

      const emailService = await import('./services/channels/email');
      const message = await emailService.sendMessage(
        parseInt(channelId),
        user.id,
        to,
        subject,
        content,
        {
          cc: ccArray,
          bcc: bccArray,
          isHtml: isHtml === 'true',
          attachments,
          inReplyTo,
          references
        }
      );

      res.json({
        success: true,
        message: 'Email sent successfully',
        data: message
      });
    } catch (error: any) {
      console.error('Error sending email:', error);
      res.status(500).json({
        success: false,
        message: error.message || 'Failed to send email'
      });
    }
  });

