  app.delete('/api/pipeline/stages/:id', ensureAuthenticated, async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const moveDealsToStageId = req.query.moveToStageId ? parseInt(req.query.moveToStageId as string) : undefined;
      const user = req.user as any;

      if (isNaN(id)) {
        return res.status(400).json({ message: 'Invalid stage ID' });
      }

      if (moveDealsToStageId !== undefined && isNaN(moveDealsToStageId)) {
        return res.status(400).json({ message: 'Invalid target stage ID' });
      }

      const existingStage = await storage.getPipelineStage(id);
      if (!existingStage) {
        return res.status(404).json({ message: 'Pipeline stage not found' });
      }

      if (existingStage.companyId !== user.companyId) {
        return res.status(403).json({ message: 'You do not have permission to delete this stage' });
      }

      const stagePipeline = existingStage.pipelineId
        ? await storage.getPipeline(existingStage.pipelineId)
        : null;
      if (!stagePipeline) {
        return res.status(404).json({ message: 'Pipeline not found' });
      }

      const perms = await getUserPermissions(user);
      const stageAccess = await assertUserCanAccessPipeline(user, stagePipeline, perms);
      if (!stageAccess.ok) {
        return res.status(stageAccess.status).json({ message: stageAccess.message });
      }

      if (moveDealsToStageId !== undefined) {
        if (moveDealsToStageId === id) {
          return res.status(400).json({ message: 'Target stage cannot be the same as the deleted stage' });
        }

        const targetStage = await storage.getPipelineStage(moveDealsToStageId);
        if (!targetStage) {
          return res.status(404).json({ message: 'Target stage not found' });
        }

        if (targetStage.companyId !== user.companyId) {
          return res.status(403).json({ message: 'Target stage does not belong to your company' });
        }

        if (targetStage.pipelineId !== stagePipeline.id) {
          return res.status(400).json({ message: 'Cannot move deals to a stage in a different pipeline' });
        }
      }

      const result = await storage.deletePipelineStage(id, moveDealsToStageId);

      if (result) {
        const { invalidatePipelineStageCache, invalidatePipelineCache } = await import('./utils/pipeline-cache');
        invalidatePipelineStageCache(user.companyId);
        invalidatePipelineCache(user.companyId);
        res.status(200).json({ success: true });
      } else {
        res.status(500).json({ message: 'Failed to delete pipeline stage' });
      }
    } catch (error) {
      console.error('Error deleting pipeline stage:', error);
      res.status(500).json({ message: 'Failed to delete pipeline stage' });
    }
  });

  app.get('/api/deals', ensureAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const generalSearch = req.query.generalSearch as string | undefined;
      const pipelineId = req.query.pipelineId ? parseInt(req.query.pipelineId as string) : undefined;
      const includeReverts = req.query.includeReverts === 'true';
      const includeContacts = req.query.includeContacts === 'true';
      const boardView = req.query.boardView === 'true';
      const includeStageSummaries = req.query.includeStageSummaries === 'true' || boardView;
      const perStageLimit = req.query.perStageLimit
        ? parseInt(req.query.perStageLimit as string, 10)
        : PIPELINE_BOARD_DEFAULT_PER_STAGE_LIMIT;
      const limit = req.query.limit ? parseInt(req.query.limit as string, 10) : undefined;
      const offset = req.query.offset ? parseInt(req.query.offset as string, 10) : undefined;
      let stageOffsets: Record<number, number> = {};
      if (req.query.stageOffsets) {
        try {
          const parsed = JSON.parse(req.query.stageOffsets as string) as Record<string, number>;
          stageOffsets = Object.fromEntries(
            Object.entries(parsed)
              .map(([k, v]) => [parseInt(k, 10), v] as const)
              .filter(([k]) => !isNaN(k)),
          );
        } catch {
          // ignore malformed stageOffsets
        }
      }

      // Parse new filter parameters
      const stageIds = req.query.stageIds ? (req.query.stageIds as string).split(',').map(id => parseInt(id)).filter(id => !isNaN(id)) : undefined;
      const priorities = req.query.priorities ? (req.query.priorities as string).split(',') as ('low' | 'medium' | 'high')[] : undefined;
      const minValue = req.query.minValue ? parseFloat(req.query.minValue as string) : undefined;
      const maxValue = req.query.maxValue ? parseFloat(req.query.maxValue as string) : undefined;
      const dueDateFrom = req.query.dueDateFrom as string | undefined;
      const dueDateTo = req.query.dueDateTo as string | undefined;
      const assignedUserIds = req.query.assignedUserIds ? (req.query.assignedUserIds as string).split(',').map(id => parseInt(id)).filter(id => !isNaN(id)) : undefined;
      const includeUnassigned = req.query.includeUnassigned === 'true';
      const tags = req.query.tags ? (req.query.tags as string).split(',') : undefined;
      const status = req.query.status as string | undefined;
      const createdFrom = req.query.createdFrom as string | undefined;
      const createdTo = req.query.createdTo as string | undefined;

      if (!user.companyId) {
        return res.status(400).json({ message: 'User must be associated with a company' });
      }

      const filter: DealsFilter = {
        companyId: user.companyId
      };

      if (generalSearch) {
        filter.generalSearch = generalSearch;
      }

      if (pipelineId && !isNaN(pipelineId)) {
        filter.pipelineId = pipelineId;
      }

      if (stageIds && stageIds.length > 0) {
        filter.stageIds = stageIds;
      }

      if (priorities && priorities.length > 0) {
        filter.priorities = priorities;
      }

      if (minValue !== undefined && !isNaN(minValue)) {
        filter.minValue = minValue;
      }

      if (maxValue !== undefined && !isNaN(maxValue)) {
        filter.maxValue = maxValue;
      }

      if (dueDateFrom) {
        filter.dueDateFrom = dueDateFrom;
      }

      if (dueDateTo) {
        filter.dueDateTo = dueDateTo;
      }

      if (assignedUserIds && assignedUserIds.length > 0) {
        filter.assignedUserIds = assignedUserIds;
      }

      if (includeUnassigned) {
        filter.includeUnassigned = includeUnassigned;
      }

      if (tags && tags.length > 0) {
        filter.tags = tags;
      }

      if (status) {
        filter.status = status;
      }

      if (createdFrom) {
        filter.createdFrom = createdFrom;
      }

      if (createdTo) {
        filter.createdTo = createdTo;
      }

      // Parse customFields from query param
      if (req.query.customFields) {
        try {
          const customFieldsStr = req.query.customFields as string;
          filter.customFields = JSON.parse(customFieldsStr);
        } catch (error) {
          console.error('Error parsing customFields:', error);
          // Ignore malformed JSON, continue without custom fields filter
        }
      }

      if (limit !== undefined && !isNaN(limit)) {
        filter.limit = limit;
      }
      if (offset !== undefined && !isNaN(offset)) {
        filter.offset = offset;
      }

      const enrichDealsWithReverts = async (dealList: any[]) => {
        if (!includeReverts || dealList.length === 0) {
          return dealList;
        }
        const dealIds = dealList.map((d) => d.id);
        const allReverts = await storage.getPipelineStageRevertsByDealIds(user.companyId, dealIds);
        const revertsByDealId = new Map<number, typeof allReverts>();
        for (const revert of allReverts) {
          const bucket = revertsByDealId.get(revert.dealId);
          if (bucket) {
            bucket.push(revert);
          } else {
            revertsByDealId.set(revert.dealId, [revert]);
          }
        }
        return dealList.map((deal) => {
          const reverts = revertsByDealId.get(deal.id) ?? [];
          const activeReverts = reverts.filter((r) => r.status === 'scheduled');
          return {
            ...deal,
            scheduledReverts: reverts,
            hasScheduledReverts: activeReverts.length > 0,
          };
        });
      };

      const enrichDealsWithContacts = async (dealList: any[]) => {
        if (!includeContacts || dealList.length === 0) {
          return dealList;
        }
        const contactIds = [...new Set(dealList.map((d) => d.contactId).filter(Boolean))] as number[];
        const contacts = await storage.getContactsByIdsForCompany(user.companyId, contactIds);
        const contactsById = new Map(contacts.map((c) => [c.id, c]));
        return dealList.map((deal) => ({
          ...deal,
          contact: contactsById.get(deal.contactId) ?? null,
        }));
      };

      if (boardView && pipelineId && !isNaN(pipelineId)) {
        const stages = await storage.getPipelineStagesByPipeline(pipelineId);
        let stageIds = stages.map((s) => s.id);
        if (filter.stageIds && filter.stageIds.length > 0) {
          const allowed = new Set(filter.stageIds);
          stageIds = stageIds.filter((id) => allowed.has(id));
        }
        const safePerStageLimit =
          !isNaN(perStageLimit) && perStageLimit > 0
            ? perStageLimit
            : PIPELINE_BOARD_DEFAULT_PER_STAGE_LIMIT;

        const { dealsByStageId, stagePagination, stageSummaries: boardStageSummaries } =
          await storage.getDealsForPipelineBoard(filter, stageIds, safePerStageLimit, stageOffsets);

        const flatDeals = stageIds.flatMap((stageId) => dealsByStageId[stageId] ?? []);
        let enrichedDeals = await enrichDealsWithReverts(flatDeals);
        enrichedDeals = await enrichDealsWithContacts(enrichedDeals);

        const enrichedById = new Map(enrichedDeals.map((d) => [d.id, d]));
        const enrichedDealsByStageId: Record<number, any[]> = {};
        for (const stageId of stageIds) {
          enrichedDealsByStageId[stageId] = (dealsByStageId[stageId] ?? []).map(
            (d) => enrichedById.get(d.id) ?? d,
          );
        }

        return res.status(200).json({
          dealsByStageId: enrichedDealsByStageId,
          stageSummaries: includeStageSummaries ? boardStageSummaries : {},
          stagePagination,
          deals: enrichedDeals,
        });
      }

      const deals = await storage.getDeals(filter);
      let result: any[] = deals;
      result = await enrichDealsWithReverts(result);
      result = await enrichDealsWithContacts(result);
      return res.status(200).json(result);
    } catch (error) {
      console.error("Error fetching deals:", error);
      res.status(500).json({ message: 'Internal server error' });
    }
  });

