  app.post('/api/company/custom-fields', ensureAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const { entity, fieldName, fieldType, fieldLabel, options, required, displayOrder } = req.body;

      if (!user.companyId) {
        return res.status(400).json({ message: 'User must be associated with a company' });
      }

      if (!entity || !fieldType || !fieldLabel) {
        return res.status(400).json({ message: 'entity, fieldType, and fieldLabel are required' });
      }

      const validEntities = ['deal', 'contact', 'company'];
      const validTypes = ['text', 'number', 'select', 'multi_select', 'date', 'boolean', 'file_select'];
      if (!validEntities.includes(entity)) {
        return res.status(400).json({ message: 'Invalid entity. Must be deal, contact, or company' });
      }
      if (!validTypes.includes(fieldType)) {
        return res.status(400).json({ message: 'Invalid fieldType' });
      }
      if (entity === 'company' && fieldType === 'file_select') {
        return res.status(400).json({ message: 'File Select is supported only for contacts and deals' });
      }

      const labelTrimmed = String(fieldLabel).trim();
      const fieldNameSanitized = fieldName
        ? String(fieldName).trim().toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '')
        : labelTrimmed.toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '');
      if (!fieldNameSanitized) {
        return res.status(400).json({ message: 'fieldLabel must contain at least one valid character' });
      }

      const customField = await storage.createCompanyCustomField({
        companyId: user.companyId,
        entity,
        fieldName: fieldNameSanitized,
        fieldType,
        fieldLabel: labelTrimmed,
        options: options || null,
        required: !!required,
        displayOrder: typeof displayOrder === 'number' ? displayOrder : 0,
      });

      return res.status(201).json(customField);
    } catch (error: any) {
      console.error('Error creating custom field:', error);
      if (error.code === '23505') {
        return res.status(400).json({ message: 'A custom field with this name already exists for this entity' });
      }
      res.status(500).json({ message: 'Internal server error' });
    }
  });

  app.patch('/api/company/custom-fields/:id', ensureAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const id = parseInt(req.params.id);
      const { fieldLabel, fieldType, options, required, displayOrder } = req.body;

      if (!user.companyId) {
        return res.status(400).json({ message: 'User must be associated with a company' });
      }

      const field = await storage.getCompanyCustomFieldById(id, user.companyId);
      if (!field) {
        return res.status(404).json({ message: 'Custom field not found or access denied' });
      }

      const updates: any = {};
      if (fieldLabel !== undefined) updates.fieldLabel = String(fieldLabel).trim();
      if (fieldType !== undefined) {
        const validTypes = ['text', 'number', 'select', 'multi_select', 'date', 'boolean', 'file_select'];
        if (!validTypes.includes(fieldType)) {
          return res.status(400).json({ message: 'Invalid fieldType' });
        }
        if (field.entity === 'company' && fieldType === 'file_select') {
          return res.status(400).json({ message: 'File Select is supported only for contacts and deals' });
        }
        updates.fieldType = fieldType;
      }
      if (options !== undefined) updates.options = options;
      if (required !== undefined) updates.required = !!required;
      if (displayOrder !== undefined) updates.displayOrder = Number(displayOrder);

      const updated = await storage.updateCompanyCustomField(id, updates);
      return res.status(200).json(updated);
    } catch (error) {
      console.error('Error updating custom field:', error);
      res.status(500).json({ message: 'Internal server error' });
    }
  });

  app.put('/api/company/custom-fields/reorder', ensureAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const { entity, customFieldIds } = req.body;

      if (!user.companyId) {
        return res.status(400).json({ message: 'User must be associated with a company' });
      }

      if (!entity || !['contact', 'deal', 'company'].includes(entity)) {
        return res.status(400).json({ message: 'Valid entity (contact, deal, or company) is required' });
      }

      if (!Array.isArray(customFieldIds)) {
        return res.status(400).json({ message: 'customFieldIds must be an array' });
      }

      const ids = customFieldIds.map((id: any) => parseInt(String(id))).filter((id: number) => !isNaN(id));
      if (ids.length !== customFieldIds.length) {
        return res.status(400).json({ message: 'All customFieldIds must be valid numbers' });
      }

      await storage.reorderCompanyCustomFields(user.companyId, entity, ids);
      return res.status(200).json({ success: true });
    } catch (error: any) {
      console.error('Error reordering custom fields:', error);
      const statusCode = error.message?.includes('Invalid') || error.message?.includes('Duplicate') ? 400 : 500;
      return res.status(statusCode).json({ message: error.message || 'Failed to reorder custom fields' });
    }
  });

