  app.get('/api/deals/export', ensureAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const { format = 'json', stageId } = req.query;




      let deals;
      try {
        if (stageId) {
          deals = await storage.getDealsByStageId(parseInt(stageId as string));
        } else {
          deals = await storage.getDeals();
        }
      } catch (error) {
        console.error('Error fetching deals:', error);
        return res.status(500).json({ message: 'Failed to fetch deals from database' });
      }




      if (!user.isSuperAdmin && user.companyId) {
        deals = deals.filter(deal => deal.companyId === user.companyId);
      }




      const stages = await storage.getPipelineStages();
      const teamMembers = await storage.getAllTeamMembers();

      // Fetch pipelines - handle super-admins without a companyId
      const pipelines = user.companyId 
        ? await storage.getPipelinesByCompany(user.companyId)
        : await storage.getPipelines();
      const pipelinesMap = new Map(pipelines.map(p => [p.id, p]));

      const contactIdsSet = new Set<number>();
      deals.forEach(deal => contactIdsSet.add(deal.contactId));
      const contactIds = Array.from(contactIdsSet);



      const contacts = await Promise.all(
        contactIds.map(async (contactId) => {
          try {
            return await storage.getContact(contactId);
          } catch (error) {
            console.warn(`Failed to get contact ${contactId}:`, error);
            return null;
          }
        })
      );
      const contactsMap = new Map(contacts.filter(Boolean).map(c => [c!.id, c]));


      const enrichedDeals = deals.map(deal => {
        const stage = stages.find(s => s.id === deal.stageId);
        const assignee = teamMembers.find((m: any) => m.id === deal.assignedToUserId);
        const contact = contactsMap.get(deal.contactId);

        return {
          id: deal.id,
          title: deal.title,
          description: deal.description,
          value: deal.value,
          priority: deal.priority,
          contactId: deal.contactId,
          contactName: contact?.name || '',
          contactEmail: contact?.email || '',
          contactPhone: contact?.phone || '',
          assignedToUserId: deal.assignedToUserId,
          assignedToEmail: assignee?.email || '',
          assignedToName: assignee?.fullName || assignee?.username || '',
          tags: Array.isArray(deal.tags) ? deal.tags : [],
          pipelineId: deal.pipelineId,
          pipelineName: pipelinesMap.get(deal.pipelineId)?.name || '',
          stage: stage?.name || '',
          stageId: deal.stageId,
          createdAt: deal.createdAt,
          updatedAt: deal.updatedAt
        };
      });



      if (format === 'json') {
        res.setHeader('Content-Type', 'application/json');
        res.setHeader('Content-Disposition', `attachment; filename="deals_export_${new Date().toISOString().split('T')[0]}.json"`);
        return res.json(enrichedDeals);
      } else {
        const tabularFormat = parseExportFormat(format);
        if (!tabularFormat) return res.status(400).json({ message: 'Unsupported export format. Use json, csv, xlsx, or excel.' });
        const rows = enrichedDeals.map((deal) => ({ ...deal, tags: Array.isArray(deal.tags) ? deal.tags.join(', ') : '' }));
        return await sendTabularExport(res, {
          filename: `deals-export-${new Date().toISOString().split('T')[0]}`,
          format: tabularFormat,
          sheets: [{ name: 'Deals', rows, columns: [
            { key: 'id', header: 'ID', type: 'string' }, { key: 'title', header: 'Title', width: 28 },
            { key: 'description', header: 'Description', width: 40 }, { key: 'value', header: 'Value', type: 'currency', numberFormat: '#,##0.00' },
            { key: 'priority', header: 'Priority' }, { key: 'contactId', header: 'Contact ID', type: 'string' },
            { key: 'contactName', header: 'Contact Name', width: 24 }, { key: 'contactEmail', header: 'Contact Email', width: 28 },
            { key: 'contactPhone', header: 'Contact Phone', type: 'string', width: 20 }, { key: 'assignedToUserId', header: 'Assigned User ID', type: 'string' },
            { key: 'assignedToEmail', header: 'Assigned Email', width: 28 }, { key: 'assignedToName', header: 'Assigned Name', width: 24 },
            { key: 'tags', header: 'Tags', width: 24 }, { key: 'pipelineId', header: 'Pipeline ID', type: 'string' },
            { key: 'pipelineName', header: 'Pipeline', width: 24 }, { key: 'stage', header: 'Stage', width: 20 },
            { key: 'stageId', header: 'Stage ID', type: 'string' }, { key: 'createdAt', header: 'Created At', type: 'date', width: 22, numberFormat: 'yyyy-mm-dd hh:mm' },
            { key: 'updatedAt', header: 'Updated At', type: 'date', width: 22, numberFormat: 'yyyy-mm-dd hh:mm' },
          ] }],
        });
      }
    } catch (error) {
      console.error('Error exporting deals:', error);
      res.status(500).json({
        message: 'Internal server error',
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

