  app.delete('/api/deals/bulk-delete', ensureAuthenticated, async (req: any, res) => {
    try {
      const { dealIds } = req.body;

      if (!Array.isArray(dealIds) || dealIds.length === 0) {
        return res.status(400).json({ message: 'dealIds must be a non-empty array' });
      }

      const results = [];
      let successCount = 0;
      let failureCount = 0;

      for (const dealId of dealIds) {
        try {
          const parsedDealId = parseInt(dealId);
          if (isNaN(parsedDealId) || parsedDealId <= 0) {
            results.push({
              dealId,
              status: 'error',
              message: 'Invalid deal ID format'
            });
            failureCount++;
            continue;
          }

          const deleteResult = await storage.deleteDeal(parsedDealId, req.user.companyId);
          if (deleteResult.success) {
            const attachments = await storage.listCustomFieldAttachments(req.user.companyId, 'deal', parsedDealId);
            for (const attachment of attachments) {
              await storage.clearCustomFieldFileReferences('deal', parsedDealId, 'custom_field_attachment', attachment.id);
              await storage.deleteCustomFieldAttachment(req.user.companyId, attachment.id);
              await fsExtra.unlink(attachment.filePath).catch(() => undefined);
              void dataUsageTracker.trackFileDelete(req.user.companyId, attachment.fileSize);
            }
            results.push({
              dealId: parsedDealId,
              status: 'success',
              message: deleteResult.reason || 'Deleted successfully'
            });
            successCount++;
          } else {
            results.push({
              dealId: parsedDealId,
              status: 'not_found',
              message: deleteResult.reason || 'Deal not found or already deleted'
            });
            failureCount++;
          }
        } catch (error: any) {
          results.push({ dealId, status: 'error', message: error.message || 'Unknown error' });
          failureCount++;
        }
      }

      return res.status(200).json({
        message: `${successCount} deals deleted successfully${failureCount > 0 ? `, ${failureCount} failed` : ''}`,
        deletedCount: successCount,
        failedCount: failureCount,
        results
      });
    } catch (error) {
      res.status(500).json({ message: 'Internal server error' });
    }
  });

