  const dealsUploadStorage = multer.diskStorage({
    destination: (req, file, cb) => {
      const uploadPath = path.join(process.cwd(), 'uploads', 'deals');
      if (!fs.existsSync(uploadPath)) {
        fs.mkdirSync(uploadPath, { recursive: true });
      }
      cb(null, uploadPath);
    },
    filename: (req, file, cb) => {
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      const filename = `deals-import-${timestamp}-${file.originalname}`;
      cb(null, filename);
    }
  });

  const dealsUpload = multer({
    storage: dealsUploadStorage,
    limits: {
      fileSize: 10 * 1024 * 1024, // 10MB
      files: 1
    },
    fileFilter: (req, file, cb) => {
      const allowedTypes = ['text/csv', 'application/json', 'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];
      const allowedExtensions = ['.csv', '.json', '.xlsx', '.xls'];

      if (allowedTypes.includes(file.mimetype) || allowedExtensions.some(ext => file.originalname.endsWith(ext))) {
        cb(null, true);
      } else {
        cb(new Error('Only CSV, JSON, and Excel files are allowed.'));
      }
    }
  });

  app.post('/api/deals/import', ensureAuthenticated, dealsUpload.single('file'), async (req: any, res) => {
    try {
      const user = req.user as any;
      const file = req.file;

      if (!file) {
        return res.status(400).json({ message: 'No file uploaded' });
      }

      let dealsData: any[] = [];
      const filePath = file.path;

      try {
        if (file.originalname.endsWith('.json')) {

          const fileContent = fs.readFileSync(filePath, 'utf8');
          dealsData = JSON.parse(fileContent);

          if (!Array.isArray(dealsData)) {
            throw new Error('JSON file must contain an array of deals');
          }
        } else if (file.originalname.endsWith('.csv')) {

          const parseCSVLine = (line: string): string[] => {
            const values: string[] = [];
            let current = '';
            let inQuotes = false;
            for (let ci = 0; ci < line.length; ci++) {
              const ch = line[ci];
              if (ch === '"') {
                if (inQuotes && line[ci + 1] === '"') {
                  current += '"';
                  ci++;
                } else {
                  inQuotes = !inQuotes;
                }
              } else if (ch === ',' && !inQuotes) {
                values.push(current.trim());
                current = '';
              } else {
                current += ch;
              }
            }
            values.push(current.trim());
            return values;
          };

          const fileContent = fs.readFileSync(filePath, 'utf8');
          const lines = fileContent.split('\n');
          const headers = parseCSVLine(lines[0]);

          dealsData = lines.slice(1)
            .filter(line => line.trim())
            .map(line => {
              const values = parseCSVLine(line);
              const deal: any = {};
              headers.forEach((header, index) => {
                deal[header] = values[index] ?? '';
              });
              return deal;
            });
        } else {
          return res.status(400).json({ message: 'Unsupported file format' });
        }


        const results = { success: 0, failed: 0, skipped: 0, errors: [] as any[] };
        const teamMembers = await storage.getAllTeamMembers();
        let companyPipelines = await storage.getPipelinesByCompany(user.companyId);
        const defaultPipeline = companyPipelines.find(p => p.isDefault === true);
        const companyIdNum = user.companyId ? Number(user.companyId) : null;
        const createdPipelinesByName = new Map<string, { pipelineId: number; stageId: number | null }>();

        for (let i = 0; i < dealsData.length; i++) {
          try {
            const dealData = dealsData[i];

            // Determine target pipeline: use CSV pipeline if it exists and belongs to company; if not found, create one (cached by name); else use default
            let targetPipelineId: number | null = null;
            const csvPipelineId = dealData.pipelineId ? parseInt(dealData.pipelineId.toString()) : NaN;
            const pipelineNameFromCsv = (dealData.pipelineName && String(dealData.pipelineName).trim()) || '';

            if (!isNaN(csvPipelineId)) {
              const pipeline = await storage.getPipeline(csvPipelineId);
              if (pipeline && companyIdNum != null && Number(pipeline.companyId) === companyIdNum) {
                targetPipelineId = pipeline.id;
              }
            }
            if (targetPipelineId == null && companyIdNum != null && (pipelineNameFromCsv || !isNaN(csvPipelineId))) {
              const pipelineName = pipelineNameFromCsv || `Imported Pipeline ${csvPipelineId}`;
              let created = createdPipelinesByName.get(pipelineName);
              if (!created) {
                const existingByName = companyPipelines.find(p => (p.name || '').trim().toLowerCase() === pipelineName.trim().toLowerCase());
                if (existingByName) {
                  const stages = await storage.getPipelineStagesByCompany(user.companyId, existingByName.id);
                  created = { pipelineId: existingByName.id, stageId: stages[0]?.id ?? null };
                  createdPipelinesByName.set(pipelineName, created);
                } else {
                  try {
                    const newPipeline = await storage.createPipeline({
                      companyId: companyIdNum,
                      name: pipelineName,
                      orderNum: 0,
                    });
                    const firstStage = await storage.createPipelineStage({
                      pipelineId: newPipeline.id,
                      companyId: companyIdNum,
                      name: (dealData.stage && String(dealData.stage).trim()) || 'Stage 1',
                      color: '#6B7280',
                      order: 1,
                    });
                    created = { pipelineId: newPipeline.id, stageId: firstStage.id };
                    createdPipelinesByName.set(pipelineName, created);
                    companyPipelines = [...companyPipelines, newPipeline];
                  } catch (pipeErr: any) {
                    if (pipeErr?.code === '23505' && (pipeErr?.constraint === 'idx_pipelines_company_name_unique' || pipeErr?.message?.includes('idx_pipelines_company_name_unique'))) {
                      const refetched = await storage.getPipelinesByCompany(user.companyId);
                      const again = refetched.find(p => (p.name || '').trim().toLowerCase() === pipelineName.trim().toLowerCase());
                      if (again) {
                        const stages = await storage.getPipelineStagesByCompany(user.companyId, again.id);
                        created = { pipelineId: again.id, stageId: stages[0]?.id ?? null };
                        createdPipelinesByName.set(pipelineName, created);
                        companyPipelines = refetched;
                      } else {
                        throw pipeErr;
                      }
                    } else {
                      throw pipeErr;
                    }
                  }
                }
              }
              targetPipelineId = created.pipelineId;
            }
            if (targetPipelineId == null) {
              targetPipelineId = defaultPipeline?.id ?? null;
            }
            if (targetPipelineId == null) {
              throw new Error('No default pipeline found for company');
            }

            const pipeline = await storage.getPipeline(targetPipelineId);
            if (!pipeline || (companyIdNum != null && Number(pipeline.companyId) !== companyIdNum)) {
              throw new Error('Invalid pipeline or pipeline does not belong to your company');
            }

            // Fetch stages for the specific pipeline
            const pipelineStages = await storage.getPipelineStagesByCompany(user.companyId, targetPipelineId);

            let stageId = dealData.stageId;
            if (dealData.stage && !stageId) {
              const stage = pipelineStages.find(s => s.name.toLowerCase() === dealData.stage.toLowerCase());
              stageId = stage?.id || pipelineStages[0]?.id; // Default to first stage of target pipeline if not found
            }

            if (stageId) {
              const stageIdNum = parseInt(stageId.toString());
              if (!isNaN(stageIdNum)) {
                const stageExists = pipelineStages.find(s => s.id === stageIdNum);
                if (!stageExists) {
                  stageId = pipelineStages[0]?.id || null;
                } else {
                  stageId = stageIdNum;
                }
              } else {
                stageId = pipelineStages[0]?.id || null;
              }
            } else {
              stageId = pipelineStages[0]?.id || null;
            }


            let assignedToUserId = dealData.assignedToUserId;
            if (dealData.assignedToEmail && !assignedToUserId) {
              const member = teamMembers.find((m: any) => m.email === dealData.assignedToEmail);
              assignedToUserId = member?.id;
            }


            let contactId: number | null = dealData.contactId ? Number(dealData.contactId) : null;

            if (contactId && !Number.isNaN(contactId)) {
              const existingById = await storage.getContact(contactId);
              if (!existingById) {
                contactId = null;
              }
            } else {
              contactId = null;
            }

            if (!contactId) {
              if (dealData.contactEmail) {
                const contactsResult = await storage.getContacts({ search: dealData.contactEmail });
                const existingContact = contactsResult.contacts.find(c => c.email === dealData.contactEmail);
                if (existingContact) {
                  contactId = existingContact.id;
                } else {
                  const newContact = await storage.createContact({
                    name: dealData.contactName || 'Imported Contact',
                    email: dealData.contactEmail,
                    phone: dealData.contactPhone || null,
                    companyId: user.companyId || null,
                    createdBy: user.id,
                    identifierType: 'whatsapp_unofficial',
                    identifier: dealData.contactPhone || dealData.contactEmail || null,
                    source: 'whatsapp'
                  });
                  contactId = newContact.id;
                }
              } else if (dealData.contactPhone) {
                const existingByPhone = await storage.getContactByPhone(dealData.contactPhone, user.companyId);
                if (existingByPhone) {
                  contactId = existingByPhone.id;
                } else {
                  const newContact = await storage.createContact({
                    name: dealData.contactName || 'Imported Contact',
                    email: null,
                    phone: dealData.contactPhone,
                    companyId: user.companyId || null,
                    createdBy: user.id,
                    identifierType: 'whatsapp_unofficial',
                    identifier: dealData.contactPhone,
                    source: 'whatsapp'
                  });
                  contactId = newContact.id;
                }
              } else if (dealData.contactName) {
                const newContact = await storage.createContact({
                  name: dealData.contactName,
                  email: null,
                  phone: null,
                  companyId: user.companyId || null,
                  createdBy: user.id,
                  identifierType: 'whatsapp_unofficial',
                  identifier: null,
                  source: 'whatsapp'
                });
                contactId = newContact.id;
              }
            }

            if (!contactId) {
              throw new Error('Contact information is required (contactId, contactEmail, contactPhone or contactName)');
            }


            let tags: string[] | null = null;
            if (dealData.tags) {
              if (Array.isArray(dealData.tags)) {
                tags = dealData.tags.filter((tag: unknown): tag is string =>
                  typeof tag === 'string' && tag.trim().length > 0
                );
              } else if (typeof dealData.tags === 'string' && dealData.tags.trim()) {

                tags = dealData.tags
                  .split(',')
                  .map((tag: string): string => tag.trim())
                  .filter((tag: string): boolean => tag.length > 0);
              }
            }


            const existingDeal = await storage.getActiveDealByContact(Number(contactId), companyIdNum ?? undefined, targetPipelineId);
            if (existingDeal) {
              results.skipped++;
            } else {
              const newDeal = {
                title: dealData.title || `Imported Deal ${i + 1}`,
                contactId: parseInt(contactId.toString()),
                description: dealData.description || null,
                value: dealData.value ? parseFloat(dealData.value.toString()) : null,
                priority: (dealData.priority as 'low' | 'medium' | 'high') || 'medium',
                assignedToUserId: assignedToUserId ? parseInt(assignedToUserId.toString()) : null,
                pipelineId: parseInt(targetPipelineId.toString()),
                stageId: stageId,
                companyId: user.companyId ? parseInt(user.companyId.toString()) : null,
                tags: tags,
                status: 'active'
              };
              await storage.createDeal(newDeal);
              results.success++;
            }
          } catch (error) {
            results.failed++;
            results.errors.push({
              row: i + 1,
              error: error instanceof Error ? error.message : 'Unknown error',
              data: dealsData[i]
            });
          }
        }

        if (user.companyId) {
          const { invalidatePipelineCache, invalidatePipelineStageCache } = await import('./utils/pipeline-cache');
          invalidatePipelineCache(user.companyId);
          invalidatePipelineStageCache(user.companyId);
        }

        fs.unlinkSync(filePath);

        return res.json(results);
      } catch (parseError) {

        if (fs.existsSync(filePath)) {
          fs.unlinkSync(filePath);
        }

        return res.status(400).json({
          message: 'Failed to parse file: ' + (parseError instanceof Error ? parseError.message : 'Unknown error')
        });
      }
    } catch (error) {
      console.error('Error importing deals:', error);
      res.status(500).json({ message: 'Internal server error' });
    }
  });

