  app.get('/api/pipeline/stages', ensureAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const pipelineId = req.query.pipelineId ? parseInt(req.query.pipelineId as string) : undefined;

      if (!user.companyId) {
        return res.json([]);
      }

      const perms = await getUserPermissions(user);

      let stages: PipelineStage[];
      if (pipelineId) {
        // Verify pipeline ownership
        const pipeline = await storage.getPipeline(pipelineId);
        if (!pipeline) {
          return res.status(404).json({ message: 'Pipeline not found' });
        }
        if (pipeline.companyId !== user.companyId) {
          return res.status(403).json({ message: 'You do not have permission to access this pipeline' });
        }
        const access = await assertUserCanAccessPipeline(user, pipeline, perms);
        if (!access.ok) {
          return res.status(access.status).json({ message: access.message });
        }
        stages = await storage.getPipelineStagesByPipeline(pipelineId);
      } else {
        stages = await storage.getPipelineStagesByCompany(user.companyId);
        if (!user.isSuperAdmin && user.role === 'agent' && !perms[PERMISSIONS.MANAGE_PIPELINE]) {
          if (perms[PERMISSIONS.VIEW_OWN_PIPELINES] !== true) {
            stages = [];
          } else {
            const assignments = await storage.getPipelineAssignmentsByUser(user.id, user.companyId);
            const assignedIds = new Set(assignments.map(a => a.pipelineId));
            const companyPipelines = await storage.getPipelinesByCompany(user.companyId);
            const allowedPipelineIds = new Set(
              companyPipelines.filter(p => p.createdBy === user.id || assignedIds.has(p.id)).map(p => p.id)
            );
            stages = stages.filter(s => s.pipelineId != null && allowedPipelineIds.has(s.pipelineId));
          }
        }
      }

      res.json(stages);
    } catch (error) {
      console.error('Error fetching pipeline stages:', error);
      res.status(500).json({ message: 'Failed to fetch pipeline stages' });
    }
  });

