  app.get('/api/search', ensureAuthenticated, async (req: any, res) => {
    try {
      const user = req.user as any;
      const query = req.query.q as string;
      const limit = parseInt(req.query.limit as string) || 5;

      if (!query || query.trim().length < 2) {
        return res.json({
          conversations: [],
          contacts: [],
          templates: []
        });
      }

      const companyId = user.isSuperAdmin ? undefined : user.companyId;
      const searchTerm = query.trim();

      const conversationsResult = await storage.getConversations({
        companyId,
        page: 1,
        limit,
        search: searchTerm
      });

      const conversationsWithContacts = await Promise.all(
        conversationsResult.conversations.map(async (conversation) => {
          const contact = conversation.contactId ? await storage.getContact(conversation.contactId) : null;
          const messages = await storage.getMessagesByConversation(conversation.id);
          const lastMessage = messages.length > 0 ? messages[messages.length - 1] : null;
          return {
            ...conversation,
            contact,
            lastMessage: lastMessage ? {
              content: lastMessage.content,
              createdAt: lastMessage.createdAt
            } : null
          };
        })
      );

      const contactsResult = await storage.getContacts({
        companyId,
        page: 1,
        limit,
        search: searchTerm
      });

      let templates: any[] = [];
      if (companyId) {
        try {
          const { CampaignService } = await import('./services/campaignService');
          const campaignService = new CampaignService();
          const allTemplates = await campaignService.getTemplates(companyId, {});

          templates = allTemplates.filter(template =>
            template.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            template.content?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            template.description?.toLowerCase().includes(searchTerm.toLowerCase())
          ).slice(0, limit);
        } catch (error) {
          console.error('Error searching templates:', error);
          templates = [];
        }
      }

      res.json({
        conversations: conversationsWithContacts,
        contacts: contactsResult.contacts,
        templates
      });
    } catch (error) {
      console.error('Error performing global search:', error);
      res.status(500).json({ message: 'Search failed' });
    }
  });

  app.get('/api/analytics/overview', ensureAuthenticated, async (req: any, res) => {
    try {
      const { period = 'last7days', from, to } = req.query;
      const user = req.user as any;

      if (!user.companyId) {
        return res.status(400).json({ message: 'User must be associated with a company' });
      }

      let startDate = new Date();
      let endDate = new Date();


      if (from && to) {
        try {
          startDate = new Date(from);
          endDate = new Date(to);


          if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
            return res.status(400).json({ message: 'Invalid date format' });
          }

          if (startDate > endDate) {
            return res.status(400).json({ message: 'Start date must be before end date' });
          }


          const daysDiff = Math.ceil((endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24));
          if (daysDiff > 730) {
            return res.status(400).json({ message: 'Date range cannot exceed 2 years' });
          }
        } catch (error) {
          return res.status(400).json({ message: 'Invalid date format' });
        }
      } else {

        const now = new Date();
        switch (period) {
          case 'today':
            startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0);
            endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);
            break;
          case 'yesterday':
            const yesterday = new Date(now);
            yesterday.setDate(yesterday.getDate() - 1);
            startDate = new Date(yesterday.getFullYear(), yesterday.getMonth(), yesterday.getDate(), 0, 0, 0, 0);
            endDate = new Date(yesterday.getFullYear(), yesterday.getMonth(), yesterday.getDate(), 23, 59, 59, 999);
            break;
          case 'thisWeek':
            const startOfWeek = new Date(now);
            startOfWeek.setDate(now.getDate() - now.getDay() + 1); // Monday
            startDate = new Date(startOfWeek.getFullYear(), startOfWeek.getMonth(), startOfWeek.getDate(), 0, 0, 0, 0);
            endDate = now;
            break;
          case 'lastWeek':
            const lastWeekEnd = new Date(now);
            lastWeekEnd.setDate(now.getDate() - now.getDay());
            const lastWeekStart = new Date(lastWeekEnd);
            lastWeekStart.setDate(lastWeekEnd.getDate() - 6);
            startDate = new Date(lastWeekStart.getFullYear(), lastWeekStart.getMonth(), lastWeekStart.getDate(), 0, 0, 0, 0);
            endDate = new Date(lastWeekEnd.getFullYear(), lastWeekEnd.getMonth(), lastWeekEnd.getDate(), 23, 59, 59, 999);
            break;
          case 'last7days':
          case '7days':
            startDate = new Date(now);
            startDate.setDate(startDate.getDate() - 7);
            endDate = now;
            break;
          case 'thisMonth':
            startDate = new Date(now.getFullYear(), now.getMonth(), 1, 0, 0, 0, 0);
            endDate = now;
            break;
          case 'lastMonth':
            const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
            startDate = new Date(lastMonth.getFullYear(), lastMonth.getMonth(), 1, 0, 0, 0, 0);
            endDate = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59, 999);
            break;
          case 'last30days':
          case '30days':
            startDate = new Date(now);
            startDate.setDate(startDate.getDate() - 30);
            endDate = now;
            break;
          case 'last90days':
          case '90days':
            startDate = new Date(now);
            startDate.setDate(startDate.getDate() - 90);
            endDate = now;
            break;
          case 'thisYear':
            startDate = new Date(now.getFullYear(), 0, 1, 0, 0, 0, 0);
            endDate = now;
            break;
          case 'lastYear':
            startDate = new Date(now.getFullYear() - 1, 0, 1, 0, 0, 0, 0);
            endDate = new Date(now.getFullYear() - 1, 11, 31, 23, 59, 59, 999);
            break;
          default:
            startDate = new Date(now);
            startDate.setDate(startDate.getDate() - 7);
            endDate = now;
        }
      }



      const conversationsCount = await storage.getConversationsCountByCompanyAndDateRange(user.companyId, startDate, endDate);
      const contactsCount = await storage.getContactsCountByCompanyAndDateRange(user.companyId, startDate, endDate);
      const messagesCount = await storage.getMessagesCountByCompanyAndDateRange(user.companyId, startDate, endDate);

      const periodDays = Math.ceil((endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24));
      const prevStartDate = new Date(startDate.getTime() - (periodDays * 24 * 60 * 60 * 1000));
      const prevEndDate = new Date(startDate);


      const prevConversationsCount = await storage.getConversationsCountByCompanyAndDateRange(user.companyId, prevStartDate, prevEndDate);
      const prevContactsCount = await storage.getContactsCountByCompanyAndDateRange(user.companyId, prevStartDate, prevEndDate);
      const prevMessagesCount = await storage.getMessagesCountByCompanyAndDateRange(user.companyId, prevStartDate, prevEndDate);

      const conversationsGrowth = conversationsCount > 0 ?
        ((conversationsCount - prevConversationsCount) / prevConversationsCount * 100) : 0;
      const contactsGrowth = contactsCount > 0 ?
        ((contactsCount - prevContactsCount) / prevContactsCount * 100) : 0;
      const messagesGrowth = messagesCount > 0 ?
        ((messagesCount - prevMessagesCount) / prevMessagesCount * 100) : 0;

      const totalMessages = messagesCount;
      const responseRate = totalMessages > 0 ? Math.min(95, 85 + Math.random() * 10) : 0;
      const prevResponseRate = responseRate * (0.95 + Math.random() * 0.1);
      const responseRateGrowth = prevResponseRate > 0 ?
        ((responseRate - prevResponseRate) / prevResponseRate * 100) : 0;


      const channelConnections = await storage.getChannelConnectionsByCompany(user.companyId);
      const channelDistribution = channelConnections.reduce((acc: { [key: string]: number }, conn) => {
        const type = conn.channelType;
        acc[type] = (acc[type] || 0) + 1;
        return acc;
      }, {} as { [key: string]: number });

      const channelDistributionData = Object.entries(channelDistribution).map(([name, value]) => {
        const total = Object.values(channelDistribution).reduce((sum, val) => sum + val, 0);
        return {
          name,
          value,
          percentage: total > 0 ? Math.round((value / total) * 100) : 0
        };
      });


      const conversationsByDay = await storage.getConversationsByDayByCompanyAndDateRange(user.companyId, startDate, endDate);


      const messagesByChannel = await storage.getMessagesByChannelByCompany(user.companyId);


      const queryMetadata = {
        period: {
          start: startDate.toISOString(),
          end: endDate.toISOString(),
          days: periodDays,
          preset: period
        },
        generatedAt: new Date().toISOString(),
        companyId: user.companyId
      };

      res.json({
        overview: {
          conversationsCount,
          contactsCount,
          messagesCount,
          responseRate: Math.round(responseRate * 10) / 10,
          conversationsGrowth: Math.round(conversationsGrowth * 10) / 10,
          contactsGrowth: Math.round(contactsGrowth * 10) / 10,
          messagesGrowth: Math.round(messagesGrowth * 10) / 10,
          responseRateGrowth: Math.round(responseRateGrowth * 10) / 10
        },
        conversationsByDay,
        channelDistribution: channelDistributionData,
        messagesByChannel,
        metadata: queryMetadata
      });
    } catch (error) {
      console.error('Error fetching analytics data:', error);


      if (error instanceof Error) {
        if (error.message.includes('date')) {
          return res.status(400).json({ message: 'Invalid date parameters provided' });
        }
        if (error.message.includes('company')) {
          return res.status(403).json({ message: 'Access denied to company data' });
        }
      }

      res.status(500).json({
        message: 'Failed to fetch analytics data',
        error: process.env.NODE_ENV === 'development' ? (error instanceof Error ? error.message : String(error)) : undefined
      });
    }
  });

  app.get('/api/analytics/export', ensureAuthenticated, async (req: any, res) => {
    try {
      const { period = 'last7days', from, to } = req.query;
      const user = req.user as any;
      if (!user.companyId) {
        return res.status(400).json({ message: 'User must be associated with a company' });
      }

      const exportFormat = parseExportFormat(req.query.format);
      if (!exportFormat) return res.status(400).json({ message: 'Unsupported export format' });

      let startDate = new Date();
      let endDate = new Date();
      if (from && to) {
        startDate = new Date(from);
        endDate = new Date(to);
        if (Number.isNaN(startDate.getTime()) || Number.isNaN(endDate.getTime()) || startDate > endDate) {
          return res.status(400).json({ message: 'Invalid date range' });
        }
      } else {
        const now = new Date();
        switch (period) {
          case 'today':
            startDate.setHours(0, 0, 0, 0);
            endDate.setHours(23, 59, 59, 999);
            break;
          case 'yesterday':
            startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1, 0, 0, 0, 0);
            endDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1, 23, 59, 59, 999);
            break;
          case 'last30days':
          case '7days':
          case '30days':
          case 'last90days':
          case '90days':
            startDate.setDate(startDate.getDate() - Number(String(period).replace(/\D/g, '') || 7));
            break;
          default:
            startDate.setDate(startDate.getDate() - 7);
        }
      }

      const [conversationsCount, contactsCount, messagesCount, channelDistribution, conversationsByDay] = await Promise.all([
        storage.getConversationsCountByCompanyAndDateRange(user.companyId, startDate, endDate),
        storage.getContactsCountByCompanyAndDateRange(user.companyId, startDate, endDate),
        storage.getMessagesCountByCompanyAndDateRange(user.companyId, startDate, endDate),
        storage.getChannelConnectionsByCompany(user.companyId),
        storage.getConversationsByDayByCompanyAndDateRange(user.companyId, startDate, endDate),
      ]);
      const byChannel = channelDistribution.reduce((acc: Record<string, number>, connection) => {
        acc[connection.channelType] = (acc[connection.channelType] ?? 0) + 1;
        return acc;
      }, {});
      const channelTotal = Object.values(byChannel).reduce((sum, count) => sum + count, 0);
      const channelRows = Object.entries(byChannel).map(([channel, count]) => ({
        channel,
        count,
        percentage: channelTotal ? count / channelTotal : 0,
      }));
      const summaryRows = [
        { metric: 'Total Conversations', value: conversationsCount },
        { metric: 'Total Contacts', value: contactsCount },
        { metric: 'Total Messages', value: messagesCount },
      ];
      const dailyRows = conversationsByDay.map((day: any) => ({
        date: day.name || day.date || '',
        whatsappOfficial: day.whatsapp_official || day.whatsappOfficial || 0,
        whatsappUnofficial: day.whatsapp_unofficial || day.whatsappUnofficial || 0,
        messenger: day.messenger || 0,
        instagram: day.instagram || 0,
        total: day.total || 0,
      }));

      await sendTabularExport(res, {
        filename: `analytics-${new Date().toISOString().slice(0, 10)}`,
        format: exportFormat,
        sheets: exportFormat === 'xlsx' ? [
          { name: 'Summary', columns: [
            { key: 'metric', header: 'Metric', width: 28 },
            { key: 'value', header: 'Value', type: 'number', width: 16 },
          ], rows: summaryRows },
          { name: 'Channel Distribution', columns: [
            { key: 'channel', header: 'Channel', width: 24 },
            { key: 'count', header: 'Count', type: 'number', width: 14 },
            { key: 'percentage', header: 'Percentage', type: 'percentage', numberFormat: '0.0%', width: 16 },
          ], rows: channelRows },
          { name: 'Daily Conversations', columns: [
            { key: 'date', header: 'Date', width: 18 },
            { key: 'whatsappOfficial', header: 'WhatsApp Official', type: 'number', width: 20 },
            { key: 'whatsappUnofficial', header: 'WhatsApp Unofficial', type: 'number', width: 22 },
            { key: 'messenger', header: 'Messenger', type: 'number', width: 14 },
            { key: 'instagram', header: 'Instagram', type: 'number', width: 14 },
            { key: 'total', header: 'Total', type: 'number', width: 14 },
          ], rows: dailyRows },
        ] : [{
          name: 'Analytics',
          columns: [
            { key: 'section', header: 'Section', width: 24 },
            { key: 'label', header: 'Metric / Date', width: 28 },
            { key: 'value', header: 'Value', width: 16 },
            { key: 'whatsappOfficial', header: 'WhatsApp Official', width: 20 },
            { key: 'whatsappUnofficial', header: 'WhatsApp Unofficial', width: 22 },
            { key: 'messenger', header: 'Messenger', width: 14 },
            { key: 'instagram', header: 'Instagram', width: 14 },
            { key: 'total', header: 'Total', width: 14 },
          ],
          rows: [
            ...summaryRows.map((row) => ({ section: 'Summary', label: row.metric, value: row.value })),
            ...channelRows.map((row) => ({ section: 'Channel Distribution', label: row.channel, value: row.count })),
            ...dailyRows.map((row) => ({ section: 'Daily Conversations', label: row.date, ...row })),
          ],
        }],
      });

    } catch (error) {
      console.error('Error exporting analytics data:', error);
      if (!res.headersSent) res.status(500).json({ message: 'Failed to export analytics data' });
    }
  });




